def collect_cited_references(text: str) -> list[str]:
    """Return the APA 7 entries for every `(Author, Year)` citation in `text`.

    Scans the narrative for citations that match a known library key,
    deduplicates by key, and returns an alphabetised list of ready-to-
    render APA entries. Unknown citations are silently ignored — callers
    should add them to `_APA_REFERENCE_LIBRARY` if they want them surfaced.
    """
    keys_seen: set[str] = set()
    for citation, key in _CITATION_TO_KEY.items():
        if citation in text and key in _APA_REFERENCE_LIBRARY:
            keys_seen.add(key)
    entries = [_APA_REFERENCE_LIBRARY[k] for k in keys_seen]
    return sorted(entries)


def build_apa_reference_list(text: str, *, always_include: list[str] | None = None) -> list[str]:
    """Build the APA reference list for a publication document.

    - `text`: the narrative body (Methods + Results) that was just rendered;
      every `(Author, Year)` token present in it is included.
    - `always_include`: reference keys that must appear regardless of
      whether they were cited (used for core MFRM references).
    """
    keys_seen: set[str] = set()
    for citation, key in _CITATION_TO_KEY.items():
        if citation in text and key in _APA_REFERENCE_LIBRARY:
            keys_seen.add(key)
    for key in always_include or []:
        if key in _APA_REFERENCE_LIBRARY:
            keys_seen.add(key)
    return sorted(_APA_REFERENCE_LIBRARY[k] for k in keys_seen)


# ---------------------------------------------------------------------------
# Word (.docx) publication document builder
# ---------------------------------------------------------------------------
# Produces a single manuscript-ready Word file containing:
#   - Title + auto-generated abstract
#   - Methods (from generate_method_appendix_text)
#   - Manuscript template (from generate_manuscript_reporting_template)
#   - Embedded figures (Wright map, pathway, scree, category curves)
#   - Embedded core tables (measures, reliability, fit summary)
#   - APA 7 reference list (via build_apa_reference_list)
#
# python-docx is lazy-imported so the app still boots if the package
# is missing (e.g. mid-deploy); the Report tab surfaces an install hint
# instead of crashing.

_PUBLICATION_DOCUMENT_CORE_REFS: list[str] = [
    "Andrich_1978",         # RSM
    "Masters_1982",         # PCM
    "Linacre_1989",         # Many-facet Rasch measurement
    "Linacre_2024",         # Fit interpretation
    "Myford_Wolfe_2003",    # Rater effects I
    "Myford_Wolfe_2004",    # Rater effects II
    "Smith_2002",           # PCA of residuals
    "Wright_Masters_1982",  # Rating scale analysis
]


# ---------------------------------------------------------------------------
# matplotlib fallback for publication figures (v0.2.10-beta)
#
# Problem: kaleido 1.x requires a Chrome / Chromium binary to render
# Plotly figures to PNG. Streamlit Community Cloud does not ship
# Chrome, so `fig_to_png_bytes()` silently returns None there and the
# Publication Document PDF ends up with no plots. Matplotlib is a
# pure-Python rendering path with no browser dependency, so we use it
# as a guaranteed fallback. When Chrome IS available the Plotly path
# is preferred because the interactive-styled Plotly figure is what
# users see on screen.
#
# Each helper below renders one publication figure from the raw data
# in the result / diagnostics dicts (not from the Plotly figure
# object) so it works even when the Plotly build fails.
# ---------------------------------------------------------------------------


def _mpl_safe_import():
    """Import matplotlib.pyplot with the Agg backend. Returns (plt, None) or (None, error_str)."""
    try:
        import matplotlib
        matplotlib.use("Agg", force=False)
        import matplotlib.pyplot as plt
        return plt, None
    except ImportError as exc:
        return None, f"matplotlib not available: {exc}"


def _mpl_fig_to_png_bytes(fig, dpi: int = PUBLICATION_FIGURE_DPI) -> bytes | None:
    """Serialise a matplotlib Figure to PNG bytes and close it."""
    try:
        import io as _io
        buf = _io.BytesIO()
        fig.savefig(buf, format="png", dpi=dpi, bbox_inches="tight")
        return buf.getvalue()
    except Exception:
        return None
    finally:
        try:
            import matplotlib.pyplot as plt
            plt.close(fig)
        except Exception:
            pass


def _mpl_wright_map_png(result: dict, diagnostics: dict) -> bytes | None:
    """Matplotlib Wright map: person abilities (left) vs. facet elements (right)."""
    plt, err = _mpl_safe_import()
    if plt is None:
        return None
    try:
        # Person ability distribution
        facets = result.get("facets", {}) if isinstance(result, dict) else {}
        person_df = facets.get("person") if isinstance(facets, dict) else None
        measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
        if not isinstance(person_df, pd.DataFrame) or person_df.empty:
            return None

        person_est = pd.to_numeric(person_df.get("Estimate"), errors="coerce").dropna()
        if person_est.empty:
            return None

        fig, (ax_l, ax_r) = plt.subplots(
            1, 2, figsize=(10, 6), sharey=True,
            gridspec_kw={"width_ratios": [1, 1.4], "wspace": 0.08},
        )
        # Persons — horizontal histogram
        ax_l.hist(
            person_est.values, bins=20, orientation="horizontal",
            color="#0d7a5a", edgecolor="white", alpha=0.85,
        )
        ax_l.set_title("Persons", fontsize=11)
        ax_l.set_xlabel("Count")
        ax_l.invert_xaxis()
        ax_l.grid(axis="y", alpha=0.25)
        ax_l.axhline(0, color="#666666", linewidth=0.7)

        # Facet elements — scatter with labels
        if isinstance(measures, pd.DataFrame) and not measures.empty:
            facet_col = "Facet" if "Facet" in measures.columns else None
            if facet_col is not None:
                colors = plt.cm.tab10.colors
                facet_names = list(measures[facet_col].astype(str).unique())
                offsets = {name: i for i, name in enumerate(facet_names)}
                for name in facet_names:
                    sub = measures[measures[facet_col].astype(str) == name]
                    y = pd.to_numeric(sub.get("Estimate"), errors="coerce")
                    x = [offsets[name]] * len(sub)
                    color = colors[offsets[name] % len(colors)]
                    ax_r.scatter(x, y, color=color, s=35, alpha=0.8, label=name)
                ax_r.set_xticks(list(offsets.values()))
                ax_r.set_xticklabels(list(offsets.keys()), rotation=25, ha="right")
        ax_r.set_title("Facet elements", fontsize=11)
        ax_r.set_ylabel("Logit measure")
        ax_r.axhline(0, color="#666666", linewidth=0.7)
        ax_r.grid(axis="y", alpha=0.25)

        fig.suptitle("Wright map (person–element targeting)", fontsize=13, y=1.02)
        return _mpl_fig_to_png_bytes(fig)
    except Exception:
        return None


def _mpl_fit_scatter_png(diagnostics: dict) -> bytes | None:
    """Matplotlib fit scatter: Infit (x) vs Outfit (y) with acceptable-zone bands."""
    plt, err = _mpl_safe_import()
    if plt is None:
        return None
    try:
        measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
        if not isinstance(measures, pd.DataFrame) or measures.empty:
            return None
        infit = pd.to_numeric(measures.get("Infit"), errors="coerce")
        outfit = pd.to_numeric(measures.get("Outfit"), errors="coerce")
        mask = infit.notna() & outfit.notna()
        if int(mask.sum()) < 2:
            return None
        infit = infit[mask]
        outfit = outfit[mask]

        fig, ax = plt.subplots(figsize=(7.5, 6))
        # Acceptable zone shading (0.5–1.5 on both axes)
        ax.axhspan(0.5, 1.5, facecolor="#b2dfb8", alpha=0.25, zorder=0)
        ax.axvspan(0.5, 1.5, facecolor="#b2dfb8", alpha=0.25, zorder=0)
        # Reference lines at 1.0 (expected value)
        ax.axhline(1.0, color="#444444", linewidth=0.8, linestyle="--", zorder=1)
        ax.axvline(1.0, color="#444444", linewidth=0.8, linestyle="--", zorder=1)
        # Scatter
        facet_col = "Facet" if "Facet" in measures.columns else None
        if facet_col is not None:
            facets = measures.loc[mask, facet_col].astype(str)
            colors = plt.cm.tab10.colors
            for i, name in enumerate(facets.unique()):
                sel = facets == name
                ax.scatter(
                    infit[sel], outfit[sel],
                    color=colors[i % len(colors)], label=name,
                    alpha=0.8, s=40, edgecolor="white", linewidth=0.5,
                )
            ax.legend(loc="best", fontsize=9, framealpha=0.9)
        else:
            ax.scatter(infit, outfit, color="#0d7a5a", alpha=0.8, s=40)

        ax.set_xlabel("Infit mean-square", fontsize=12)
        ax.set_ylabel("Outfit mean-square", fontsize=12)
        ax.set_title("Fit scatter (Infit vs Outfit)", fontsize=13)
        ax.grid(alpha=0.3)
        ax.set_xlim(max(0, min(infit.min(), 0.4)), max(infit.max() * 1.05, 2.0))
        ax.set_ylim(max(0, min(outfit.min(), 0.4)), max(outfit.max() * 1.05, 2.0))
        return _mpl_fig_to_png_bytes(fig)
    except Exception:
        return None


def _mpl_category_probability_png(result: dict) -> bytes | None:
    """Matplotlib category probability curves across the latent scale."""
    plt, err = _mpl_safe_import()
    if plt is None:
        return None
    try:
        # `build_category_probability_curve_data` is the public helper
        # that returns {"available": bool, "probability": DataFrame, ...}
        builder = globals().get("build_category_probability_curve_data")
        if not callable(builder):
            return None
        curve = builder(result)
        if not isinstance(curve, dict) or not curve.get("available"):
            return None
        prob = curve.get("probability")
        if not isinstance(prob, pd.DataFrame) or prob.empty or "Theta" not in prob.columns:
            return None

        theta = pd.to_numeric(prob["Theta"], errors="coerce").values
        category_cols = [c for c in prob.columns if c not in ("Theta", "Expected")]
        if not category_cols:
            return None

        fig, ax = plt.subplots(figsize=(8, 5.5))
        colors = plt.cm.viridis(np.linspace(0, 0.9, len(category_cols)))
        for i, cname in enumerate(category_cols):
            y = pd.to_numeric(prob[cname], errors="coerce").values
            ax.plot(theta, y, color=colors[i], linewidth=2, label=str(cname))
        ax.set_xlabel("Latent measure θ (logits)", fontsize=12)
        ax.set_ylabel("P(category)", fontsize=12)
        ax.set_title("Category probability curves", fontsize=13)
        ax.grid(alpha=0.3)
        ax.set_ylim(-0.02, 1.02)
        ax.legend(title="Category", loc="best", fontsize=9, framealpha=0.9)
        return _mpl_fig_to_png_bytes(fig)
    except Exception:
        return None


def _mpl_facet_distribution_png(diagnostics: dict) -> bytes | None:
    """Matplotlib box plot of measures within each facet."""
    plt, err = _mpl_safe_import()
    if plt is None:
        return None
    try:
        measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
        if not isinstance(measures, pd.DataFrame) or measures.empty:
            return None
        if "Facet" not in measures.columns or "Estimate" not in measures.columns:
            return None

        pdf = measures.copy()
        pdf["Estimate"] = pd.to_numeric(pdf["Estimate"], errors="coerce")
        pdf = pdf.dropna(subset=["Estimate"])
        if pdf.empty:
            return None

        facet_groups: list[tuple[str, np.ndarray]] = []
        for name in pdf["Facet"].astype(str).unique():
            vals = pdf.loc[pdf["Facet"].astype(str) == name, "Estimate"].values
            if len(vals) >= 1:
                facet_groups.append((name, vals))
        if not facet_groups:
            return None

        fig, ax = plt.subplots(figsize=(8, 5.5))
        labels = [g[0] for g in facet_groups]
        values = [g[1] for g in facet_groups]
        # `tick_labels` replaced the deprecated `labels` kwarg in
        # matplotlib 3.9; fall back to the old name when older versions
        # are installed so we stay compatible with the pinned floor.
        try:
            bp = ax.boxplot(
                values, tick_labels=labels, patch_artist=True, widths=0.55,
                medianprops={"color": "#222222", "linewidth": 1.5},
            )
        except TypeError:
            bp = ax.boxplot(
                values, labels=labels, patch_artist=True, widths=0.55,
                medianprops={"color": "#222222", "linewidth": 1.5},
            )
        colors = plt.cm.tab10.colors
        for i, patch in enumerate(bp["boxes"]):
            patch.set_facecolor(colors[i % len(colors)])
            patch.set_alpha(0.55)
        # Overlay strip-plot of raw values
        for i, (_, vals) in enumerate(facet_groups, start=1):
            jitter = (np.random.default_rng(42 + i).normal(0, 0.05, size=len(vals)))
            ax.scatter(np.full_like(vals, i, dtype=float) + jitter, vals,
                       color="#222222", alpha=0.55, s=12, zorder=3)

        ax.set_ylabel("Logit measure", fontsize=12)
        ax.set_title("Facet element distribution", fontsize=13)
        ax.grid(axis="y", alpha=0.3)
        ax.axhline(0, color="#666666", linewidth=0.7, linestyle="--")
        fig.autofmt_xdate(rotation=20)
        return _mpl_fig_to_png_bytes(fig)
    except Exception:
        return None


def _plotly_or_matplotlib_png(
    plotly_fig,
    matplotlib_fallback,
) -> bytes | None:
    """Try Plotly (kaleido → Chrome) first; fall back to matplotlib.

    The Plotly path produces PNGs styled identically to the on-screen
    figure, so it is preferred when Chrome is available. On Streamlit
    Community Cloud Chrome is typically absent and `fig_to_png_bytes`
    returns None — we then call the matplotlib fallback, which needs
    nothing beyond the raw data and always succeeds.
    """
    if plotly_fig is not None:
        png = fig_to_png_bytes(plotly_fig)
        if png:
            return png
    # matplotlib_fallback is a zero-arg callable that produces bytes
    try:
        return matplotlib_fallback()
    except Exception:
        return None


def _publication_figure_payloads(
    result: dict, diagnostics: dict,
) -> list[tuple[str, str, bytes]]:
    """Render the core publication figures as PNG bytes for Word/PDF embedding.

    Returns a list of (figure_id, caption, png_bytes). Prefers the
    Plotly export (kaleido + Chrome) for parity with the on-screen
    visuals, but falls back to matplotlib when Chrome is unavailable
    — so PDFs / Word docs always have their core figures embedded,
    even on Streamlit Community Cloud.
    """
    out: list[tuple[str, str, bytes]] = []

    # Wright map
    try:
        wright_fig = None
        try:
            wright_fig = _make_wright_map_export_figure(result, diagnostics)
        except Exception:
            pass
        png = _plotly_or_matplotlib_png(
            wright_fig,
            lambda: _mpl_wright_map_png(result, diagnostics),
        )
        if png:
            out.append((
                "wright_map",
                "Wright map aligning person abilities and facet element measures on a common logit scale.",
                png,
            ))
    except Exception:  # pragma: no cover - figure helpers may refuse some inputs
        pass

    # Fit scatter (Infit vs Outfit)
    try:
        fit_fig = None
        measures = diagnostics.get("measures")
        if isinstance(measures, pd.DataFrame) and not measures.empty:
            try:
                fit_fig = _make_fit_scatter_export_figure(measures)
            except Exception:
                pass
        png = _plotly_or_matplotlib_png(
            fit_fig,
            lambda: _mpl_fit_scatter_png(diagnostics),
        )
        if png:
            out.append((
                "fit_scatter",
                "Infit vs Outfit mean-square statistics across facet elements (1.0 = expected).",
                png,
            ))
    except Exception:
        pass

    # Category probability curves
    try:
        cp_figs: dict | None = None
        try:
            cp_figs = _make_category_probability_curve_figures(result)
        except Exception:
            cp_figs = None
        first_plotly = None
        first_name = ""
        if isinstance(cp_figs, dict) and cp_figs:
            first_name, first_plotly = next(iter(cp_figs.items()))
        png = _plotly_or_matplotlib_png(
            first_plotly,
            lambda: _mpl_category_probability_png(result),
        )
        if png:
            label = first_name or "Average"
            out.append((
                f"category_curves_{label}",
                f"Category probability curves — {label}.",
                png,
            ))
    except Exception:
        pass

    # Facet distribution
    try:
        fd_fig = None
        try:
            fd_fig = _make_facet_distribution_export_figure(diagnostics)
        except Exception:
            pass
        png = _plotly_or_matplotlib_png(
            fd_fig,
            lambda: _mpl_facet_distribution_png(diagnostics),
        )
        if png:
            out.append((
                "facet_distribution",
                "Facet distribution of element measures.",
                png,
            ))
    except Exception:
        pass

    return out


def _add_markdown_to_docx(document, markdown_text: str) -> None:
    """Render a minimal subset of markdown (headings, paragraphs, bullets,
    horizontal rules) into a python-docx Document. Anything we don't
    recognise falls through as a plain paragraph."""
    if not markdown_text:
        return
    lines = markdown_text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if not stripped:
            i += 1
            continue
        if stripped.startswith("### "):
            document.add_heading(stripped[4:].strip(), level=3)
        elif stripped.startswith("## "):
            document.add_heading(stripped[3:].strip(), level=2)
        elif stripped.startswith("# "):
            document.add_heading(stripped[2:].strip(), level=1)
        elif stripped.startswith(("- ", "* ")):
            document.add_paragraph(stripped[2:].strip(), style="List Bullet")
        elif stripped == "---":
            document.add_paragraph("").add_run()  # blank spacer
        elif stripped.startswith("|") and "|" in stripped[1:]:
            # Minimal markdown table support: collect contiguous | rows
            table_rows = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                row = [c.strip() for c in lines[i].strip().strip("|").split("|")]
                table_rows.append(row)
                i += 1
            # Drop markdown alignment row (---|---)
            table_rows = [r for r in table_rows if not all(set(c) <= set("-: ") for c in r)]
            if table_rows:
                cols = max(len(r) for r in table_rows)
                tbl = document.add_table(rows=len(table_rows), cols=cols)
                tbl.style = "Light Grid Accent 1"
                for r_idx, row in enumerate(table_rows):
                    for c_idx in range(cols):
                        tbl.cell(r_idx, c_idx).text = row[c_idx] if c_idx < len(row) else ""
            continue  # i already advanced past the table
        else:
            document.add_paragraph(stripped)
        i += 1


def _add_dataframe_to_docx(document, df: "pd.DataFrame", caption: str | None = None) -> None:
    """Render a pandas DataFrame as a Word table (with optional caption above)."""
    if not isinstance(df, pd.DataFrame) or df.empty:
        return
    if caption:
        p = document.add_paragraph()
        run = p.add_run(caption)
        run.italic = True
    # Cap very wide / long tables so the Word file stays reasonable
    display = df.copy()
    if len(display.columns) > 12:
        display = display.iloc[:, :12]
    if len(display) > 60:
        display = display.head(60)
    tbl = document.add_table(rows=len(display) + 1, cols=len(display.columns))
    tbl.style = "Light Grid Accent 1"
    for j, col in enumerate(display.columns):
        tbl.cell(0, j).text = str(col)
    for i_row, (_, row) in enumerate(display.iterrows(), start=1):
        for j, col in enumerate(display.columns):
            value = row[col]
            if isinstance(value, float):
                tbl.cell(i_row, j).text = f"{value:.3f}"
            else:
                tbl.cell(i_row, j).text = str(value)


def build_publication_word_bytes(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> bytes:
    """Build a manuscript-ready Word (.docx) document as bytes.

    Raises RuntimeError if python-docx is unavailable (callers should catch
    and show an install hint). Figure / table embeds that fail are silently
    skipped so the document always assembles.
    """
    try:
        from docx import Document
        from docx.shared import Inches
    except ImportError as exc:
        raise RuntimeError(
            "python-docx is not installed. Add `python-docx>=1.0` to "
            "requirements.txt and reinstall."
        ) from exc
    import io as _io

    document = Document()
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}

    # --- Title + auto-abstract ---
    model_name = str(config.get("model", "MFRM"))
    method_name = str(config.get("method", "estimation"))
    n_obs = prep.get("n_obs", "?")
    n_person = prep.get("n_person", "?")
    facet_names = config.get("facet_names", [])

    document.add_heading("Many-Facet Rasch Measurement analysis", level=0)
    abstract = document.add_paragraph()
    abstract.add_run("Abstract. ").bold = True
    abstract.add_run(
        f"This document reports a {model_name} analysis estimated via {method_name} "
        f"on {n_obs} observations from {n_person} persons across "
        f"{len(facet_names)} facets ({', '.join(map(str, facet_names)) or 'none'}). "
        "The sections below follow the APA 7 reporting layout: exhaustive Methods, "
        "Results with embedded figures and tables, and a references list. "
        "All content is auto-generated from the current analysis configuration; "
        "edit freely for your manuscript."
    )

    # --- Methods (reuse existing narrative generator) ---
    methods_text = ""
    try:
        methods_text = generate_method_appendix_text(result, diagnostics, all_bias_results)
    except Exception:
        methods_text = "# Methods\n\n(Method appendix could not be generated for this run.)"
    _add_markdown_to_docx(document, methods_text)

    # --- Manuscript template (Methods + Results narrative) ---
    document.add_page_break()
    manuscript_text = ""
    try:
        manuscript_text = generate_manuscript_reporting_template(result, diagnostics, all_bias_results)
    except Exception:
        manuscript_text = "# Results\n\n(Manuscript template could not be generated for this run.)"
    _add_markdown_to_docx(document, manuscript_text)

    # --- Core results tables ---
    document.add_heading("Results tables", level=1)
    measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
    if isinstance(measures, pd.DataFrame) and not measures.empty:
        _add_dataframe_to_docx(
            document, measures.round(3),
            caption="Table 1. Element measures, standard errors, and fit statistics.",
        )
    reliability = diagnostics.get("reliability") if isinstance(diagnostics, dict) else None
    if isinstance(reliability, pd.DataFrame) and not reliability.empty:
        _add_dataframe_to_docx(
            document, reliability.round(3),
            caption="Table 2. Reliability and separation by facet.",
        )

    # --- Embedded figures ---
    figures = _publication_figure_payloads(result, diagnostics)
    if figures:
        document.add_heading("Figures", level=1)
        for idx, (fig_id, caption, png) in enumerate(figures, start=1):
            buf = _io.BytesIO(png)
            try:
                document.add_picture(buf, width=Inches(6))
            except Exception:
                continue
            p = document.add_paragraph()
            p.add_run(f"Figure {idx}. {caption}").italic = True

    # --- References ---
    document.add_page_break()
    document.add_heading("References", level=1)
    narrative_for_refs = (methods_text or "") + "\n" + (manuscript_text or "")
    refs = build_apa_reference_list(
        narrative_for_refs,
        always_include=_PUBLICATION_DOCUMENT_CORE_REFS,
    )
    if refs:
        for ref in refs:
            p = document.add_paragraph(ref)
            p.paragraph_format.first_line_indent = Inches(-0.5)
            p.paragraph_format.left_indent = Inches(0.5)
    else:
        document.add_paragraph("(No references cited in the current narrative.)")

    out = _io.BytesIO()
    document.save(out)
    return out.getvalue()


# ---------------------------------------------------------------------------
# PDF publication document builder (reportlab)
# ---------------------------------------------------------------------------
# Same content as the Word builder, rendered as a flowable PDF via
# reportlab's platypus stack. Per the earlier decision the PDF excludes
# the reproducibility code appendix that the Word version carries —
# users who need the code path should use the Word export (or the
# Downloads tab zip).

def _pdf_markdown_to_flowables(markdown_text: str, styles):
    """Convert a minimal subset of markdown into reportlab flowables.

    Handles headings (`#`, `##`, `###`), paragraphs, bullet lists,
    horizontal rules. Markdown tables are rendered as a monospaced
    block for readability (full table styling is reserved for core
    result tables passed via _pdf_dataframe_flowable).
    """
    from reportlab.platypus import Paragraph, Spacer
    flowables = []
    if not markdown_text:
        return flowables
    lines = markdown_text.splitlines()
    for raw in lines:
        line = raw.rstrip()
        if not line.strip():
            flowables.append(Spacer(1, 6))
            continue
        if line.startswith("### "):
            flowables.append(Paragraph(line[4:].strip(), styles["Heading3"]))
        elif line.startswith("## "):
            flowables.append(Paragraph(line[3:].strip(), styles["Heading2"]))
        elif line.startswith("# "):
            flowables.append(Paragraph(line[2:].strip(), styles["Heading1"]))
        elif line.startswith(("- ", "* ")):
            flowables.append(Paragraph(f"• {line[2:].strip()}", styles["BodyText"]))
        elif line.strip() == "---":
            flowables.append(Spacer(1, 10))
        elif line.startswith("|"):
            # Monospaced fallback for markdown tables
            flowables.append(Paragraph(f"<font face='Courier'>{line}</font>", styles["BodyText"]))
        else:
            # Reportlab uses simple HTML-ish markup for inline formatting;
            # escape existing <> so the markdown source doesn't break the parser.
            safe = line.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            flowables.append(Paragraph(safe, styles["BodyText"]))
    return flowables


def _pdf_dataframe_flowable(df: "pd.DataFrame", caption: str | None = None):
    """Render a DataFrame as a reportlab Table flowable."""
    from reportlab.platypus import Paragraph, Spacer, Table, TableStyle
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet

    if not isinstance(df, pd.DataFrame) or df.empty:
        return []
    styles = getSampleStyleSheet()
    display = df.copy()
    if len(display.columns) > 10:
        display = display.iloc[:, :10]
    if len(display) > 50:
        display = display.head(50)
    # Round floats for compactness
    for col in display.columns:
        if pd.api.types.is_float_dtype(display[col]):
            display[col] = display[col].round(3)

    rows = [list(display.columns)]
    for _, row in display.iterrows():
        rows.append([str(v) for v in row.tolist()])
    tbl = Table(rows, repeatRows=1)
    tbl.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#D9E1F2")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.black),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 8),
        ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
    ]))
    out = []
    if caption:
        out.append(Paragraph(f"<i>{caption}</i>", styles["BodyText"]))
        out.append(Spacer(1, 4))
    out.append(tbl)
    out.append(Spacer(1, 10))
    return out


def build_publication_pdf_bytes(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> bytes:
    """Build a manuscript-ready PDF document as bytes.

    Raises RuntimeError if reportlab is unavailable. Figure / table embeds
    that fail are silently skipped so the document always assembles.
    """
    try:
        from reportlab.lib.pagesizes import LETTER
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import inch
        from reportlab.platypus import (
            Image,
            PageBreak,
            Paragraph,
            SimpleDocTemplate,
            Spacer,
        )
    except ImportError as exc:
        raise RuntimeError(
            "reportlab is not installed. Add `reportlab>=4.0` to "
            "requirements.txt and reinstall."
        ) from exc
    import io as _io

    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}

    model_name = str(config.get("model", "MFRM"))
    method_name = str(config.get("method", "estimation"))
    n_obs = prep.get("n_obs", "?")
    n_person = prep.get("n_person", "?")
    facet_names = config.get("facet_names", [])

    buf = _io.BytesIO()
    doc = SimpleDocTemplate(
        buf, pagesize=LETTER,
        topMargin=0.75 * inch, bottomMargin=0.75 * inch,
        leftMargin=0.85 * inch, rightMargin=0.85 * inch,
        title="MFRM publication document",
    )
    styles = getSampleStyleSheet()
    # Custom title style
    styles.add(ParagraphStyle(
        name="DocTitle",
        parent=styles["Title"],
        fontSize=18,
        spaceAfter=12,
    ))

    story: list = []

    # --- Title ---
    story.append(Paragraph("Many-Facet Rasch Measurement analysis", styles["DocTitle"]))
    story.append(Spacer(1, 6))

    # --- Abstract ---
    abstract_text = (
        f"<b>Abstract.</b> This document reports a {model_name} analysis "
        f"estimated via {method_name} on {n_obs} observations from "
        f"{n_person} persons across {len(facet_names)} facets "
        f"({', '.join(map(str, facet_names)) or 'none'}). "
        "Sections below follow the APA 7 reporting layout: exhaustive "
        "Methods, Results with embedded figures and tables, and a "
        "references list. All content is auto-generated from the current "
        "analysis configuration; edit freely for your manuscript."
    )
    story.append(Paragraph(abstract_text, styles["BodyText"]))
    story.append(Spacer(1, 12))

    # --- Methods ---
    methods_text = ""
    try:
        methods_text = generate_method_appendix_text(result, diagnostics, all_bias_results)
    except Exception:
        methods_text = "# Methods\n\n(Method appendix could not be generated for this run.)"
    story.extend(_pdf_markdown_to_flowables(methods_text, styles))

    # --- Manuscript template ---
    story.append(PageBreak())
    manuscript_text = ""
    try:
        manuscript_text = generate_manuscript_reporting_template(result, diagnostics, all_bias_results)
    except Exception:
        manuscript_text = "# Results\n\n(Manuscript template could not be generated for this run.)"
    story.extend(_pdf_markdown_to_flowables(manuscript_text, styles))

    # --- Results tables ---
    story.append(Paragraph("Results tables", styles["Heading1"]))
    measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
    if isinstance(measures, pd.DataFrame) and not measures.empty:
        story.extend(_pdf_dataframe_flowable(
            measures,
            caption="Table 1. Element measures, standard errors, and fit statistics.",
        ))
    reliability = diagnostics.get("reliability") if isinstance(diagnostics, dict) else None
    if isinstance(reliability, pd.DataFrame) and not reliability.empty:
        story.extend(_pdf_dataframe_flowable(
            reliability,
            caption="Table 2. Reliability and separation by facet.",
        ))

    # --- Figures ---
    figures = _publication_figure_payloads(result, diagnostics)
    if figures:
        story.append(PageBreak())
        story.append(Paragraph("Figures", styles["Heading1"]))
        for idx, (fig_id, caption, png) in enumerate(figures, start=1):
            try:
                img_buf = _io.BytesIO(png)
                story.append(Image(img_buf, width=6.0 * inch, height=4.0 * inch, kind="proportional"))
            except Exception:
                continue
            story.append(Paragraph(f"<i>Figure {idx}. {caption}</i>", styles["BodyText"]))
            story.append(Spacer(1, 10))

    # --- References ---
    story.append(PageBreak())
    story.append(Paragraph("References", styles["Heading1"]))
    narrative_for_refs = (methods_text or "") + "\n" + (manuscript_text or "")
    refs = build_apa_reference_list(
        narrative_for_refs,
        always_include=_PUBLICATION_DOCUMENT_CORE_REFS,
    )
    if refs:
        # Hanging-indent style (APA 7)
        ref_style = ParagraphStyle(
            name="APARef",
            parent=styles["BodyText"],
            firstLineIndent=-18,
            leftIndent=18,
            spaceAfter=6,
        )
        for ref in refs:
            safe = ref.replace("&", "&amp;")
            story.append(Paragraph(safe, ref_style))
    else:
        story.append(Paragraph("(No references cited in the current narrative.)", styles["BodyText"]))

    doc.build(story)
    return buf.getvalue()


# ---------------------------------------------------------------------------
# HTML publication document builder (stdlib only)
# ---------------------------------------------------------------------------

def _html_escape(text: str) -> str:
    return (
        text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
    )


def _markdown_to_html(markdown_text: str) -> str:
    """Minimal markdown → HTML converter used by the HTML publication
    document. Handles headings, paragraphs, bullet lists, horizontal
    rules, and markdown tables (pipe-delimited)."""
    if not markdown_text:
        return ""
    lines = markdown_text.splitlines()
    out: list[str] = []
    i = 0
    in_list = False
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if not stripped:
            if in_list:
                out.append("</ul>")
                in_list = False
            i += 1
            continue
        if stripped == "---":
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append("<hr/>")
            i += 1
            continue
        if stripped.startswith("### "):
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append(f"<h3>{_html_escape(stripped[4:].strip())}</h3>")
        elif stripped.startswith("## "):
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append(f"<h2>{_html_escape(stripped[3:].strip())}</h2>")
        elif stripped.startswith("# "):
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append(f"<h1>{_html_escape(stripped[2:].strip())}</h1>")
        elif stripped.startswith(("- ", "* ")):
            if not in_list:
                out.append("<ul>")
                in_list = True
            out.append(f"<li>{_html_escape(stripped[2:].strip())}</li>")
        elif stripped.startswith("|"):
            if in_list:
                out.append("</ul>")
                in_list = False
            rows: list[list[str]] = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                cells = [c.strip() for c in lines[i].strip().strip("|").split("|")]
                rows.append(cells)
                i += 1
            rows = [r for r in rows if not all(set(c) <= set("-: ") for c in r)]
            if rows:
                out.append("<table>")
                for r_idx, row in enumerate(rows):
                    tag = "th" if r_idx == 0 else "td"
                    out.append("<tr>" + "".join(f"<{tag}>{_html_escape(c)}</{tag}>" for c in row) + "</tr>")
                out.append("</table>")
            continue
        else:
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append(f"<p>{_html_escape(stripped)}</p>")
        i += 1
    if in_list:
        out.append("</ul>")
    return "\n".join(out)


_PUBLICATION_HTML_STYLE = """
<style>
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
         max-width: 820px; margin: 2em auto; padding: 0 1em; line-height: 1.55; color: #222; }
  h1 { font-size: 1.9em; border-bottom: 2px solid #1b9e77; padding-bottom: 0.25em; }
  h2 { font-size: 1.4em; color: #1b9e77; margin-top: 1.8em; }
  h3 { font-size: 1.15em; color: #555; }
  table { border-collapse: collapse; margin: 1em 0; font-size: 0.92em; }
  th, td { border: 1px solid #bbb; padding: 4px 8px; text-align: left; }
  th { background: #e9eef5; }
  hr { border: none; border-top: 1px solid #ccc; margin: 1.5em 0; }
  .abstract { background: #f5f7fa; padding: 0.8em 1em; border-left: 4px solid #1b9e77; margin: 1em 0; }
  .figure-caption { font-style: italic; font-size: 0.9em; color: #555; margin: 0.3em 0 1.5em 0; }
  .ref { text-indent: -1.5em; padding-left: 1.5em; margin-bottom: 0.4em; }
</style>
"""


def build_publication_html_bytes(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> bytes:
    """Build a manuscript-ready HTML document as UTF-8 bytes (no JS, no external assets)."""
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    model_name = str(config.get("model", "MFRM"))
    method_name = str(config.get("method", "estimation"))
    n_obs = prep.get("n_obs", "?")
    n_person = prep.get("n_person", "?")
    facet_names = config.get("facet_names", [])

    try:
        methods_text = generate_method_appendix_text(result, diagnostics, all_bias_results)
    except Exception:
        methods_text = "# Methods\n\n(Method appendix could not be generated for this run.)"
    try:
        manuscript_text = generate_manuscript_reporting_template(result, diagnostics, all_bias_results)
    except Exception:
        manuscript_text = "# Results\n\n(Manuscript template could not be generated for this run.)"

    narrative_for_refs = (methods_text or "") + "\n" + (manuscript_text or "")
    refs = build_apa_reference_list(
        narrative_for_refs, always_include=_PUBLICATION_DOCUMENT_CORE_REFS,
    )

    # Tables rendered as HTML via pandas (escape-safe)
    measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
    reliability = diagnostics.get("reliability") if isinstance(diagnostics, dict) else None
    measures_html = ""
    if isinstance(measures, pd.DataFrame) and not measures.empty:
        measures_html = (
            "<h2>Table 1. Element measures, standard errors, and fit statistics</h2>\n"
            + measures.round(3).to_html(index=False, border=0)
        )
    reliability_html = ""
    if isinstance(reliability, pd.DataFrame) and not reliability.empty:
        reliability_html = (
            "<h2>Table 2. Reliability and separation by facet</h2>\n"
            + reliability.round(3).to_html(index=False, border=0)
        )

    # Embed figures as base64 PNG so the HTML stays self-contained
    import base64
    figures = _publication_figure_payloads(result, diagnostics)
    figures_html = ""
    if figures:
        figures_html = "<h2>Figures</h2>\n"
        for idx, (fig_id, caption, png) in enumerate(figures, start=1):
            b64 = base64.b64encode(png).decode("ascii")
            figures_html += (
                f'<figure><img src="data:image/png;base64,{b64}" '
                f'alt="{_html_escape(caption)}" style="max-width:100%;"/>'
                f'<figcaption class="figure-caption">Figure {idx}. {_html_escape(caption)}</figcaption></figure>\n'
            )

    refs_html = ""
    if refs:
        refs_html = "<h2>References</h2>\n" + "\n".join(
            f'<p class="ref">{_html_escape(r)}</p>' for r in refs
        )

    body = f"""
<h1>Many-Facet Rasch Measurement analysis</h1>
<div class="abstract">
  <strong>Abstract.</strong> This document reports a {_html_escape(model_name)} analysis
  estimated via {_html_escape(method_name)} on {n_obs} observations from {n_person}
  persons across {len(facet_names)} facets
  ({_html_escape(', '.join(map(str, facet_names)) or 'none')}).
  The sections below follow the APA 7 reporting layout: exhaustive Methods,
  Results with embedded figures and tables, and a references list.
  All content is auto-generated from the current analysis configuration;
  edit freely for your manuscript.
</div>
{_markdown_to_html(methods_text)}
<hr/>
{_markdown_to_html(manuscript_text)}
{measures_html}
{reliability_html}
{figures_html}
{refs_html}
"""
    html = (
        "<!DOCTYPE html>\n<html lang='en'><head><meta charset='utf-8'/>"
        "<title>MFRM publication document</title>"
        + _PUBLICATION_HTML_STYLE
        + "</head><body>\n" + body + "\n</body></html>"
    )
    return html.encode("utf-8")


# ---------------------------------------------------------------------------
# Report-tab section: Publication Document (Word / PDF / HTML)
# ---------------------------------------------------------------------------

def _render_publication_document_section(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> None:
    """Render the download buttons for the Word / PDF / HTML publication docs."""
    st.subheader("📄 Publication Document")
    st.caption(
        "Download a manuscript-ready document combining the auto-generated "
        "abstract, an exhaustive Methods section, results tables, embedded "
        "figures, and an APA 7 reference list. Choose the format that fits "
        "your workflow: Word for further editing, PDF for sharing, HTML for web."
    )

    # v0.2.10-beta: one-click downloads for all three formats. Each
    # format is built lazily on first entry to this tab and cached in
    # session_state keyed by a fingerprint of the current run; subsequent
    # sidebar reruns reuse the cached bytes so only genuinely new runs
    # trigger a rebuild. The PDF button is promoted to `type="primary"`
    # because the user explicitly asked for the PDF to be the easy path.

    # Fingerprint the current run so cache invalidates only when the
    # underlying results actually change, not on every sidebar rerun.
    try:
        _run_fp = stable_json_fingerprint({
            "config": result.get("config", {}),
            "prep": result.get("prep", {}),
            "summary_len": len(result.get("summary", pd.DataFrame())),
            "measures_len": len(diagnostics.get("measures", pd.DataFrame())),
        })
    except Exception:
        _run_fp = f"no_fp_{id(result)}"

    def _cached_build(
        label: str, kind: str, builder, allow_runtime_error: bool = True,
    ) -> tuple[bytes | None, str | None]:
        """Build document bytes or pull them from session_state cache."""
        cache_key = f"_publication_doc_{kind}_bytes"
        fp_key = f"_publication_doc_{kind}_fp"
        if (
            cache_key in st.session_state
            and st.session_state.get(fp_key) == _run_fp
        ):
            return st.session_state[cache_key], None
        try:
            with st.spinner(f"Building {label}…"):
                data = builder(result, diagnostics, all_bias_results)
            st.session_state[cache_key] = data
            st.session_state[fp_key] = _run_fp
            return data, None
        except RuntimeError as exc:
            if allow_runtime_error:
                return None, f"{label} export unavailable: {exc}"
            raise
        except Exception as exc:  # pragma: no cover
            return None, f"{label} build failed: {exc}"

    col_w, col_p, col_h = st.columns(3)

    with col_w:
        word_bytes, word_err = _cached_build(
            "Word", "word", build_publication_word_bytes,
        )
        if word_bytes is not None:
            st.download_button(
                "⬇ Download Word (.docx)",
                data=word_bytes,
                file_name="mfrm_publication_document.docx",
                mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                key="publication_doc_word_dl",
                use_container_width=True,
                help="Editable manuscript with tables + embedded figures.",
            )
        elif word_err:
            st.caption(f"⚠️ {word_err}")

    with col_p:
        pdf_bytes, pdf_err = _cached_build(
            "PDF", "pdf", build_publication_pdf_bytes,
        )
        if pdf_bytes is not None:
            st.download_button(
                "⬇ Download PDF (with plots)",
                data=pdf_bytes,
                file_name="mfrm_publication_document.pdf",
                mime="application/pdf",
                key="publication_doc_pdf_dl",
                use_container_width=True,
                type="primary",
                help=(
                    "Letter-size PDF with Methods, tables, embedded figures "
                    "(Wright map, Fit scatter, Category probability, Facet "
                    "distribution), and APA 7 references."
                ),
            )
        elif pdf_err:
            st.caption(f"⚠️ {pdf_err}")

    with col_h:
        html_bytes, html_err = _cached_build(
            "HTML", "html", build_publication_html_bytes,
        )
        if html_bytes is not None:
            st.download_button(
                "⬇ Download HTML",
                data=html_bytes,
                file_name="mfrm_publication_document.html",
                mime="text/html",
                key="publication_doc_html_dl",
                use_container_width=True,
                help="Self-contained HTML page (no external assets).",
            )
        elif html_err:
            st.caption(f"⚠️ {html_err}")

    st.caption(
        "💡 All three formats share the same narrative source — content "
        "is identical. Word = editable, PDF = print-ready (with embedded "
        "plots), HTML = self-contained and works offline."
    )


