def show_fit_details_section(
    diagnostics: dict,
    result: dict | None = None,
    all_bias_results: dict | None = None,
) -> None:
    """Detailed fit statistics with misfit flagging and visualizations."""


    st.subheader(t("fit_details.subheader"))
    st.caption(t("fit_details.caption"))

    with st.expander(t("fit_details.guide_expander"), expanded=False):
        st.markdown(t("fit_details.guide_body"))

    # Fit criteria reference (Wright & Linacre, 1994; Linacre, 2002)
    st.markdown(t("fit_details.criteria_table"))

    # Result-aware fit summary
    _fit_summary_callout(diagnostics.get("measures", pd.DataFrame()))

    fit_df = diagnostics.get("fit")
    if not isinstance(fit_df, pd.DataFrame) or fit_df.empty:
        measures = diagnostics.get("measures", pd.DataFrame())
        if not measures.empty and "Infit" in measures.columns:
            fit_df = measures.copy()
        else:
            st.info(t("fit_details.no_fit_info"))
            return

    st.dataframe(fit_df, width="stretch")

    # Misfit flagging
    _show_misfit_flags(fit_df)

    # Fit scatter plot: Infit vs Outfit
    if "Infit" in fit_df.columns and "Outfit" in fit_df.columns:
        _draw_fit_scatter(fit_df)

    # ZSTD distribution
    _draw_zstd_distribution(fit_df)

    # Top misfit elements
    _draw_misfit_ranking(fit_df)
    if isinstance(result, dict):
        st.subheader(t("fit_details.misfit_casebook_subheader"))
        casebook = build_misfit_casebook(result, diagnostics, all_bias_results or {})
        if isinstance(casebook, pd.DataFrame) and not casebook.empty:
            st.dataframe(casebook, width="stretch", hide_index=True)
            st.download_button(
                t("fit_details.misfit_casebook_download_button"),
                data=to_csv_bytes(casebook),
                file_name="mfrm_misfit_casebook.csv",
                mime="text/csv",
                key="dl_misfit_casebook_fit_tab",
            )
    show_marginal_fit_section(diagnostics)


def _marginal_scope_label(row: pd.Series) -> str:
    """Compact label for marginal diagnostic rows."""
    if "FacetA" in row.index and pd.notna(row.get("FacetA", np.nan)):
        return (
            f"{row.get('FacetA')}:{row.get('LevelA')} x "
            f"{row.get('FacetB')}:{row.get('LevelB')}"
        )
    if "Facet" in row.index and pd.notna(row.get("Facet", np.nan)):
        return f"{row.get('Facet')}:{row.get('Level')}"
    return str(row.get("Scope", "Overall"))


def _prepare_marginal_plot_frame(summary: pd.DataFrame, top_n: int = 25) -> pd.DataFrame:
    if not isinstance(summary, pd.DataFrame) or summary.empty or "MaxAbsStdResidual" not in summary.columns:
        return pd.DataFrame()
    plot_df = summary.copy()
    plot_df["MaxAbsStdResidual"] = pd.to_numeric(plot_df["MaxAbsStdResidual"], errors="coerce")
    plot_df["p"] = pd.to_numeric(plot_df.get("p", pd.Series(np.nan, index=plot_df.index)), errors="coerce")
    plot_df = plot_df.dropna(subset=["MaxAbsStdResidual"])
    if plot_df.empty:
        return pd.DataFrame()
    plot_df["_Label"] = plot_df.apply(_marginal_scope_label, axis=1)
    plot_df["_StatusOrder"] = plot_df.get("Status", pd.Series("OK", index=plot_df.index)).map({"Review": 0, "OK": 1}).fillna(2)
    plot_df = plot_df.sort_values(
        ["_StatusOrder", "MaxAbsStdResidual", "p"],
        ascending=[True, False, True],
    ).head(int(top_n))
    return plot_df


def _make_marginal_summary_figure(summary: pd.DataFrame, title: str, top_n: int = 25):
    plot_df = _prepare_marginal_plot_frame(summary, top_n=top_n)
    if plot_df.empty:
        return None
    colors = plot_df.get("Status", pd.Series("OK", index=plot_df.index)).map({
        "Review": "#d95f02",
        "OK": "#1b9e77",
    }).fillna("#7570b3")
    custom = np.column_stack([
        plot_df.get("Status", pd.Series("", index=plot_df.index)).astype(str).to_numpy(),
        plot_df["p"].to_numpy(),
        pd.to_numeric(plot_df.get("Rows", pd.Series(np.nan, index=plot_df.index)), errors="coerce").to_numpy(),
    ])
    fig = go.Figure(go.Bar(
        x=plot_df["MaxAbsStdResidual"],
        y=plot_df["_Label"],
        orientation="h",
        marker_color=colors,
        customdata=custom,
        hovertemplate=(
            "%{y}<br>Max |Std residual|=%{x:.2f}"
            "<br>Status=%{customdata[0]}"
            "<br>p=%{customdata[1]:.3g}"
            "<br>Rows=%{customdata[2]:.0f}<extra></extra>"
        ),
    ))
    fig.add_vline(x=3.0, line_dash="dash", line_color="#d62728", line_width=0.8,
                  annotation_text="review >= 3")
    fig.update_layout(
        title=title,
        xaxis_title="Max |standardized observed-expected residual|",
        yaxis=dict(autorange="reversed"),
        height=max(340, 26 * len(plot_df) + 130),
        template="plotly_white",
        showlegend=False,
        margin=_readable_plot_margins(y_labels=plot_df["_Label"].astype(str).tolist(), base_left=130),
    )
    labels_full = plot_df["_Label"].astype(str).tolist()
    fig.update_yaxes(
        tickmode="array",
        tickvals=labels_full,
        ticktext=_compact_label_list(labels_full, max_chars=42),
        automargin=True,
        tickfont=dict(size=9 if len(labels_full) > 20 else 10),
    )
    return fig


def _make_marginal_heatmap_figure(
    counts: pd.DataFrame,
    title: str,
    top_labels: list[str] | None = None,
    top_n: int = 25,
):
    required = {"Category", "StdResidual"}
    if not isinstance(counts, pd.DataFrame) or counts.empty or not required.issubset(counts.columns):
        return None
    plot_df = counts.copy()
    plot_df["StdResidual"] = pd.to_numeric(plot_df["StdResidual"], errors="coerce")
    plot_df = plot_df.dropna(subset=["StdResidual"])
    if plot_df.empty:
        return None
    plot_df["_Label"] = plot_df.apply(_marginal_scope_label, axis=1)
    if top_labels:
        plot_df = plot_df[plot_df["_Label"].isin(top_labels)]
    else:
        top_labels = (
            plot_df.groupby("_Label")["StdResidual"]
            .apply(lambda s: float(np.nanmax(np.abs(s))))
            .sort_values(ascending=False)
            .head(int(top_n))
            .index.tolist()
        )
        plot_df = plot_df[plot_df["_Label"].isin(top_labels)]
    if plot_df.empty:
        return None
    plot_df["Category"] = plot_df["Category"].astype(str)
    heat = plot_df.pivot_table(
        index="_Label",
        columns="Category",
        values="StdResidual",
        aggfunc="mean",
        observed=False,
    )
    heat = heat.reindex([label for label in top_labels if label in heat.index])
    if heat.empty:
        return None
    compacted = len(heat.index) < plot_df["_Label"].nunique()
    finite = np.asarray(heat.to_numpy(dtype=float))
    zlim = float(np.nanmax(np.abs(finite))) if np.isfinite(finite).any() else 3.0
    zlim = max(3.0, min(zlim, 8.0))
    x_labels_full = [str(c) for c in heat.columns]
    y_labels_full = [str(r) for r in heat.index]
    fig = go.Figure(data=go.Heatmap(
        z=heat.to_numpy(dtype=float),
        x=x_labels_full,
        y=y_labels_full,
        zmid=0,
        zmin=-zlim,
        zmax=zlim,
        colorscale=[
            [0.0, "#2166ac"],
            [0.5, "#f7f7f7"],
            [1.0, "#b2182b"],
        ],
        colorbar=dict(title="Std residual"),
        hovertemplate="%{y}<br>Category=%{x}<br>Std residual=%{z:.2f}<extra></extra>",
    ))
    fig.update_layout(
        title=title + (" (top residual rows)" if compacted else ""),
        xaxis_title="Score category",
        yaxis_title="Marginal row",
        height=max(340, 26 * len(heat.index) + 130),
        template="plotly_white",
        margin=_readable_plot_margins(y_labels=y_labels_full, x_labels=x_labels_full, base_left=130, base_bottom=70),
    )
    fig.update_xaxes(
        tickmode="array",
        tickvals=x_labels_full,
        ticktext=_compact_label_list(x_labels_full, max_chars=20),
        automargin=True,
    )
    fig.update_yaxes(
        tickmode="array",
        tickvals=y_labels_full,
        ticktext=_compact_label_list(y_labels_full, max_chars=42),
        automargin=True,
        tickfont=dict(size=9 if len(y_labels_full) > 20 else 10),
    )
    return fig


def _make_wright_map_export_figure(
    person_tbl: pd.DataFrame,
    facet_tbl: pd.DataFrame,
    step_tbl: pd.DataFrame | None = None,
):
    person_est = pd.to_numeric(
        person_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce",
    ).dropna() if isinstance(person_tbl, pd.DataFrame) else pd.Series(dtype=float)
    if person_est.empty:
        return None
    facet_est = facet_tbl.copy() if isinstance(facet_tbl, pd.DataFrame) else pd.DataFrame()
    if "Estimate" in facet_est.columns:
        facet_est["Estimate"] = pd.to_numeric(facet_est["Estimate"], errors="coerce")
        facet_est = facet_est.dropna(subset=["Estimate"])
    facet_names = list(facet_est["Facet"].unique()) if "Facet" in facet_est.columns and not facet_est.empty else []
    max_elements_per_facet = int(facet_est.groupby("Facet").size().max()) if facet_names else 0

    fig = make_subplots(
        rows=1,
        cols=2,
        column_widths=[0.32, 0.68],
        shared_yaxes=True,
        subplot_titles=["Persons", "Facet and threshold locations"],
    )
    fig.add_trace(
        go.Histogram(
            y=person_est.values,
            nbinsy=30,
            marker_color="#9e9e9e",
            name="Persons",
            showlegend=False,
            hovertemplate="n=%{x}<br>Logit=%{y:.2f}<extra></extra>",
        ),
        row=1,
        col=1,
    )
    fig.update_xaxes(autorange="reversed", title_text="Count", row=1, col=1)
    colors = px.colors.qualitative.Set2
    for i, fname in enumerate(facet_names):
        fdata = facet_est[facet_est["Facet"] == fname]
        full_labels = (
            fdata["Level"].astype(str).to_numpy()
            if "Level" in fdata.columns else np.array([str(idx) for idx in fdata.index])
        )
        fig.add_trace(
            go.Scatter(
                x=[fname] * len(fdata),
                y=fdata["Estimate"].to_numpy(),
                mode="markers",
                marker=dict(size=8, color=colors[i % len(colors)], line=dict(width=0.4, color="#333333")),
                name=str(fname),
                customdata=np.column_stack([full_labels, np.repeat(fname, len(fdata))]),
                hovertemplate="%{customdata[1]}: %{customdata[0]}<br>Logit=%{y:.2f}<extra></extra>",
            ),
            row=1,
            col=2,
        )
    if isinstance(step_tbl, pd.DataFrame) and not step_tbl.empty:
        step_vals = pd.to_numeric(step_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna()
        for sv in step_vals:
            fig.add_hline(y=float(sv), line_dash="dot", line_color="#777777", line_width=0.7, row=1, col=2)
    fig.update_yaxes(title_text="Logit scale", row=1, col=1)
    facet_tick_angle = -30 if len(facet_names) > 4 or max((len(str(v)) for v in facet_names), default=0) > 12 else 0
    fig.update_xaxes(tickangle=facet_tick_angle, automargin=True, row=1, col=2)
    fig.update_layout(
        title="Wright map",
        height=max(500, 22 * max_elements_per_facet + 210),
        template="plotly_white",
        hovermode="closest",
        margin=_readable_plot_margins(x_labels=[str(v) for v in facet_names], base_left=95, base_bottom=95),
    )
    return fig


