def external_simulation_template_scripts() -> dict[str, str]:
    """Return sanitized Python/R/Julia templates for external validation handoff."""
    readme = """# External Simulation Validation Templates

These templates are sanitized handoff scripts. They do not contain raw data,
absolute paths, package-cache paths, or personal machine
names.

Use them only after creating an anonymized long-format CSV. Set paths through
environment variables instead of editing machine-specific absolute paths into the scripts.

Required environment variables:
- `MFRM_INPUT_CSV`: path to the anonymized long-format CSV.
- `MFRM_OUTPUT_DIR`: output folder for generated validation artifacts.
- `MFRM_PERSON_COL`: person identifier column, default `Person`.
- `MFRM_SCORE_COL`: score column, default `Score`.
- `MFRM_FACET_COLS`: comma-separated facet columns, default `Rater,Criteria,Region`.

Examples:

```bash
MFRM_INPUT_CSV=writing_long_anonymized.csv \\
MFRM_OUTPUT_DIR=validation_outputs/python \\
MFRM_FACET_COLS=Rater,Criteria,Region \\
python simulation_validation_python_template.py
```

```bash
MFRM_INPUT_CSV=writing_long_anonymized.csv \\
MFRM_OUTPUT_DIR=validation_outputs/r \\
Rscript simulation_validation_r_template.R
```

```bash
MFRM_INPUT_CSV=writing_long_anonymized.csv \\
MFRM_OUTPUT_DIR=validation_outputs/julia \\
julia simulation_validation_julia_template.jl
```

The Python template can import this public app (`streamlit_app.py`) when it is
on `PYTHONPATH` or in the current directory. The R and Julia templates run data
audits by default and only attempt optional engine refits when a local package
or engine file is explicitly supplied through an environment variable.
"""

    python_template = r"""#!/usr/bin/env python3
# Sanitized external Simulation validation template for the MFRM Streamlit app.
# No machine-specific absolute paths or raw data are embedded. Configure by environment.

from __future__ import annotations

import importlib.util
import os
import sys
import time
from pathlib import Path

import pandas as pd


INPUT_CSV = Path(os.environ.get("MFRM_INPUT_CSV", "input_long.csv")).expanduser()
OUTPUT_DIR = Path(os.environ.get("MFRM_OUTPUT_DIR", "validation_outputs/python")).expanduser()
PERSON_COL = os.environ.get("MFRM_PERSON_COL", "Person")
SCORE_COL = os.environ.get("MFRM_SCORE_COL", "Score")
FACET_COLS = [x.strip() for x in os.environ.get("MFRM_FACET_COLS", "Rater,Criteria,Region").split(",") if x.strip()]
MODEL = os.environ.get("MFRM_MODEL", "RSM")
METHOD = os.environ.get("MFRM_METHOD", "JMLE")
STEP_FACET = os.environ.get("MFRM_STEP_FACET") or None
SLOPE_FACET = os.environ.get("MFRM_SLOPE_FACET") or None
MAXIT = int(os.environ.get("MFRM_MAXIT", "250"))
RELTOL = float(os.environ.get("MFRM_RELTOL", "5e-5"))
ENGINE_PATH = os.environ.get("MFRM_PY_ENGINE_PATH", "")


def load_engine():
    if ENGINE_PATH:
        path = Path(ENGINE_PATH).expanduser().resolve()
        spec = importlib.util.spec_from_file_location("mfrm_python_engine", path)
        if spec is None or spec.loader is None:
            raise RuntimeError(f"Could not load Python engine from {path}")
        module = importlib.util.module_from_spec(spec)
        sys.modules["mfrm_python_engine"] = module
        spec.loader.exec_module(module)
        return module
    try:
        import streamlit_app as app_engine
    except ImportError as exc:
        raise RuntimeError(
            "streamlit_app.py is not importable. Run this from the app folder, "
            "set PYTHONPATH to the app folder, or set MFRM_PY_ENGINE_PATH."
        ) from exc
    return app_engine


def data_audit(df: pd.DataFrame) -> pd.DataFrame:
    missing_cols = [c for c in [PERSON_COL, SCORE_COL, *FACET_COLS] if c not in df.columns]
    rows = [
        {"Check": "input_csv", "Value": str(INPUT_CSV), "Status": "ok" if INPUT_CSV.exists() else "missing"},
        {"Check": "n_rows", "Value": len(df), "Status": "ok" if len(df) > 0 else "empty"},
        {"Check": "person_col", "Value": PERSON_COL, "Status": "ok" if PERSON_COL in df.columns else "missing"},
        {"Check": "score_col", "Value": SCORE_COL, "Status": "ok" if SCORE_COL in df.columns else "missing"},
        {"Check": "facet_cols", "Value": ",".join(FACET_COLS), "Status": "ok" if not missing_cols else "missing:" + ",".join(missing_cols)},
    ]
    if SCORE_COL in df.columns and len(df) > 0:
        score = pd.to_numeric(df[SCORE_COL], errors="coerce")
        rows.extend([
            {"Check": "score_min", "Value": score.min(), "Status": "ok"},
            {"Check": "score_max", "Value": score.max(), "Status": "ok"},
            {"Check": "score_missing", "Value": int(score.isna().sum()), "Status": "review" if score.isna().any() else "ok"},
            {"Check": "observed_categories", "Value": ",".join(map(str, sorted(score.dropna().unique()))), "Status": "ok"},
        ])
    return pd.DataFrame(rows)


def write_frame(name: str, frame) -> None:
    if isinstance(frame, pd.DataFrame) and not frame.empty:
        frame.to_csv(OUTPUT_DIR / name, index=False)


def main() -> int:
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    status_rows = []
    if not INPUT_CSV.exists():
        pd.DataFrame([{"Status": "error", "Detail": f"Input CSV not found: {INPUT_CSV}"}]).to_csv(
            OUTPUT_DIR / "python_template_status.csv", index=False
        )
        return 1

    df = pd.read_csv(INPUT_CSV)
    audit = data_audit(df)
    audit.to_csv(OUTPUT_DIR / "python_data_audit.csv", index=False)
    if audit["Status"].astype(str).str.startswith("missing").any() or len(df) == 0:
        pd.DataFrame([{"Status": "error", "Detail": "Required columns or rows are missing. See python_data_audit.csv."}]).to_csv(
            OUTPUT_DIR / "python_template_status.csv", index=False
        )
        return 1

    engine = load_engine()
    t0 = time.time()
    try:
        result = engine.mfrm_estimate(
            df,
            person_col=PERSON_COL,
            facet_cols=FACET_COLS,
            score_col=SCORE_COL,
            model=MODEL,
            method=METHOD,
            step_facet=STEP_FACET,
            slope_facet=SLOPE_FACET,
            maxit=MAXIT,
            reltol=RELTOL,
        )
        elapsed = time.time() - t0
        diagnostics = {}
        if hasattr(engine, "mfrm_diagnostics"):
            diagnostics = engine.mfrm_diagnostics(result, compute_pca=False, compute_marginal=False)
        summary = result.get("summary", pd.DataFrame()).copy()
        if not summary.empty:
            summary["TemplateElapsedSeconds"] = elapsed
            summary["TemplateEngine"] = "Python"
        write_frame("python_summary.csv", summary)
        write_frame("python_convergence.csv", result.get("convergence", pd.DataFrame()))
        facets = result.get("facets", {}) if isinstance(result, dict) else {}
        write_frame("python_person_measures.csv", facets.get("person", pd.DataFrame()) if isinstance(facets, dict) else pd.DataFrame())
        write_frame("python_facet_measures.csv", facets.get("others", pd.DataFrame()) if isinstance(facets, dict) else pd.DataFrame())
        write_frame("python_steps.csv", result.get("steps", pd.DataFrame()))
        write_frame("python_fit_statistics.csv", diagnostics.get("fit", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame())
        status_rows.append({"Status": "ok", "Detail": "Python validation refit completed.", "ElapsedSeconds": elapsed})
    except Exception as exc:
        status_rows.append({"Status": "error", "Detail": str(exc), "ElapsedSeconds": time.time() - t0})

    pd.DataFrame(status_rows).to_csv(OUTPUT_DIR / "python_template_status.csv", index=False)
    return 0 if status_rows and status_rows[-1]["Status"] == "ok" else 1


if __name__ == "__main__":
    raise SystemExit(main())
"""

    r_template = r"""#!/usr/bin/env Rscript
# Sanitized external Simulation validation template for optional R/mfrmr checks.
# No machine-specific absolute paths or raw data are embedded. Configure by environment.

input_csv <- Sys.getenv("MFRM_INPUT_CSV", "input_long.csv")
output_dir <- Sys.getenv("MFRM_OUTPUT_DIR", "validation_outputs/r")
person_col <- Sys.getenv("MFRM_PERSON_COL", "Person")
score_col <- Sys.getenv("MFRM_SCORE_COL", "Score")
facet_cols <- strsplit(Sys.getenv("MFRM_FACET_COLS", "Rater,Criteria,Region"), ",", fixed = TRUE)[[1]]
facet_cols <- trimws(facet_cols[nzchar(trimws(facet_cols))])
model <- Sys.getenv("MFRM_MODEL", "RSM")
method <- Sys.getenv("MFRM_METHOD", "JMLE")
maxit <- as.integer(Sys.getenv("MFRM_MAXIT", "250"))
reltol <- as.numeric(Sys.getenv("MFRM_RELTOL", "5e-5"))
r_source <- Sys.getenv("MFRM_R_SOURCE", "")

dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)

write_status <- function(status, detail) {
  write.csv(
    data.frame(Status = status, Detail = detail, stringsAsFactors = FALSE),
    file.path(output_dir, "r_template_status.csv"),
    row.names = FALSE
  )
}

if (!file.exists(input_csv)) {
  write_status("error", paste("Input CSV not found:", input_csv))
  quit(status = 1)
}

dat <- read.csv(input_csv, stringsAsFactors = FALSE, check.names = FALSE)
required_cols <- c(person_col, score_col, facet_cols)
missing_cols <- setdiff(required_cols, names(dat))

audit <- data.frame(
  Check = c("input_csv", "n_rows", "person_col", "score_col", "facet_cols"),
  Value = c(input_csv, nrow(dat), person_col, score_col, paste(facet_cols, collapse = ",")),
  Status = c(
    "ok",
    ifelse(nrow(dat) > 0, "ok", "empty"),
    ifelse(person_col %in% names(dat), "ok", "missing"),
    ifelse(score_col %in% names(dat), "ok", "missing"),
    ifelse(length(missing_cols) == 0, "ok", paste("missing", paste(missing_cols, collapse = ",")))
  ),
  stringsAsFactors = FALSE
)
write.csv(audit, file.path(output_dir, "r_data_audit.csv"), row.names = FALSE)

if (length(missing_cols) > 0 || nrow(dat) == 0) {
  write_status("error", "Required columns or rows are missing. See r_data_audit.csv.")
  quit(status = 1)
}

category_counts <- as.data.frame(table(dat[[score_col]], useNA = "ifany"), stringsAsFactors = FALSE)
names(category_counts) <- c("Score", "N")
write.csv(category_counts, file.path(output_dir, "r_category_counts.csv"), row.names = FALSE)

facet_counts <- do.call(
  rbind,
  lapply(facet_cols, function(fc) {
    out <- as.data.frame(table(dat[[fc]], useNA = "ifany"), stringsAsFactors = FALSE)
    names(out) <- c("Level", "N")
    out$Facet <- fc
    out[, c("Facet", "Level", "N")]
  })
)
write.csv(facet_counts, file.path(output_dir, "r_facet_counts.csv"), row.names = FALSE)

if (nzchar(r_source)) {
  source(r_source)
}

fit_fun <- NULL
if (exists("fit_mfrm", mode = "function")) {
  fit_fun <- get("fit_mfrm")
} else if (requireNamespace("mfrmr", quietly = TRUE) && exists("fit_mfrm", where = asNamespace("mfrmr"), inherits = FALSE)) {
  fit_fun <- get("fit_mfrm", envir = asNamespace("mfrmr"))
}

if (is.null(fit_fun)) {
  write_status("audit_only", "No fit_mfrm() function found. Data audit files were written; set MFRM_R_SOURCE or install/load mfrmr for an optional refit.")
  quit(status = 0)
}

t0 <- proc.time()[["elapsed"]]
fit <- tryCatch(
  fit_fun(
    data = dat,
    person_col = person_col,
    facet_cols = facet_cols,
    score_col = score_col,
    model = model,
    method = method,
    maxit = maxit,
    reltol = reltol
  ),
  error = function(e) e
)
elapsed <- proc.time()[["elapsed"]] - t0

if (inherits(fit, "error")) {
  write_status("error", conditionMessage(fit))
  quit(status = 1)
}

summary_out <- data.frame(
  model = model,
  method = method,
  n_rows = nrow(dat),
  n_persons = length(unique(dat[[person_col]])),
  elapsed_sec = elapsed,
  stringsAsFactors = FALSE
)
write.csv(summary_out, file.path(output_dir, "r_mfrmr_summary.csv"), row.names = FALSE)
saveRDS(fit, file.path(output_dir, "r_mfrmr_fit.rds"))
write_status("ok", "R optional mfrmr refit completed. Review parameterization before comparing with Python.")
"""

    julia_template = r"""#!/usr/bin/env julia
# Sanitized external Simulation validation template for optional Julia checks.
# No machine-specific absolute paths, sysimage paths, or raw data are embedded. Configure by environment.

using CSV
using DataFrames
using Statistics

input_csv = get(ENV, "MFRM_INPUT_CSV", "input_long.csv")
output_dir = get(ENV, "MFRM_OUTPUT_DIR", "validation_outputs/julia")
person_col = Symbol(get(ENV, "MFRM_PERSON_COL", "Person"))
score_col = Symbol(get(ENV, "MFRM_SCORE_COL", "Score"))
facet_cols = Symbol.(strip.(split(get(ENV, "MFRM_FACET_COLS", "Rater,Criteria,Region"), ",")))
model = get(ENV, "MFRM_MODEL", "RSM")
method = get(ENV, "MFRM_METHOD", "JMLE")
maxit = parse(Int, get(ENV, "MFRM_MAXIT", "250"))
reltol = parse(Float64, get(ENV, "MFRM_RELTOL", "5e-5"))
engine_path = get(ENV, "MFRM_JULIA_ENGINE_PATH", "")

mkpath(output_dir)

function write_status(status::AbstractString, detail::AbstractString)
    CSV.write(joinpath(output_dir, "julia_template_status.csv"), DataFrame(Status=[status], Detail=[detail]))
end

if !isfile(input_csv)
    write_status("error", "Input CSV not found: $(input_csv)")
    exit(1)
end

dat = CSV.read(input_csv, DataFrame)
required_cols = vcat([person_col, score_col], facet_cols)
missing_cols = [String(c) for c in required_cols if !(String(c) in names(dat))]
audit = DataFrame(
    Check = ["input_csv", "n_rows", "person_col", "score_col", "facet_cols"],
    Value = [input_csv, string(nrow(dat)), String(person_col), String(score_col), join(String.(facet_cols), ",")],
    Status = [
        "ok",
        nrow(dat) > 0 ? "ok" : "empty",
        String(person_col) in names(dat) ? "ok" : "missing",
        String(score_col) in names(dat) ? "ok" : "missing",
        isempty(missing_cols) ? "ok" : "missing:" * join(missing_cols, ",")
    ],
)
CSV.write(joinpath(output_dir, "julia_data_audit.csv"), audit)

if !isempty(missing_cols) || nrow(dat) == 0
    write_status("error", "Required columns or rows are missing. See julia_data_audit.csv.")
    exit(1)
end

category_counts = combine(groupby(dat, score_col), nrow => :N)
CSV.write(joinpath(output_dir, "julia_category_counts.csv"), category_counts)

facet_counts = DataFrame(Facet=String[], Level=String[], N=Int[])
for fc in facet_cols
    counts = combine(groupby(dat, fc), nrow => :N)
    append!(facet_counts, DataFrame(Facet=fill(String(fc), nrow(counts)), Level=string.(counts[!, fc]), N=counts.N))
end
CSV.write(joinpath(output_dir, "julia_facet_counts.csv"), facet_counts)

if isempty(engine_path)
    write_status("audit_only", "No Julia engine supplied. Data audit files were written; set MFRM_JULIA_ENGINE_PATH for an optional refit.")
    exit(0)
end

include(engine_path)
if !isdefined(Main, :mfrm_estimate)
    write_status("error", "MFRM_JULIA_ENGINE_PATH did not define mfrm_estimate().")
    exit(1)
end

t0 = time()
try
    result = mfrm_estimate(
        dat;
        person_col=person_col,
        facet_cols=facet_cols,
        score_col=score_col,
        model=model,
        method=method,
        maxit=maxit,
        reltol=reltol,
    )
    elapsed = time() - t0
    sm = result.summary
    summary_df = DataFrame(
        model=[model],
        method=[method],
        n_rows=[nrow(dat)],
        n_persons=[length(unique(dat[!, person_col]))],
        elapsed_sec=[elapsed],
        loglik=[haskey(sm, "LogLik") ? Float64(sm["LogLik"]) : missing],
        converged=[haskey(sm, "Converged") ? Bool(sm["Converged"]) : missing],
    )
    CSV.write(joinpath(output_dir, "julia_summary.csv"), summary_df)
    CSV.write(joinpath(output_dir, "julia_person_measures.csv"), result.person)
    CSV.write(joinpath(output_dir, "julia_facet_measures.csv"), result.facets)
    CSV.write(joinpath(output_dir, "julia_steps.csv"), result.steps)
    if isdefined(Main, :diagnose_mfrm)
        diag = diagnose_mfrm(result, dat; person_col=person_col, facet_cols=facet_cols, score_col=score_col)
        CSV.write(joinpath(output_dir, "julia_measures.csv"), diag.measures)
        CSV.write(joinpath(output_dir, "julia_reliability.csv"), diag.reliability)
    end
    write_status("ok", "Julia optional refit completed. Review parameterization before comparing with Python.")
catch err
    write_status("error", sprint(showerror, err))
    exit(1)
end
"""

    return {
        "README_external_simulation_templates.md": readme,
        "simulation_validation_python_template.py": python_template,
        "simulation_validation_r_template.R": r_template,
        "simulation_validation_julia_template.jl": julia_template,
    }


# ---------------------------------------------------------------------------
# Phase 4-7: Multi-format downloads
# ---------------------------------------------------------------------------

def _render_downloads(
    result: dict,
    diagnostics: dict,
    report_tables: dict,
    scorefile: pd.DataFrame,
    residuals: pd.DataFrame,
    bias_results: dict | None = None,
    all_bias_results: dict | None = None,
    generate_figures: bool = True,
) -> None:
    """Download section with sub-tabs: Data Tables, Figures, Scripts."""
    st.subheader("Downloads")
    st.caption(
        "All analysis outputs organized for download. Use the ZIP buttons for "
        "one-click bundled downloads, or expand individual items below."
    )

    # Prominent cross-reference: the publication-ready Word / PDF / HTML
    # export lives under Report → 💾 Exports → 📄 Publication Document.
    # Users who open Downloads tab expecting a manuscript file should be
    # pointed there explicitly.
    with st.container(border=True):
        st.markdown(
            "📄 **Looking for a manuscript-ready Word, PDF, or HTML document?** "
            "The single-file Publication Document (abstract + Methods + Results + "
            "figures + APA 7 references) lives under "
            "**Report → 💾 Exports → 📄 Publication Document**. "
            "This Downloads tab hosts the underlying data tables, figures, "
            "and reproducibility scripts instead."
        )

    dl_tabs = st.tabs(["Data Tables", "Figures", "Scripts & Config"])

    # ---- Collect all data frames ----
    summary = result.get("summary", pd.DataFrame())
    measures_dl = diagnostics.get("measures", pd.DataFrame())
    reliability_dl = diagnostics.get("reliability", pd.DataFrame())
    steps_dl = result.get("steps", pd.DataFrame())
    if not isinstance(steps_dl, pd.DataFrame):
        steps_dl = pd.DataFrame()
    slopes_dl = result.get("slopes", pd.DataFrame())
    if not isinstance(slopes_dl, pd.DataFrame):
        slopes_dl = pd.DataFrame()
    fit_dl = diagnostics.get("fit", pd.DataFrame())
    if not isinstance(fit_dl, pd.DataFrame):
        fit_dl = pd.DataFrame()

    all_frames: dict[str, pd.DataFrame] = {}
    if not summary.empty:
        all_frames["summary"] = summary
    likelihood_info_dl = result.get("likelihood_information", pd.DataFrame())
    if not isinstance(likelihood_info_dl, pd.DataFrame) or likelihood_info_dl.empty:
        likelihood_info_dl = build_likelihood_information_criteria(result)
    if isinstance(likelihood_info_dl, pd.DataFrame) and not likelihood_info_dl.empty:
        all_frames["likelihood_information_criteria"] = likelihood_info_dl
    regularization_dl = result.get("regularization", {})
    if isinstance(regularization_dl, dict):
        reg_settings_dl = regularization_dl.get("settings", pd.DataFrame())
        reg_audit_dl = regularization_dl.get("audit", pd.DataFrame())
        reg_penalty_dl = regularization_dl.get("penalty_summary", pd.DataFrame())
        if isinstance(reg_settings_dl, pd.DataFrame) and not reg_settings_dl.empty:
            all_frames["facet_regularization_settings"] = reg_settings_dl
        if isinstance(reg_audit_dl, pd.DataFrame) and not reg_audit_dl.empty:
            all_frames["facet_regularization_audit"] = reg_audit_dl
        if isinstance(reg_penalty_dl, pd.DataFrame) and not reg_penalty_dl.empty:
            all_frames["regularization_penalty_summary"] = reg_penalty_dl
    convergence_dl = result.get("convergence", pd.DataFrame())
    if isinstance(convergence_dl, pd.DataFrame) and not convergence_dl.empty:
        all_frames["convergence"] = convergence_dl
    prep = result.get("prep", {})
    score_map = prep.get("score_map", pd.DataFrame())
    if isinstance(score_map, pd.DataFrame) and not score_map.empty:
        all_frames["score_map"] = score_map
    audit_summary = prep.get("audit_summary", pd.DataFrame())
    if isinstance(audit_summary, pd.DataFrame) and not audit_summary.empty:
        all_frames["response_data_audit_summary"] = audit_summary
    row_audit = prep.get("row_audit", pd.DataFrame())
    if isinstance(row_audit, pd.DataFrame) and not row_audit.empty:
        all_frames["response_data_row_audit"] = row_audit
    excluded_rows = prep.get("excluded_rows", pd.DataFrame())
    if isinstance(excluded_rows, pd.DataFrame) and not excluded_rows.empty:
        all_frames["response_data_excluded_rows"] = excluded_rows
    if not measures_dl.empty:
        all_frames["measures"] = measures_dl
    shrinkage_dl = diagnostics.get("eb_shrinkage", {})
    if isinstance(shrinkage_dl, dict) and shrinkage_dl.get("available"):
        shr_report_dl = shrinkage_dl.get("report", pd.DataFrame())
        shr_measures_dl = shrinkage_dl.get("measures", pd.DataFrame())
        if isinstance(shr_report_dl, pd.DataFrame) and not shr_report_dl.empty:
            all_frames["eb_shrinkage_report"] = shr_report_dl
        if isinstance(shr_measures_dl, pd.DataFrame) and not shr_measures_dl.empty:
            all_frames["eb_shrinkage_measures"] = shr_measures_dl
    if not reliability_dl.empty:
        all_frames["reliability"] = reliability_dl
    try:
        weight_audit_dl = build_weighting_policy_audit(result)
        if isinstance(weight_audit_dl, pd.DataFrame) and not weight_audit_dl.empty:
            all_frames["weighting_policy_audit"] = weight_audit_dl
    except Exception:
        weight_audit_dl = pd.DataFrame()
    try:
        publication_gate_dl = build_publication_gate_summary(result, diagnostics, all_bias_results)
        if isinstance(publication_gate_dl, pd.DataFrame) and not publication_gate_dl.empty:
            all_frames["publication_gate_summary"] = publication_gate_dl
    except Exception:
        publication_gate_dl = pd.DataFrame()
    try:
        action_plan_dl = build_submission_action_plan(result, diagnostics, all_bias_results)
        if isinstance(action_plan_dl, pd.DataFrame) and not action_plan_dl.empty:
            all_frames["submission_action_plan"] = action_plan_dl
    except Exception:
        action_plan_dl = pd.DataFrame()
    try:
        beginner_case_dl = build_beginner_case_guidance(result, diagnostics, all_bias_results)
        if isinstance(beginner_case_dl, pd.DataFrame) and not beginner_case_dl.empty:
            all_frames["beginner_case_guidance"] = beginner_case_dl
    except Exception:
        beginner_case_dl = pd.DataFrame()
    try:
        misfit_casebook_dl = build_misfit_casebook(result, diagnostics, all_bias_results)
        if isinstance(misfit_casebook_dl, pd.DataFrame) and not misfit_casebook_dl.empty:
            all_frames["misfit_casebook"] = misfit_casebook_dl
    except Exception:
        misfit_casebook_dl = pd.DataFrame()
    try:
        readiness_dl = build_final_report_readiness(result, diagnostics, all_bias_results)
        if isinstance(readiness_dl, pd.DataFrame) and not readiness_dl.empty:
            all_frames["final_report_readiness"] = readiness_dl
    except Exception:
        readiness_dl = pd.DataFrame()
    try:
        claim_guide_dl = build_manuscript_claim_guide(result, diagnostics, all_bias_results)
        if isinstance(claim_guide_dl, pd.DataFrame) and not claim_guide_dl.empty:
            all_frames["manuscript_claim_guide"] = claim_guide_dl
    except Exception:
        claim_guide_dl = pd.DataFrame()
    visual_checklist_dl = visual_interpretation_checklist()
    if isinstance(visual_checklist_dl, pd.DataFrame) and not visual_checklist_dl.empty:
        all_frames["visual_interpretation_checklist"] = visual_checklist_dl
    visual_evidence_dl = visual_method_evidence_table()
    if isinstance(visual_evidence_dl, pd.DataFrame) and not visual_evidence_dl.empty:
        all_frames["visual_method_evidence"] = visual_evidence_dl
    public_beta_dl = public_beta_limitations_table()
    if isinstance(public_beta_dl, pd.DataFrame) and not public_beta_dl.empty:
        all_frames["public_beta_limitations"] = public_beta_dl
    simulation_inventory_dl = external_simulation_reference_inventory()
    if isinstance(simulation_inventory_dl, pd.DataFrame) and not simulation_inventory_dl.empty:
        all_frames["external_simulation_reference_inventory"] = simulation_inventory_dl
    simulation_templates_dl = external_simulation_template_inventory()
    if isinstance(simulation_templates_dl, pd.DataFrame) and not simulation_templates_dl.empty:
        all_frames["external_simulation_template_inventory"] = simulation_templates_dl
    mfrmr_coverage_dl = mfrmr_015_migration_coverage_table()
    if isinstance(mfrmr_coverage_dl, pd.DataFrame) and not mfrmr_coverage_dl.empty:
        all_frames["mfrmr_015_migration_coverage"] = mfrmr_coverage_dl
    mfrmr_016_coverage_dl = mfrmr_016_migration_coverage_table()
    if isinstance(mfrmr_016_coverage_dl, pd.DataFrame) and not mfrmr_016_coverage_dl.empty:
        all_frames["mfrmr_016_migration_coverage"] = mfrmr_016_coverage_dl
    public_readiness_dl = public_release_readiness_table()
    if isinstance(public_readiness_dl, pd.DataFrame) and not public_readiness_dl.empty:
        all_frames["public_release_readiness"] = public_readiness_dl
    if not steps_dl.empty:
        all_frames["steps"] = steps_dl
    if not slopes_dl.empty:
        all_frames["gpcm_slopes"] = slopes_dl
    try:
        category_curve_dl = category_probability_curve_export_table(result)
        if isinstance(category_curve_dl, pd.DataFrame) and not category_curve_dl.empty:
            all_frames["category_probability_curves"] = category_curve_dl
    except Exception:
        category_curve_dl = pd.DataFrame()
    try:
        information_curve_dl = information_curve_export_table(result)
        if isinstance(information_curve_dl, pd.DataFrame) and not information_curve_dl.empty:
            all_frames["information_curves"] = information_curve_dl
    except Exception:
        information_curve_dl = pd.DataFrame()
    population_dl = result.get("population", {})
    if isinstance(population_dl, dict):
        pop_coef = population_dl.get("coefficients", pd.DataFrame())
        pop_person = population_dl.get("person_data", pd.DataFrame())
        pop_transforms = population_dl.get("numeric_transforms", pd.DataFrame())
        pop_type_summary = population_dl.get("type_summary", pd.DataFrame())
        pop_term_types = pd.DataFrame(
            [
                {"Term": term, "Type": term_type}
                for term, term_type in dict(population_dl.get("term_types", {})).items()
            ]
        )
        if isinstance(pop_coef, pd.DataFrame) and not pop_coef.empty:
            all_frames["population_coefficients"] = pop_coef
        if isinstance(pop_person, pd.DataFrame) and not pop_person.empty and bool(population_dl.get("enabled", False)):
            all_frames["population_person_data"] = pop_person
        if isinstance(pop_transforms, pd.DataFrame) and not pop_transforms.empty:
            all_frames["population_numeric_transforms"] = pop_transforms
        if isinstance(pop_type_summary, pd.DataFrame) and not pop_type_summary.empty:
            all_frames["population_covariate_type_summary"] = pop_type_summary
        if not pop_term_types.empty:
            all_frames["population_term_types"] = pop_term_types
    if isinstance(scorefile, pd.DataFrame) and not scorefile.empty:
        all_frames["scorefile"] = scorefile
    try:
        prediction_dl = compute_fitted_prediction_table(result)
        if isinstance(prediction_dl, pd.DataFrame) and not prediction_dl.empty:
            all_frames["fitted_predictions"] = prediction_dl
    except Exception:
        prediction_dl = pd.DataFrame()
    session_new_pred = st.session_state.get("mfrm_new_design_prediction_bundle", {})
    if isinstance(session_new_pred, dict):
        new_pred_tbl = session_new_pred.get("table", pd.DataFrame())
        if isinstance(new_pred_tbl, pd.DataFrame) and not new_pred_tbl.empty:
            all_frames["new_design_predictions"] = new_pred_tbl
    session_refit_sim = st.session_state.get("mfrm_refit_simulation_bundle", {})
    if isinstance(session_refit_sim, dict):
        refit_summary = session_refit_sim.get("summary", pd.DataFrame())
        refit_counts = session_refit_sim.get("category_counts", pd.DataFrame())
        if isinstance(refit_summary, pd.DataFrame) and not refit_summary.empty:
            all_frames["refit_simulation_summary"] = refit_summary
        if isinstance(refit_counts, pd.DataFrame) and not refit_counts.empty:
            all_frames["refit_simulation_category_counts"] = refit_counts
    try:
        design_dl = evaluate_design_from_fitted(result, diagnostics, forecast_multipliers=(2.0,))
        if isinstance(design_dl, dict) and design_dl.get("available"):
            design_overview = design_dl.get("overview", pd.DataFrame())
            design_summary = design_dl.get("summary", pd.DataFrame())
            design_forecast = design_dl.get("forecast", pd.DataFrame())
            design_counts = design_dl.get("facet_counts", pd.DataFrame())
            design_sample_summary = design_dl.get("sample_size_summary", pd.DataFrame())
            design_sample_audit = design_dl.get("sample_size_adequacy", pd.DataFrame())
            design_nesting = design_dl.get("nesting_audit", pd.DataFrame())
            design_effect = design_dl.get("design_effect", pd.DataFrame())
            if isinstance(design_overview, pd.DataFrame) and not design_overview.empty:
                all_frames["design_overview"] = design_overview
            if isinstance(design_summary, pd.DataFrame) and not design_summary.empty:
                all_frames["design_evaluation"] = design_summary
            if isinstance(design_forecast, pd.DataFrame) and not design_forecast.empty:
                all_frames["design_reliability_forecast"] = design_forecast
            if isinstance(design_counts, pd.DataFrame) and not design_counts.empty:
                all_frames["design_facet_counts"] = design_counts
            if isinstance(design_sample_summary, pd.DataFrame) and not design_sample_summary.empty:
                all_frames["facet_sample_size_summary"] = design_sample_summary
            if isinstance(design_sample_audit, pd.DataFrame) and not design_sample_audit.empty:
                all_frames["facet_sample_size_adequacy"] = design_sample_audit
            if isinstance(design_nesting, pd.DataFrame) and not design_nesting.empty:
                all_frames["facet_nesting_audit"] = design_nesting
            if isinstance(design_effect, pd.DataFrame) and not design_effect.empty:
                all_frames["intraclass_icc_design_effect"] = design_effect
    except Exception:
        design_dl = {}
    if isinstance(residuals, pd.DataFrame) and not residuals.empty:
        all_frames["residuals"] = residuals
    posterior_dl = result.get("posterior", {})
    if isinstance(posterior_dl, dict):
        posterior_scores = posterior_dl.get("scores", pd.DataFrame())
        plausible_values = posterior_dl.get("plausible_values", pd.DataFrame())
        if isinstance(posterior_scores, pd.DataFrame) and not posterior_scores.empty:
            all_frames["posterior_scores"] = posterior_scores
        if isinstance(plausible_values, pd.DataFrame) and not plausible_values.empty:
            all_frames["plausible_values"] = plausible_values
    if not fit_dl.empty:
        all_frames["fit_statistics"] = fit_dl
    for facet_name, tbl in (report_tables or {}).items():
        safe_name = facet_name.replace(" ", "_")[:31]
        all_frames[f"facets_{safe_name}"] = tbl
    if bias_results and bias_results.get("table") is not None and not bias_results["table"].empty:
        all_frames["bias_table"] = bias_results["table"]
        dff_tbl = build_dff_bias_screening_table(bias_results)
        if isinstance(dff_tbl, pd.DataFrame) and not dff_tbl.empty:
            all_frames["dff_bias_screening"] = dff_tbl
        if bias_results.get("summary") is not None:
            all_frames["bias_summary"] = bias_results["summary"]
    if all_bias_results:
        for pair_key, pair_bundle in all_bias_results.items():
            pair_table = pair_bundle.get("table") if isinstance(pair_bundle, dict) else None
            if isinstance(pair_table, pd.DataFrame) and not pair_table.empty:
                safe_pair = re.sub(r"[^A-Za-z0-9]+", "_", str(pair_key)).strip("_")[:40]
                all_frames[f"bias_{safe_pair}"] = pair_table
                dff_pair = build_dff_bias_screening_table(pair_bundle)
                if isinstance(dff_pair, pd.DataFrame) and not dff_pair.empty:
                    all_frames[f"dff_bias_{safe_pair}"] = dff_pair
    marginal_fit = diagnostics.get("marginal_fit", {})
    if isinstance(marginal_fit, dict):
        marginal_summary = marginal_fit.get("summary", pd.DataFrame())
        marginal_counts = marginal_fit.get("counts", pd.DataFrame())
        marginal_pairwise = marginal_fit.get("pairwise", {}) if isinstance(marginal_fit.get("pairwise", {}), dict) else {}
        pair_summary = marginal_pairwise.get("summary", pd.DataFrame())
        pair_counts = marginal_pairwise.get("counts", pd.DataFrame())
        if isinstance(marginal_summary, pd.DataFrame) and not marginal_summary.empty:
            all_frames["marginal_fit_summary"] = marginal_summary
        if isinstance(marginal_counts, pd.DataFrame) and not marginal_counts.empty:
            all_frames["marginal_fit_counts"] = marginal_counts
        if isinstance(pair_summary, pd.DataFrame) and not pair_summary.empty:
            all_frames["marginal_pairwise_summary"] = pair_summary
        if isinstance(pair_counts, pd.DataFrame) and not pair_counts.empty:
            all_frames["marginal_pairwise_counts"] = pair_counts
    anchor_audit = result.get("config", {}).get("anchor_audit", {})
    if isinstance(anchor_audit, dict):
        audit_summary = anchor_audit.get("summary", pd.DataFrame())
        audit_issues = anchor_audit.get("issues", pd.DataFrame())
        valid_anchors = anchor_audit.get("valid_anchors", pd.DataFrame())
        valid_group_anchors = anchor_audit.get("valid_group_anchors", pd.DataFrame())
        if isinstance(audit_summary, pd.DataFrame) and not audit_summary.empty:
            all_frames["anchor_audit_summary"] = audit_summary
        if isinstance(audit_issues, pd.DataFrame) and not audit_issues.empty:
            all_frames["anchor_audit_issues"] = audit_issues
        if isinstance(valid_anchors, pd.DataFrame) and not valid_anchors.empty:
            all_frames["valid_anchor_inputs"] = valid_anchors
        if isinstance(valid_group_anchors, pd.DataFrame) and not valid_group_anchors.empty:
            all_frames["valid_group_anchor_inputs"] = valid_group_anchors
    drift_review = result.get("anchor_drift", {})
    if isinstance(drift_review, dict):
        drift_summary = drift_review.get("summary", pd.DataFrame())
        anchor_drift_tbl = drift_review.get("anchor_drift", pd.DataFrame())
        group_drift_tbl = drift_review.get("group_drift", pd.DataFrame())
        if isinstance(drift_summary, pd.DataFrame) and not drift_summary.empty:
            all_frames["anchor_drift_summary"] = drift_summary
        if isinstance(anchor_drift_tbl, pd.DataFrame) and not anchor_drift_tbl.empty:
            all_frames["anchor_drift"] = anchor_drift_tbl
        if isinstance(group_drift_tbl, pd.DataFrame) and not group_drift_tbl.empty:
            all_frames["group_anchor_drift"] = group_drift_tbl
    chain_review = result.get("equating_chain", {})
    if isinstance(chain_review, dict):
        chain_summary = chain_review.get("summary", pd.DataFrame())
        chain_edges = chain_review.get("edges", pd.DataFrame())
        if isinstance(chain_summary, pd.DataFrame) and not chain_summary.empty:
            all_frames["equating_chain_summary"] = chain_summary
        if isinstance(chain_edges, pd.DataFrame) and not chain_edges.empty:
            all_frames["equating_chain_edges"] = chain_edges
    workflow_plan = result.get("anchor_equating_workflow", pd.DataFrame())
    if isinstance(workflow_plan, pd.DataFrame) and not workflow_plan.empty:
        all_frames["anchor_equating_workflow"] = workflow_plan

    # Anchor data
    anchor_parts = []
    others_df = result.get("facets", {}).get("others", pd.DataFrame())
    if not others_df.empty and "Facet" in others_df.columns and "Level" in others_df.columns and "Estimate" in others_df.columns:
        for _, row in others_df.iterrows():
            anchor_parts.append({
                "Facet": row["Facet"],
                "Level": row["Level"],
                "Anchor": round(float(row["Estimate"]), 4),
            })
    if anchor_parts:
        all_frames["anchors"] = pd.DataFrame(anchor_parts)
    all_frames_key = frames_fingerprint(all_frames)

    # ================================================================
    # Sub-tab 0: Data Tables
    # ================================================================
    with dl_tabs[0]:
        st.markdown(f"**{len(all_frames)} table(s)** available for download.")

        z_col1, z_col2, z_col3 = st.columns(3)
        with z_col1:
            st.download_button(
                "Download ALL tables (ZIP)",
                data=cached_tables_zip(all_frames, all_frames_key),
                file_name="MFRM_Tables.zip",
                mime="application/zip",
                key="dl_tables_zip",
            )
        with z_col2:
            try:
                st.download_button(
                    "Download Excel (.xlsx)",
                    data=cached_excel_bytes(all_frames, all_frames_key),
                    file_name="MFRM_Report.xlsx",
                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    key="dl_tables_xlsx",
                )
            except Exception as xl_exc:
                st.caption(f"Excel export failed: {xl_exc}")
        with z_col3:
            st.download_button(
                "Download HTML report",
                data=cached_html_report(all_frames, all_frames_key),
                file_name="MFRM_Report.html",
                mime="text/html",
                key="dl_tables_html",
            )

        # --- Individual CSVs in expander ---
        with st.expander(f"Individual CSV downloads ({len(all_frames)} files)"):
            cols = st.columns(3)
            for idx, (name, df) in enumerate(all_frames.items()):
                with cols[idx % 3]:
                    st.download_button(
                        f"{name}.csv ({len(df)} rows)",
                        data=to_csv_bytes(df),
                        file_name=f"mfrm_{name}.csv",
                        mime="text/csv",
                        key=f"dl_csv_{name}",
                    )

    # ================================================================
    # Sub-tab 1: Figures
    # ================================================================
    with dl_tabs[1]:
        st.caption(
            "Download key diagnostic plots using the app's manuscript export profile: "
            "white background, consistent font, compact margins, 300 DPI PNG when static "
            "export is available, and matching interactive HTML for review."
        )
        if not generate_figures:
            st.info(
                "Figure export bundle generation was skipped for this run. "
                "Re-run with Analysis depth = Full publication or Custom > "
                "Prepare figure export bundle to build downloadable plot files."
            )
            figure_result = {}
            figure_measures = pd.DataFrame()
            figure_steps = pd.DataFrame()
        else:
            figure_result = result
            figure_measures = measures_dl
            figure_steps = steps_dl

        # Generate all key figures
        figure_bytes: dict[str, bytes] = {}  # PNG bytes (if kaleido works)
        figure_html: dict[str, str] = {}     # HTML fallback (always available)
        _fig_errors: list[str] = []
        _kaleido_ok: bool = True  # track whether kaleido works

        # Wright Map
        facets_data = figure_result.get("facets", {})
        person_tbl = facets_data.get("person", pd.DataFrame())
        facet_tbl = facets_data.get("others", pd.DataFrame())
        step_tbl = figure_steps
        if not person_tbl.empty:
            try:
                fig_wm = _make_wright_map_export_figure(person_tbl, facet_tbl, step_tbl)
                _kaleido_ok = _add_figure_export(fig_wm, "wright_map", figure_bytes, figure_html) and _kaleido_ok
            except Exception as e:
                _fig_errors.append(f"Wright Map: {e}")

        # Fit Scatter
        if not figure_measures.empty and "Infit" in figure_measures.columns and "Outfit" in figure_measures.columns:
            try:
                fig_fs = _make_fit_scatter_export_figure(figure_measures)
                _kaleido_ok = _add_figure_export(fig_fs, "fit_scatter", figure_bytes, figure_html) and _kaleido_ok
            except Exception as e:
                _fig_errors.append(f"Fit Scatter: {e}")

        # Category Probability Curves
        try:
            curve_dl = build_category_probability_curve_data(figure_result)
            fig_cpc, fig_expected = _make_category_probability_curve_figures(curve_dl)
            _kaleido_ok = _add_figure_export(
                fig_cpc,
                "category_probability_curves_average",
                figure_bytes,
                figure_html,
            ) and _kaleido_ok
            _kaleido_ok = _add_figure_export(
                fig_expected,
                "expected_score_curve_average",
                figure_bytes,
                figure_html,
            ) and _kaleido_ok
        except Exception as e:
            _fig_errors.append(f"Category Probability Curves: {e}")

        # Information / targeting curve
        try:
            info_curve_dl = build_information_curve_data(figure_result)
            fig_info = _make_information_curve_figure(info_curve_dl)
            if fig_info is not None:
                _kaleido_ok = _add_figure_export(
                    fig_info,
                    "information_curve_average",
                    figure_bytes,
                    figure_html,
                ) and _kaleido_ok
        except Exception as e:
            _fig_errors.append(f"Information curve: {e}")

        # EB shrinkage forest
        try:
            fig_shr = _make_eb_shrinkage_figure(diagnostics.get("eb_shrinkage", {}))
            if fig_shr is not None:
                _kaleido_ok = _add_figure_export(
                    fig_shr,
                    "eb_shrinkage_forest",
                    figure_bytes,
                    figure_html,
                ) and _kaleido_ok
        except Exception as e:
            _fig_errors.append(f"EB shrinkage forest: {e}")

        # Facet Distribution (box)
        if not figure_measures.empty and "Facet" in figure_measures.columns:
            try:
                fig_fd = _make_facet_distribution_export_figure(figure_measures)
                _kaleido_ok = _add_figure_export(fig_fd, "facet_distribution", figure_bytes, figure_html) and _kaleido_ok
            except Exception as e:
                _fig_errors.append(f"Facet Distribution: {e}")

        # Strict marginal diagnostics
        if generate_figures:
            try:
                marginal_fit_dl = diagnostics.get("marginal_fit", {})
                if isinstance(marginal_fit_dl, dict) and marginal_fit_dl.get("available"):
                    marginal_summary_dl = marginal_fit_dl.get("summary", pd.DataFrame())
                    marginal_counts_dl = marginal_fit_dl.get("counts", pd.DataFrame())
                    fig_ms = _make_marginal_summary_figure(
                        marginal_summary_dl,
                        "Largest marginal distribution deviations",
                    )
                    if fig_ms is not None:
                        _kaleido_ok = _add_figure_export(
                            fig_ms,
                            "strict_marginal_summary",
                            figure_bytes,
                            figure_html,
                        ) and _kaleido_ok
                    top_frame_dl = _prepare_marginal_plot_frame(marginal_summary_dl, top_n=25)
                    top_labels_dl = top_frame_dl["_Label"].tolist() if "_Label" in top_frame_dl.columns else None
                    fig_mh = _make_marginal_heatmap_figure(
                        marginal_counts_dl,
                        "Category-level marginal residual heatmap",
                        top_labels=top_labels_dl,
                    )
                    if fig_mh is not None:
                        _kaleido_ok = _add_figure_export(
                            fig_mh,
                            "strict_marginal_heatmap",
                            figure_bytes,
                            figure_html,
                        ) and _kaleido_ok

                    pairwise_dl = marginal_fit_dl.get("pairwise", {})
                    if isinstance(pairwise_dl, dict) and pairwise_dl.get("available"):
                        pair_summary_dl = pairwise_dl.get("summary", pd.DataFrame())
                        pair_counts_dl = pairwise_dl.get("counts", pd.DataFrame())
                        fig_ps = _make_marginal_summary_figure(
                            pair_summary_dl,
                            "Largest pairwise marginal deviations",
                            top_n=30,
                        )
                        if fig_ps is not None:
                            _kaleido_ok = _add_figure_export(
                                fig_ps,
                                "strict_marginal_pairwise_summary",
                                figure_bytes,
                                figure_html,
                            ) and _kaleido_ok
                        pair_top_dl = _prepare_marginal_plot_frame(pair_summary_dl, top_n=30)
                        pair_labels_dl = pair_top_dl["_Label"].tolist() if "_Label" in pair_top_dl.columns else None
                        fig_ph = _make_marginal_heatmap_figure(
                            pair_counts_dl,
                            "Pairwise category-level marginal residual heatmap",
                            top_labels=pair_labels_dl,
                            top_n=30,
                        )
                        if fig_ph is not None:
                            _kaleido_ok = _add_figure_export(
                                fig_ph,
                                "strict_marginal_pairwise_heatmap",
                                figure_bytes,
                                figure_html,
                            ) and _kaleido_ok
            except Exception as e:
                _fig_errors.append(f"Strict marginal diagnostics: {e}")

        if generate_figures:
            n_available = len(set(figure_html) | set(figure_bytes))
            fmt_label = "PNG + HTML" if figure_bytes else "HTML"
            st.markdown(f"**{n_available} figure(s)** available ({fmt_label} format).")

        if not _kaleido_ok and figure_html:
            st.info(
                "PNG export is unavailable (kaleido not configured on this server). "
                "Interactive HTML figures are offered instead. "
                "To enable PNG with kaleido >= 1.0, install Chrome or Chromium in the runtime."
            )

        if _fig_errors:
            with st.expander(f"⚠ {len(_fig_errors)} figure(s) could not be generated"):
                for err in _fig_errors:
                    st.caption(err)

        figure_manifest = _figure_export_manifest(figure_html, figure_bytes)
        if generate_figures and not figure_manifest.empty:
            st.markdown("**Figure export manifest**")
            _render_compact_dataframe(
                figure_manifest,
                ["FigureName", "FormatsAvailable", "ManuscriptUse"],
                details_label="Show full figure export manifest",
                hide_index=True,
                wrap_text=True,
            )
            st.download_button(
                "Download figure manifest (CSV)",
                data=to_csv_bytes(figure_manifest),
                file_name="figure_manifest.csv",
                mime="text/csv",
                key="dl_figure_manifest",
            )

        if figure_html or figure_bytes:
            figure_assets = _figure_bundle_assets(figure_html, figure_bytes, figure_manifest)
            figure_assets_key = bytes_mapping_fingerprint(figure_assets)
            st.download_button(
                "Download publication figure bundle (ZIP)",
                data=cached_mixed_asset_zip(figure_assets, figure_assets_key),
                file_name="MFRM_Publication_Figures.zip",
                mime="application/zip",
                key="dl_figs_zip",
            )

            with st.expander(f"Individual figure downloads ({len(set(figure_html) | set(figure_bytes))} figure(s))"):
                fig_cols = st.columns(3)
                for idx, name in enumerate(sorted(set(figure_html) | set(figure_bytes))):
                    with fig_cols[idx % len(fig_cols)]:
                        if name in figure_bytes:
                            st.download_button(
                                f"{name}.png",
                                data=figure_bytes[name],
                                file_name=f"{name}.png",
                                mime="image/png",
                                key=f"dl_fig_png_dl_{name}",
                            )
                        if name in figure_html:
                            st.download_button(
                                f"{name}.html",
                                data=figure_html[name].encode("utf-8"),
                                file_name=f"{name}.html",
                                mime="text/html",
                                key=f"dl_fig_html_dl_{name}",
                            )
        elif generate_figures:
            st.info("No figures available. Run estimation first.")

    # ================================================================
    # Sub-tab 2: Scripts & Config
    # ================================================================
    with dl_tabs[2]:
        st.caption(
            "Reproducible analysis scripts (Python & R), configuration JSON, "
            "anchor files for scale linking, and Stan code for Bayesian estimation."
        )

        # --- Analysis configuration JSON ---
        st.subheader("Analysis configuration")
        config = result.get("config", {})
        prep = result.get("prep", {})
        score_map_records = []
        if isinstance(prep.get("score_map"), pd.DataFrame):
            score_map_records = prep["score_map"].to_dict(orient="records")
        opt_export = result.get("opt")
        grad_export = pd.to_numeric(
            pd.Series([getattr(opt_export, "gradient_norm", np.nan)]),
            errors="coerce",
        ).iloc[0]
        elapsed_export = pd.to_numeric(
            pd.Series([getattr(opt_export, "elapsed_seconds", np.nan)]),
            errors="coerce",
        ).iloc[0]
        script_support = build_script_support_status(result)
        optimizer_label = config.get("optimizer") or config.get("mml_engine") or "unknown optimizer"
        software_label = f"MFRM FACETS-mode (standalone Python; {optimizer_label}; no mfrmr/R engine)"
        config_export = {
            "app_version": config.get("app_version", APP_VERSION),
            "release_label": config.get("release_label", APP_RELEASE_LABEL),
            "runtime_scope": config.get("runtime_scope", "standalone Python; no external MFRM engine called"),
            "validation_stance": "Functional parity target; exact cross-package numerical equality is not claimed without a specific parity report.",
            "run_fingerprint": config.get("run_fingerprint"),
            "analysis_config_fingerprint": config.get("analysis_config_fingerprint"),
            "input_data_fingerprint": config.get("input_data_fingerprint"),
            "anchor_data_fingerprint": config.get("anchor_data_fingerprint"),
            "anchor_source_fingerprint": config.get("anchor_source_fingerprint"),
            "group_anchor_data_fingerprint": config.get("group_anchor_data_fingerprint"),
            "group_anchor_source_fingerprint": config.get("group_anchor_source_fingerprint"),
            "population_data_fingerprint": config.get("population_data_fingerprint"),
            "population_source_fingerprint": config.get("population_source_fingerprint"),
            "fingerprint_scope": "short SHA-256 digests for reproducibility checks; not a privacy guarantee or encrypted data store",
            "model": config.get("model", "RSM"),
            "method": config.get("method", "JMLE"),
            "n_obs": prep.get("n_obs"),
            "n_person": prep.get("n_person"),
            "n_cat": config.get("n_cat"),
            "rating_min": prep.get("rating_min"),
            "rating_max": prep.get("rating_max"),
            "keep_original": prep.get("keep_original"),
            "score_range_explicit": prep.get("score_range_explicit"),
            "unused_score_categories": prep.get("unused_score_categories", []),
            "score_map": score_map_records,
            "facet_names": config.get("facet_names", []),
            "workflow_mode": config.get("workflow_mode"),
            "advanced_controls": config.get("advanced_controls"),
            "step_facet": config.get("step_facet"),
            "slope_facet": config.get("slope_facet"),
            "gpcm_spec": config.get("gpcm_spec"),
            "noncenter_facet": config.get("noncenter_facet"),
            "dummy_facets": config.get("dummy_facets", []),
            "positive_facets": config.get("positive_facets", []),
            "optimizer": config.get("optimizer"),
            "mml_engine": config.get("mml_engine"),
            "mml_engine_requested": config.get("mml_engine_requested"),
            "mml_engine_auto_selected": config.get("mml_engine_auto_selected"),
            "mml_engine_auto_attempted": config.get("mml_engine_auto_attempted"),
            "mml_engine_auto_fallback_reason": config.get("mml_engine_auto_fallback_reason"),
            "ui_mml_engine": config.get("ui_mml_engine"),
            "quad_points": config.get("quad_points"),
            "population_prior_sd": config.get("population_prior_sd"),
            "facet_regularization_enabled": config.get("facet_regularization_enabled"),
            "facet_regularization_mode": config.get("facet_regularization_mode"),
            "facet_regularization_objective_mode": config.get("facet_regularization_objective_mode"),
            "facet_regularization_scope": config.get("facet_regularization_scope"),
            "facet_regularization_fingerprint": config.get("facet_regularization_fingerprint"),
            "facet_regularization_ui_mode": config.get("facet_regularization_ui_mode"),
            "facet_regularization_ui_specs": config.get("facet_regularization_specs"),
            "population_formula": config.get("population_formula"),
            "population_terms": (
                config.get("population_model", {}).get("terms")
                if isinstance(config.get("population_model"), dict) else None
            ),
            "population_columns": (
                config.get("population_model", {}).get("columns")
                if isinstance(config.get("population_model"), dict) else None
            ),
            "population_standardize_numeric": (
                config.get("population_model", {}).get("standardize_numeric")
                if isinstance(config.get("population_model"), dict) else None
            ),
            "population_categorical_terms": config.get("population_categorical_terms", []),
            "population_numeric_terms": config.get("population_numeric_terms", []),
            "population_term_types": (
                config.get("population_model", {}).get("term_types")
                if isinstance(config.get("population_model"), dict) else None
            ),
            "population_numeric_transforms": (
                config.get("population_model", {}).get("numeric_transforms")
                if isinstance(config.get("population_model"), dict) else None
            ),
            "population_enabled": (
                config.get("population_model", {}).get("enabled")
                if isinstance(config.get("population_model"), dict) else None
            ),
            "anchor_policy": config.get("anchor_policy"),
            "anchor_audit_status": (
                config.get("anchor_audit", {}).get("overall_status")
                if isinstance(config.get("anchor_audit"), dict) else None
            ),
            "anchor_audit_settings": (
                config.get("anchor_audit", {}).get("settings")
                if isinstance(config.get("anchor_audit"), dict) else None
            ),
            "anchor_drift_scope": config.get("anchor_drift_scope"),
            "anchor_drift_available": (
                result.get("anchor_drift", {}).get("available")
                if isinstance(result.get("anchor_drift"), dict) else None
            ),
            "equating_chain_scope": config.get("equating_chain_scope"),
            "equating_chain_available": (
                result.get("equating_chain", {}).get("available")
                if isinstance(result.get("equating_chain"), dict) else None
            ),
            "maxit": config.get("maxit"),
            "reltol": config.get("reltol"),
            "analysis_depth": config.get("analysis_depth"),
            "compute_residual_pca": config.get("compute_residual_pca", diagnostics.get("pca_enabled")),
            "compute_strict_marginal": config.get("compute_strict_marginal", diagnostics.get("marginal_fit_enabled")),
            "strict_marginal_pairwise": config.get("strict_marginal_pairwise"),
            "strict_marginal_max_pair_cells": config.get("strict_marginal_max_pair_cells"),
            "strict_marginal_available": (
                diagnostics.get("marginal_fit", {}).get("available")
                if isinstance(diagnostics.get("marginal_fit"), dict) else None
            ),
            "compute_eb_shrinkage": config.get("compute_eb_shrinkage", diagnostics.get("eb_shrinkage_enabled")),
            "eb_shrinkage_available": (
                diagnostics.get("eb_shrinkage", {}).get("available")
                if isinstance(diagnostics.get("eb_shrinkage"), dict) else None
            ),
            "facet_sample_adequacy_thresholds": dict(FACET_SAMPLE_ADEQUACY_THRESHOLDS),
            "nesting_audit_rule": "conditional entropy index = 1 - H(FacetB|FacetA)/H(FacetB)",
            "compute_plausible_values": config.get("compute_plausible_values"),
            "n_plausible_values": config.get("n_plausible_values"),
            "plausible_seed": config.get("plausible_seed"),
            "posterior_scoring_available": (
                result.get("posterior", {}).get("available")
                if isinstance(result.get("posterior"), dict) else None
            ),
            "prediction_scope": "fitted_rows_conditional; supplied_new_rows_known_person_conditional_or_unknown_person_mml_population_marginal",
            "simulation_scope": "optional_fixed_parameter_row_probability_simulation",
            "fitted_simulation_settings": {
                "replicates": st.session_state.get("prediction_sim_replicates"),
                "seed": st.session_state.get("prediction_sim_seed"),
                "include_row_draws": st.session_state.get("prediction_sim_row_draws"),
            },
            "refit_simulation_scope": "optional_small_replicate_random_missingness_refit_stress_test",
            "refit_simulation_settings": {
                "replicates": st.session_state.get("refit_sim_replicates"),
                "missing_rate": st.session_state.get("refit_sim_missing_rate"),
                "maxit": st.session_state.get("refit_sim_maxit"),
                "seed": st.session_state.get("refit_sim_seed"),
                "method": st.session_state.get("refit_sim_method"),
            },
            "design_evaluation_scope": "observed_design_balance_reliability_forecast",
            "script_support_scope": script_support.get("scope"),
            "portable_self_contained_jmle_available": script_support.get("portable_available"),
            "portable_self_contained_jmle_blockers": script_support.get("portable_blockers"),
            "bias_mode": config.get("bias_mode"),
            "selected_bias_pair": config.get("selected_bias_pair"),
            "render_interactive_plots": config.get("render_interactive_plots"),
            "generate_figure_exports": config.get("generate_figure_exports"),
            "converged": bool(getattr(result.get("opt"), "success", False)),
            "convergence_message": str(getattr(result.get("opt"), "message", "")),
            "gradient_norm": float(grad_export) if np.isfinite(grad_export) else None,
            "elapsed_seconds": float(elapsed_export) if np.isfinite(elapsed_export) else None,
            "software": software_label,
        }
        config_export["config_export_fingerprint"] = stable_json_fingerprint(config_export)
        config_json = json.dumps(config_export, indent=2, ensure_ascii=False, default=str)
        with st.expander("View config JSON"):
            st.code(config_json, language="json")
        st.download_button(
            "Download config (JSON)",
            data=config_json.encode("utf-8"),
            file_name="mfrm_config.json",
            mime="application/json",
            key="dl_config_json",
        )

        # --- Import companion for Download config ---
        # A previously downloaded mfrm_config.json can be uploaded here to
        # inspect the run's settings. The import is read-only — it parses
        # the JSON, validates the schema, and shows the values in a table
        # — because most of the fields in the exported payload are
        # run-specific metadata (fingerprint, convergence status, elapsed
        # seconds) rather than sidebar inputs that can be replayed
        # losslessly. Users who want to re-run with the imported settings
        # copy the model / method / analysis-depth values manually.
        uploaded_config = st.file_uploader(
            "Import config JSON (read-only inspection)",
            type=["json"],
            key="import_config_json_v021",
            help=(
                "Upload a previously downloaded mfrm_config.json to verify "
                "what settings produced an earlier run. This panel shows the "
                "settings as a table; it does not overwrite sidebar inputs, "
                "so accidental imports can't corrupt your current run."
            ),
        )
        if uploaded_config is not None:
            try:
                imported = json.loads(uploaded_config.read().decode("utf-8"))
                # Keep only the settings that map back to sidebar inputs.
                whitelist = _CONFIG_JSON_IMPORT_WHITELIST
                settings_rows = [
                    {"setting": k, "value": str(imported[k])}
                    for k in sorted(whitelist)
                    if k in imported
                ]
                if settings_rows:
                    st.success(
                        f"Imported {len(settings_rows)} setting(s) from "
                        f"{uploaded_config.name}. Review the values, then "
                        "update the sidebar manually if you want to re-run."
                    )
                    st.dataframe(
                        pd.DataFrame(settings_rows),
                        width="stretch", hide_index=True,
                    )
                else:
                    st.warning(
                        "Imported JSON had no recognisable MFRM settings. "
                        "Is this the config file downloaded from this app?"
                    )
            except json.JSONDecodeError as exc:
                st.error(f"Could not parse JSON: {exc}")
            except Exception as exc:  # pragma: no cover - defensive
                st.error(f"Import failed: {type(exc).__name__}: {exc}")

        method_appendix = generate_method_appendix_text(result, diagnostics, all_bias_results)
        manuscript_template = generate_manuscript_reporting_template(result, diagnostics, all_bias_results)
        external_template_assets = external_simulation_template_scripts()
        local_batch_readme = generate_local_batch_readme()
        text_assets = {
            "method_appendix.md": method_appendix,
            "manuscript_template.md": manuscript_template,
            "local_batch_workflow.md": local_batch_readme,
            **external_template_assets,
        }
        text_assets_key = bytes_mapping_fingerprint(text_assets)
        st.subheader("Compact method appendix")
        with st.expander("View method appendix"):
            st.code(method_appendix, language="markdown")
        st.download_button(
            "Download method appendix (Markdown)",
            data=method_appendix.encode("utf-8"),
            file_name="mfrm_method_appendix.md",
            mime="text/markdown",
            key="dl_method_appendix_md",
        )
        st.subheader("Manuscript reporting template")
        st.caption(
            "Use this with the Claim Guide and Readiness table before drafting final Results and Limitations."
        )
        with st.expander("View manuscript template"):
            st.code(manuscript_template, language="markdown")
        st.download_button(
            "Download manuscript template (Markdown)",
            data=manuscript_template.encode("utf-8"),
            file_name="mfrm_manuscript_template.md",
            mime="text/markdown",
            key="dl_manuscript_template_md",
        )

        # --- Anchor file ---
        if anchor_parts:
            st.subheader("Anchor file")
            st.caption("Estimated measures as anchor values for linking future analyses.")
