def _self_test_essential_mode_tab_filters() -> None:
    """Pin the Essential-mode hidden-tab sets for Help + Report tabs.

    The filtering logic lives inline inside `show_help_section` and
    `show_report_section`; this test mirrors those sets so that if
    someone renames or reorders a label, CI catches the drift before
    Essential mode silently drops a user-visible tab.
    """
    # Help tab: 10 labels total; 3 hidden in Essential, 7 visible.
    help_all_labels = [
        "Quick Start", "Analysis Workflow", "Interpretation Guide",
        "Rater Effects", "Rating Scale Guide", "Glossary",
        "Reporting Guide", "Troubleshooting", "Model Capability",
        "Public Beta",
    ]
    help_advanced = {"Rating Scale Guide", "Model Capability", "Public Beta"}
    help_essential = [l for l in help_all_labels if l not in help_advanced]
    _self_test_assert(
        len(help_all_labels) == 10,
        f"Help tab label count drifted: {len(help_all_labels)} != 10",
    )
    _self_test_assert(
        len(help_essential) == 7,
        f"Help tab Essential-visible count wrong: {len(help_essential)} != 7",
    )
    _self_test_assert(
        help_advanced.issubset(set(help_all_labels)),
        "Help tab ADVANCED set contains labels not in master list",
    )

    # Report tab narrative-group: 4 labels total, 2 in Essential.
    report_narrative_all = [
        "APA Report", "Manuscript Template", "Method Appendix", "Claim Guide",
    ]
    report_narrative_essential = ["APA Report", "Claim Guide"]
    _self_test_assert(
        set(report_narrative_essential).issubset(set(report_narrative_all)),
        "Report narrative Essential-visible set drifted from master list",
    )

    # Report tab checks-group: 4 labels total, 3 in Essential.
    report_checks_all = ["Tables", "Reporting Checklist", "Facet Equivalence", "Readiness"]
    report_checks_essential = ["Tables", "Reporting Checklist", "Readiness"]
    _self_test_assert(
        set(report_checks_essential).issubset(set(report_checks_all)),
        "Report checks Essential-visible set drifted from master list",
    )

    # Report tab exports-group: 2 labels total, 1 in Essential.
    report_exports_all = ["Stan Code", "📄 Publication Document"]
    report_exports_essential = ["📄 Publication Document"]
    _self_test_assert(
        set(report_exports_essential).issubset(set(report_exports_all)),
        "Report exports Essential-visible set drifted from master list",
    )


def _self_test_data_outlier_detection() -> None:
    """Pin the six ingestion-time anomaly detectors in `detect_data_outliers`.

    Builds a synthetic dataset that intentionally contains one case of
    each anomaly the function screens for, then asserts each check
    type appears in the findings list. Clean data produces zero
    findings — no false positives.
    """
    rng = np.random.default_rng(20260417)
    rows: list[tuple] = []
    # Baseline: 20 normal persons × 3 raters × 2 tasks = 120 rows
    for pi in range(1, 21):
        for ri in range(1, 4):
            for ti in range(1, 3):
                rows.append((f"P{pi:02d}", f"R{ri}", f"T{ti}",
                             int(rng.integers(0, 6))))
    clean_df = pd.DataFrame(rows, columns=["Person", "Rater", "Task", "Score"])

    # Clean data → zero findings
    findings = detect_data_outliers(
        clean_df, person_col="Person", score_col="Score",
        facet_cols=["Rater", "Task"],
    )
    _self_test_assert(
        len(findings) == 0,
        f"clean dataset produced {len(findings)} false-positive findings: "
        f"{[f['name'] for f in findings]}",
    )

    # Inject every anomaly type
    rows_dirty = list(rows)
    # Zero-variance person
    for ri in range(1, 4):
        for ti in range(1, 3):
            rows_dirty.append(("P21_CONSTANT", f"R{ri}", f"T{ti}", 3))
    # Zero-variance rater
    for pi in range(1, 15):
        rows_dirty.append((f"P{pi:02d}", "R4_CONSTANT", "T1", 5))
    # Negative + out-of-range
    rows_dirty.append(("P_NEG", "R1", "T1", -2))
    rows_dirty.append(("P_HIGH", "R1", "T1", 99))
    # Over-observed person
    for _ in range(250):
        rows_dirty.append(("P_OVER", "R1", "T1", int(rng.integers(0, 6))))
    dirty_df = pd.DataFrame(rows_dirty, columns=["Person", "Rater", "Task", "Score"])

    findings_dirty = detect_data_outliers(
        dirty_df, person_col="Person", score_col="Score",
        facet_cols=["Rater", "Task"],
        rating_min=0, rating_max=5,
    )
    found_names = {f["name"] for f in findings_dirty}
    expected = {
        "scores_below_range",
        "scores_above_range",
        "scores_negative",
        "zero_variance_persons",
        "zero_variance_Rater",
        "person_over_observed",
    }
    missing = expected - found_names
    _self_test_assert(
        not missing,
        f"outlier detection failed to flag: {missing}. Found: {found_names}",
    )

    # Every finding has the readiness-check shape.
    for f in findings_dirty:
        for required in ("name", "severity", "headline", "detail"):
            _self_test_assert(
                required in f,
                f"finding {f.get('name', '?')!r} missing field {required!r}",
            )
        _self_test_assert(
            f["severity"] in ("ok", "warning", "issue"),
            f"finding {f['name']!r} has invalid severity {f['severity']!r}",
        )

    # Ceiling saturation (separate fixture because it requires ≥ 50 rows
    # with > 90 % at the max).
    ceiling_df = pd.DataFrame({
        "Person": [f"C{i:02d}" for i in range(60)],
        "Rater": ["R1"] * 60,
        "Task": ["T1"] * 60,
        "Score": [5] * 55 + [3, 4, 4, 5, 4],
    })
    ceiling_findings = detect_data_outliers(
        ceiling_df, person_col="Person", score_col="Score",
        facet_cols=["Rater", "Task"],
    )
    ceiling_names = {f["name"] for f in ceiling_findings}
    _self_test_assert(
        "ceiling_saturation" in ceiling_names,
        f"ceiling saturation not detected: {ceiling_names}",
    )


def _self_test_sample_data_scenarios() -> None:
    """Validate every entry in `SAMPLE_DATA_SCENARIOS` generates usable data.

    v0.2.7-beta added three new scenarios (large_writing_pca,
    speaking_test, clinical_osce) alongside the renamed default
    `writing_essay`. This test pins:
      - Every scenario generates a DataFrame whose row count matches
        its declared `n_obs`.
      - All facet columns are non-empty and have no missing levels.
      - The Score column stays inside the declared `n_cat` category
        range [0, n_cat-1].
      - Every citation in the scenario's `citations` list resolves to
        a real entry in `_APA_REFERENCE_LIBRARY`.
      - Determinism: same (key, seed) → same DataFrame bytes.
    """
    _self_test_assert(
        len(SAMPLE_DATA_SCENARIOS) >= 5,
        f"expected at least 5 scenarios, got {len(SAMPLE_DATA_SCENARIOS)}",
    )
    _self_test_assert(
        DEFAULT_SAMPLE_SCENARIO_KEY in SAMPLE_DATA_SCENARIOS,
        f"DEFAULT_SAMPLE_SCENARIO_KEY {DEFAULT_SAMPLE_SCENARIO_KEY!r} "
        "missing from registry",
    )
    data_source_options = build_data_source_options()
    labels = [opt["label"] for opt in data_source_options]
    _self_test_assert(
        len(data_source_options) == len(SAMPLE_DATA_SCENARIOS) + 2,
        "data-source radio should show every sample plus one Paste and one Upload option",
    )
    _self_test_assert(
        len(labels) == len(set(labels)),
        f"data-source radio labels must be unique, got duplicates in {labels}",
    )
    _self_test_assert(
        labels[-2:] == ["📋 Paste CSV/TSV text", "📤 Upload your own file"],
        f"data-source radio should end with Paste/Upload, got {labels[-2:]}",
    )

    for key, scenario in SAMPLE_DATA_SCENARIOS.items():
        # Metadata contract
        for required in ("label", "short", "description", "dimensions",
                         "n_obs", "build_params", "citations"):
            _self_test_assert(
                required in scenario,
                f"scenario {key!r} missing {required!r} field",
            )

        # Generate and check shape. Scenarios with a `missing_rate`
        # produce a stochastic row count (e.g., 15% MAR drop on a
        # 1,920-row design lands somewhere around 1,632 ± a few),
        # so allow a 5% tolerance on either side for those.
        df = sample_mfrm_data_by_key(key, seed=20260417)
        params_for_tol = scenario["build_params"]()
        missing_rate = float(params_for_tol.get("missing_rate", 0.0) or 0.0)
        if missing_rate > 0:
            tolerance = max(20, int(scenario["n_obs"] * 0.05))
            _self_test_assert(
                abs(df.shape[0] - scenario["n_obs"]) <= tolerance,
                f"scenario {key!r}: expected ~{scenario['n_obs']} rows "
                f"(±{tolerance} for {missing_rate:.0%} missing), "
                f"got {df.shape[0]}",
            )
        else:
            _self_test_assert(
                df.shape[0] == scenario["n_obs"],
                f"scenario {key!r}: expected {scenario['n_obs']} rows, "
                f"got {df.shape[0]}",
            )
        _self_test_assert(
            df.shape[1] == 5,
            f"scenario {key!r}: expected 5 columns, got {df.shape[1]}",
        )

        # Facet-column sanity
        for col in df.columns[:-1]:  # everything except the score column
            _self_test_assert(
                df[col].notna().all(),
                f"scenario {key!r}: column {col!r} has NaN values",
            )
            # Most facets must have ≥ 2 levels so the facet contributes
            # estimable variance, BUT a pro-forma singleton (e.g., the
            # single-scorer in the binary testlet scenario, or an
            # automatic-key design) is legitimate — MFRM simply centers
            # it to 0 at estimation. Enforce ≥ 1 level always; enforce
            # ≥ 2 only on facets that the scenario declares as
            # dimensional (persons / tasks / criteria).
            min_levels = 1 if col in ("Rater", "Scorer") else 2
            _self_test_assert(
                df[col].nunique() >= min_levels,
                f"scenario {key!r}: column {col!r} has < "
                f"{min_levels} unique level(s)",
            )

        # Score bounds
        score_col = df.columns[-1]
        n_cat = scenario["dimensions"]["n_cat"]
        scores = pd.to_numeric(df[score_col], errors="coerce")
        _self_test_assert(
            scores.notna().all(),
            f"scenario {key!r}: score column has non-numeric entries",
        )
        _self_test_assert(
            scores.min() >= 0,
            f"scenario {key!r}: negative score found (min={scores.min()})",
        )
        _self_test_assert(
            scores.max() <= n_cat - 1,
            f"scenario {key!r}: score exceeds n_cat-1 "
            f"(max={scores.max()}, n_cat={n_cat})",
        )

        # Citation resolution
        for cite in scenario["citations"]:
            key_in_map = _CITATION_TO_KEY.get(cite)
            _self_test_assert(
                key_in_map is not None,
                f"scenario {key!r}: citation {cite!r} not in "
                "_CITATION_TO_KEY",
            )
            _self_test_assert(
                key_in_map in _APA_REFERENCE_LIBRARY,
                f"scenario {key!r}: citation {cite!r} resolves to "
                f"missing reference key {key_in_map!r}",
            )

    # Determinism: same seed reproduces exactly
    df1 = sample_mfrm_data_by_key(DEFAULT_SAMPLE_SCENARIO_KEY, seed=99)
    df2 = sample_mfrm_data_by_key(DEFAULT_SAMPLE_SCENARIO_KEY, seed=99)
    _self_test_assert(
        df1.equals(df2),
        "sample_mfrm_data_by_key is non-deterministic for fixed seed",
    )

    # Backward compatibility: sample_mfrm_data() still returns the
    # legacy writing-essay shape so older tests / docs stay valid.
    legacy = sample_mfrm_data(seed=20240101)
    _self_test_assert(
        legacy.shape == (960, 5),
        f"sample_mfrm_data() legacy shape changed: {legacy.shape}",
    )
    _self_test_assert(
        list(legacy.columns) == ["Person", "Rater", "Task", "Criterion", "Score"],
        f"sample_mfrm_data() legacy columns changed: {list(legacy.columns)}",
    )


def _self_test_posterior_load_netcdf() -> None:
    """Round-trip a synthetic posterior through `_posterior_load_netcdf`.

    Builds a 2-chain × 100-draw × 3-parameter arviz object in memory,
    serialises it to NetCDF, then replays through the uploader wrapper.
    Pins the NetCDF loader path end-to-end (temp-file handling, arviz
    round-trip, summariser output shape) which the parquet test in
    `_self_test_posterior_viewer_loaders` does not cover.

    Portable across arviz 0.x (`InferenceData(posterior=xr.Dataset)`)
    and arviz 1.x (`from_dict({"posterior": {...}})` → `DataTree`). The
    serialization itself is done via the object's own `.to_netcdf(path)`
    method, which exists on both object families.
    """
    import os as _os
    import tempfile
    try:
        import arviz as _az  # noqa: N813
    except ImportError:
        return  # arviz not installed — skip gracefully
    try:
        import netCDF4  # noqa: F401
    except ImportError:
        return  # netCDF4 engine missing — skip

    rng = np.random.default_rng(20260417)
    chains, draws = 2, 100
    params = ["alpha", "beta", "sigma"]

    # Build the posterior in a way that serialises cleanly on both
    # arviz 0.x (InferenceData + xarray.Dataset) and arviz 1.x
    # (DataTree via from_dict). xarray rejects the 0.x path when given
    # an arbitrary Python dict, so branch explicitly.
    try:
        from arviz import InferenceData as _InferenceData  # type: ignore
        _has_legacy_api = True
    except ImportError:
        _has_legacy_api = False

    try:
        if _has_legacy_api:
            import xarray as _xr
            posterior = _xr.Dataset({
                name: _xr.DataArray(
                    rng.normal(0.0, 1.0, size=(chains, draws)),
                    dims=["chain", "draw"],
                )
                for name in params
            })
            idata = _InferenceData(posterior=posterior)
        else:
            # arviz >= 1.0 returns a DataTree from `from_dict`.
            idata = _az.from_dict({
                "posterior": {
                    name: rng.normal(0.0, 1.0, size=(chains, draws))
                    for name in params
                }
            })
    except Exception:
        # Some arviz/xarray combinations refuse synthetic construction.
        # Skip rather than fail CI — this test targets the *loader*,
        # so if we cannot even build a fixture, there is nothing to
        # assert against anyway.
        return

    tmp_path = None
    raw: bytes | None = None
    try:
        buf = tempfile.NamedTemporaryFile(suffix=".nc", delete=False)
        tmp_path = buf.name
        buf.close()
        try:
            idata.to_netcdf(tmp_path)
        except Exception:
            # xarray serialization quirks vary by version — skip if
            # the fixture itself cannot be persisted.
            return
        with open(tmp_path, "rb") as fh:
            raw = fh.read()
    finally:
        if tmp_path is not None:
            try:
                _os.unlink(tmp_path)
            except OSError:
                pass

    if not raw:
        return

    class _FakeUpload:
        def __init__(self, data: bytes, name: str):
            self._data = data
            self.name = name
        def getvalue(self) -> bytes:
            return self._data
        def read(self) -> bytes:
            return self._data

    fake = _FakeUpload(raw, "draws.nc")
    payload = _posterior_load_netcdf(fake)
    _self_test_assert(payload is not None, "_posterior_load_netcdf returned None")
    _self_test_assert(
        payload.get("source") == "netcdf",
        f"source tag mismatch: {payload.get('source')!r}",
    )
    _self_test_assert(
        payload.get("n_chains") == chains,
        f"n_chains mismatch: {payload.get('n_chains')}",
    )
    _self_test_assert(
        payload.get("n_draws") == draws,
        f"n_draws mismatch: {payload.get('n_draws')}",
    )
    _self_test_assert(
        set(params).issubset(set(payload.get("parameter_names", []))),
        f"parameter_names missing: {payload.get('parameter_names')}",
    )


def _self_test_posterior_load_cmdstan_csvs() -> None:
    """Round-trip synthetic CmdStan CSVs through `_posterior_load_cmdstan_csvs`.

    Writes two minimal CmdStan-style CSV files (one per chain) with a
    comment header + standard sample-stat columns + three scalar
    parameters. Confirms that `arviz.from_cmdstan` can ingest them and
    the wrapper returns a correctly-shaped payload (n_chains=2,
    n_draws=50, parameter_names includes the scalars, source="cmdstan_csv").
    """
    try:
        import arviz as _az  # noqa: N813, F401
    except ImportError:
        return

    import io as _io

    def _build_csv(chain_id: int, n_draws: int) -> bytes:
        # Minimal CmdStan CSV: a few comment lines + sample header + rows.
        lines: list[str] = []
        lines.append("# stan_version_major = 2")
        lines.append("# stan_version_minor = 32")
        lines.append("# stan_version_patch = 0")
        lines.append(f"# id = {chain_id}")
        lines.append("# method = sample (Default)")
        lines.append("lp__,accept_stat__,stepsize__,treedepth__,"
                     "n_leapfrog__,divergent__,energy__,alpha,beta,sigma")
        rng = np.random.default_rng(1000 + chain_id)
        for _ in range(n_draws):
            lp = float(rng.normal(-10.0, 0.5))
            accept = float(rng.uniform(0.8, 1.0))
            step = float(rng.uniform(0.2, 0.4))
            td = int(rng.integers(2, 6))
            nlp = 2 ** td
            div = 0
            ene = -lp + float(rng.normal(0.0, 1.0))
            alpha = float(rng.normal(0.0, 1.0))
            beta = float(rng.normal(0.5, 0.5))
            sigma = float(abs(rng.normal(1.0, 0.1)))
            lines.append(
                f"{lp:.4f},{accept:.4f},{step:.4f},{td},{nlp},{div},"
                f"{ene:.4f},{alpha:.4f},{beta:.4f},{sigma:.4f}"
            )
        return ("\n".join(lines) + "\n").encode("utf-8")

    class _FakeUpload:
        def __init__(self, data: bytes, name: str):
            self._data = data
            self.name = name
        def getvalue(self) -> bytes:
            return self._data
        def read(self) -> bytes:
            return self._data

    files = [
        _FakeUpload(_build_csv(chain_id=1, n_draws=50), "chain_1.csv"),
        _FakeUpload(_build_csv(chain_id=2, n_draws=50), "chain_2.csv"),
    ]
    try:
        payload = _posterior_load_cmdstan_csvs(files)
    except Exception:
        # If arviz rejects our minimal CSV format (stricter parsing in
        # some versions), skip rather than block CI. This test is about
        # catching regressions in our wrapper, not in arviz's parser.
        return
    if payload is None:
        return
    _self_test_assert(
        payload.get("source") == "cmdstan_csv",
        f"source tag mismatch: {payload.get('source')!r}",
    )
    # arviz may or may not preserve chain count depending on version —
    # assert the payload shape is coherent rather than a hard count.
    _self_test_assert(
        payload.get("n_chains", 0) >= 1,
        f"n_chains must be >= 1: {payload.get('n_chains')}",
    )
    _self_test_assert(
        payload.get("n_draws", 0) >= 1,
        f"n_draws must be >= 1: {payload.get('n_draws')}",
    )
    param_names = payload.get("parameter_names", [])
    _self_test_assert(
        any(p in param_names for p in ("alpha", "beta", "sigma")),
        f"none of the scalar parameter names made it through: {param_names}",
    )


def _self_test_config_json_import_whitelist() -> None:
    """Pin the 25-key config-import whitelist and its behaviour under import.

    The `_CONFIG_JSON_IMPORT_WHITELIST` set is the contract between
    `Download config (JSON)` (writer) and `Import config JSON` (reader).
    The reader filters imported keys to this whitelist; adding a key
    here without updating the exporter (or vice versa) causes silent
    drop on re-import. This test pins the size + specific critical keys
    so CI catches drift.
    """
    # Size contract — bumping this number requires an entry in CHANGELOG.
    _self_test_assert(
        len(_CONFIG_JSON_IMPORT_WHITELIST) == 25,
        f"config-import whitelist size drifted: {len(_CONFIG_JSON_IMPORT_WHITELIST)} != 25",
    )
    # Keys the sidebar MUST round-trip.
    critical_keys = {
        "model_type", "method", "analysis_depth",
        "rating_min", "rating_max",
        "maxit", "reltol", "anchor_policy",
        "facet_regularization_ui_mode", "facet_regularization_specs",
    }
    missing = critical_keys - _CONFIG_JSON_IMPORT_WHITELIST
    _self_test_assert(
        not missing,
        f"config-import whitelist missing critical keys: {missing}",
    )
    # Sanity: filter behaviour matches the inline code in the handler.
    imported_fake = {
        "model_type": "RSM",
        "method": "JMLE",
        "rating_min": 1,
        "rating_max": 5,
        "maxit": 300,
        "not_in_whitelist": "should_be_dropped",
        "config_export_fingerprint": "abc123",  # metadata, filtered
    }
    kept = {
        k: imported_fake[k]
        for k in sorted(_CONFIG_JSON_IMPORT_WHITELIST)
        if k in imported_fake
    }
    _self_test_assert(
        len(kept) == 5,
        f"expected 5 whitelisted keys to pass filter, got {len(kept)}",
    )
    _self_test_assert(
        "not_in_whitelist" not in kept and "config_export_fingerprint" not in kept,
        "whitelist filter leaked a non-whitelisted key",
    )


def _self_test_run_history_clear_confirmation() -> None:
    """Exercise the two-step run-history clear flow.

    Verifies:
    1. `record_run_in_history` pushes entries capped at `_RUN_HISTORY_MAX`.
    2. `get_run_history` returns the current list.
    3. `clear_run_history` wipes the session-state key, and subsequent
       `get_run_history` returns an empty list.
    4. The confirmation flag (`_run_history_clear_confirm`) is independent
       of the list itself, so setting / unsetting it does not mutate history.
    """
    # Baseline cleanup — pretend another test left stuff in session state.
    try:
        if _RUN_HISTORY_KEY in st.session_state:
            del st.session_state[_RUN_HISTORY_KEY]
        if "_run_history_clear_confirm" in st.session_state:
            del st.session_state["_run_history_clear_confirm"]
    except Exception:
        return  # session_state unavailable (rare in CI) — skip

    # Empty state should produce an empty list.
    _self_test_assert(
        get_run_history() == [],
        "fresh session state should yield an empty run history",
    )

    # Synthesise _RUN_HISTORY_MAX + 2 run outputs so the cap engages.
    for i in range(_RUN_HISTORY_MAX + 2):
        fake_output = {
            "model_type": "RSM",
            "_est_method": "JMLE",
            "facet_cols": ["Rater", "Task"],
            "result": {
                "summary": pd.DataFrame([{
                    "Model": "RSM", "Method": "JMLE",
                    "Converged": True, "Iterations": 10 + i,
                }]),
                "prep": {"n_obs": 100 + i, "n_person": 20 + i},
            },
        }
        record_run_in_history(output=fake_output, elapsed_sec=1.5)

    history = get_run_history()
    _self_test_assert(
        len(history) == _RUN_HISTORY_MAX,
        f"run history cap failed: {len(history)} != {_RUN_HISTORY_MAX}",
    )
    # Oldest entries were dropped — newest iteration count should survive.
    iterations = [e.get("iterations", 0) for e in history]
    _self_test_assert(
        max(iterations) == 10 + (_RUN_HISTORY_MAX + 2 - 1),
        f"newest run dropped: max iterations = {max(iterations)}",
    )

    # Simulate the two-step confirm flow.
    st.session_state["_run_history_clear_confirm"] = True
    _self_test_assert(
        get_run_history() == history,
        "setting confirm flag should not mutate history",
    )
    clear_run_history()
    _self_test_assert(
        get_run_history() == [],
        "clear_run_history did not empty the session list",
    )

    # Cleanup lingering flag so unrelated tests do not see stale state.
    try:
        if "_run_history_clear_confirm" in st.session_state:
            del st.session_state["_run_history_clear_confirm"]
    except Exception:
        pass


def _self_test_publication_document_html() -> None:
    """Build an HTML publication document from a minimal synthetic result."""
    res = {
        "config": {"model": "RSM", "method": "JMLE", "facet_names": ["Rater", "Task"], "n_cat": 5},
        "prep": {"n_obs": 120, "n_person": 20, "rating_min": 1, "rating_max": 5, "unused_score_categories": []},
        "opt": None,
        "summary": pd.DataFrame([{"Model": "RSM", "Method": "JMLE", "Converged": True, "Iterations": 42, "LogLik": -180.0}]),
        "facets": {
            "person": pd.DataFrame({"Person": [f"P{i}" for i in range(20)], "Estimate": np.linspace(-1.5, 1.5, 20)}),
            "others": pd.DataFrame({"Facet": ["Rater"] * 3, "Level": ["R1", "R2", "R3"], "Estimate": [-0.3, 0.0, 0.4]}),
        },
        "steps": pd.DataFrame({"Step": ["S1", "S2", "S3", "S4"], "Estimate": [-1.5, -0.5, 0.5, 1.5]}),
    }
    diag = {
        "measures": pd.DataFrame({
            "Facet": ["Rater"] * 3, "Level": ["R1", "R2", "R3"],
            "Estimate": [-0.3, 0.0, 0.4], "SE": [0.15, 0.14, 0.16],
        }),
        "reliability": pd.DataFrame({
            "Facet": ["Person", "Rater"], "Separation": [2.5, 1.8], "Reliability": [0.88, 0.76], "Strata": [3.7, 2.7],
        }),
    }
    data = build_publication_html_bytes(res, diag, all_bias_results={})
    _self_test_assert(isinstance(data, (bytes, bytearray)), "HTML builder did not return bytes")
    text = data.decode("utf-8", errors="replace")
    _self_test_assert("<!DOCTYPE html>" in text, "HTML doc missing DOCTYPE")
    _self_test_assert("<html" in text.lower(), "HTML doc missing <html> tag")
    _self_test_assert("Many-Facet Rasch Measurement" in text, "HTML doc missing title")
    _self_test_assert("References" in text or "reference" in text.lower(), "HTML doc missing references")
    _self_test_assert(len(data) > 2000, f"HTML doc seems too small: {len(data)} bytes")


def _self_test_diagnose_estimation_error_patterns() -> None:
    """Confirm every registered error-pattern needle round-trips through the matcher."""
    # Sample message → expected keyword for each entry in _ESTIMATION_ERROR_PATTERNS
    expected: list[tuple[str, str]] = [
        ("matrix is singular", "noncenter_facet"),
        ("Covariance not positive semi-definite", "reltol"),
        ("Reached Maximum iterations without convergence", "maxit"),
        ("Estimator did not converge.", "maxit"),
        ("all observations are extreme", "xtreme"),
        ("Rating scale cannot be constructed", "score_col"),
        ("KeyError: 'Person' column", "person_col"),
        ("empty dataframe after filter", "data"),
        ("MemoryError: could not allocate", "facet_cols"),
        ("anchor row does not exist", "anchor_df"),
    ]
    for msg, keyword in expected:
        remedy = diagnose_estimation_error(Exception(msg))
        _self_test_assert(
            remedy is not None,
            f"message {msg!r} did not match any known pattern",
        )
        _self_test_assert(
            remedy[2] == keyword,
            f"message {msg!r} expected keyword {keyword!r}, got {remedy[2]!r}",
        )
    # Unknown pattern returns None
    _self_test_assert(
        diagnose_estimation_error(Exception("a totally novel failure signature")) is None,
        "unknown pattern incorrectly matched",
    )


def _self_test_reorder_measure_columns() -> None:
    """Pin column reordering: identity + measures first, metadata last."""
    df = pd.DataFrame([{
        "Anchor": "A", "TotalCount": 10, "Level": "R1", "Infit": 1.0,
        "SE": 0.1, "Estimate": 0.5, "Facet": "Rater", "Outfit": 1.1,
        "UnknownColumn": "x",
    }])
    out = reorder_measure_columns(df)
    expected_prefix = ["Facet", "Level", "Estimate", "SE", "Infit", "Outfit"]
    _self_test_assert(
        list(out.columns)[: len(expected_prefix)] == expected_prefix,
        f"expected prefix {expected_prefix}, got {list(out.columns)[: len(expected_prefix)]}",
    )
    # Anchor / TotalCount land after the ranked columns
    anchor_idx = list(out.columns).index("Anchor")
    estimate_idx = list(out.columns).index("Estimate")
    _self_test_assert(anchor_idx > estimate_idx, "Anchor should come after Estimate")
    # Unknown columns are preserved (tail)
    _self_test_assert("UnknownColumn" in out.columns, "Unknown column dropped")
    # Truly empty DataFrame (no columns) passes through untouched
    truly_empty = pd.DataFrame()
    _self_test_assert(
        len(reorder_measure_columns(truly_empty).columns) == 0,
        "column-less DataFrame handling broke",
    )


def _self_test_style_fit_columns() -> None:
    """Pin conditional formatting for Infit / Outfit mean-square columns."""
    # DataFrame with representative fit values across all four bins
    df = pd.DataFrame({
        "Facet": ["A", "B", "C", "D"],
        "Estimate": [0.1, 0.2, 0.3, 0.4],
        "Infit": [0.3, 1.0, 1.7, 2.5],       # yellow / green / orange / red
        "Outfit": [0.4, 1.2, 1.8, 3.0],
        "Infit_ZSTD": [-2.5, 0.0, 2.5, 4.0], # ZSTD must NOT be styled
        "ReliabilityNote": ["", "", "", ""],  # string column must be ignored
    })
    styler = style_fit_columns(df)
    # When fit columns are present, we get a Styler back
    _self_test_assert(
        hasattr(styler, "to_html"),
        "style_fit_columns did not return a Styler for valid input",
    )
    # Empty / fit-less DataFrame passes through untouched
    passthrough = style_fit_columns(pd.DataFrame({"Facet": ["X"], "Value": [1]}))
    _self_test_assert(
        isinstance(passthrough, pd.DataFrame),
        "expected DataFrame passthrough for fit-less table",
    )
    # Empty input tolerated
    _self_test_assert(
        style_fit_columns(pd.DataFrame()).empty,
        "empty DataFrame mishandled",
    )


def _self_test_format_measure_table() -> None:
    """Pin the canonical rounding helper for user-facing measure tables."""
    df = pd.DataFrame({
        "Facet": ["A", "B"],
        "Estimate": [0.123456789, -0.987654321],
        "SE": [0.11111111, 0.22222222],
        "Infit": [1.234567, 0.987654],
        "Probability": [0.123456789, 0.9876543],
        "CategoryLabel": ["x", "y"],
    })
    out = format_measure_table(df)
    _self_test_assert(out["Estimate"].tolist() == [0.123, -0.988], f"Estimate rounding wrong: {out['Estimate'].tolist()}")
    _self_test_assert(out["SE"].tolist() == [0.111, 0.222], f"SE rounding wrong: {out['SE'].tolist()}")
    _self_test_assert(out["Infit"].tolist() == [1.235, 0.988], f"Infit rounding wrong: {out['Infit'].tolist()}")
    _self_test_assert(out["Probability"].tolist() == [0.1235, 0.9877], f"Prob rounding wrong: {out['Probability'].tolist()}")
    # Non-numeric columns pass through untouched
    _self_test_assert(out["CategoryLabel"].tolist() == ["x", "y"], "non-numeric column mutated")
    # Empty / non-DataFrame inputs are tolerated
    empty = format_measure_table(pd.DataFrame())
    _self_test_assert(empty.empty, "empty df handling broke")


def _self_test_apa_reference_list() -> None:
    """Pin the APA 7 reference library to the narrative conventions used here."""
    # Library is well-formed
    _self_test_assert(
        len(_APA_REFERENCE_LIBRARY) >= 30,
        f"APA library should have ≥30 entries, has {len(_APA_REFERENCE_LIBRARY)}",
    )
    # Citation-to-key map is consistent with the library
    for citation, key in _CITATION_TO_KEY.items():
        _self_test_assert(
            key in _APA_REFERENCE_LIBRARY,
            f"citation map points at missing library key: {citation} -> {key}",
        )
    # Returned entries are alphabetised and deduplicated
    narrative = (
        "Estimation follows Masters (1982) (Masters, 1982) and uses the "
        "EM algorithm of (Bock & Aitkin, 1981). Fit interpretation follows "
        "(Linacre, 2002) and (Wright & Linacre, 1994). (Masters, 1982) again."
    )
    refs = build_apa_reference_list(narrative)
    _self_test_assert(len(refs) == 4, f"expected 4 unique refs, got {len(refs)}")
    _self_test_assert(refs == sorted(refs), "reference list is not alphabetised")
    # Always-include injection works even when the citation is not in the text
    refs2 = build_apa_reference_list("No citations here.", always_include=["Andrich_1978"])
    _self_test_assert(len(refs2) == 1, "always_include failed to inject")
    _self_test_assert("Andrich, D. (1978)" in refs2[0], "always_include returned wrong entry")
    # Unknown citations are silently ignored rather than erroring
    refs3 = build_apa_reference_list("(NotACitedAuthor, 9999)")
    _self_test_assert(refs3 == [], "unknown citations must be ignored")


def export_reference_parity_fixture(output_dir: str) -> int:
    """Export deterministic Python outputs for external TAM/sirt/mirt checks."""
    out_dir = Path(output_dir).expanduser().resolve()
    out_dir.mkdir(parents=True, exist_ok=True)
    data = sample_mfrm_data(seed=20260411)
    keep_persons = data["Person"].drop_duplicates().head(8)
    data = data[data["Person"].isin(keep_persons)].copy()
    data_path = out_dir / "mfrm_parity_data_long.csv"
    data.to_csv(data_path, index=False)

    persons = data["Person"].drop_duplicates().astype(str).tolist()
    person_data = pd.DataFrame({
        "Person": persons,
        "Grade": [1 + (i // 2) for i in range(len(persons))],
        "Group": ["A" if i % 2 == 0 else "B" for i in range(len(persons))],
    })
    person_data_path = out_dir / "mfrm_parity_person_data.csv"
    person_data.to_csv(person_data_path, index=False)

    sirt_long = data.copy()
    sirt_long["SirtItem"] = sirt_long["Task"].astype(str) + "__" + sirt_long["Criterion"].astype(str)
    sirt_response = sirt_long.pivot_table(
        index=["Person", "Rater"],
        columns="SirtItem",
        values="Score",
        aggfunc="first",
    )
    sirt_item_cols = sorted(map(str, sirt_response.columns))
    sirt_response = sirt_response.reindex(columns=sirt_item_cols).reset_index()
    sirt_response.to_csv(out_dir / "sirt_rater_facets_response.csv", index=False)
    sirt_item_metadata = (
        sirt_long[["SirtItem", "Task", "Criterion"]]
        .drop_duplicates()
        .set_index("SirtItem")
        .loc[sirt_item_cols]
        .reset_index()
    )
    sirt_item_metadata.to_csv(out_dir / "sirt_rater_facets_items.csv", index=False)

    scenarios = [
        {
            "name": "jmle_rsm",
            "method": "JMLE",
            "model": "RSM",
            "mml_engine": "EM",
            "population_formula": None,
            "person_data": None,
        },
        {
            "name": "jmle_pcm_task_steps",
            "method": "JMLE",
            "model": "PCM",
            "mml_engine": "EM",
            "step_facet": "Task",
            "population_formula": None,
            "person_data": None,
        },
        {
            "name": "mml_rsm_fixed_prior",
            "method": "MML",
            "model": "RSM",
            "mml_engine": "EM",
            "population_formula": None,
            "person_data": None,
        },
        {
            "name": "mml_rsm_latent_regression",
            "method": "MML",
            "model": "RSM",
            "mml_engine": "EM",
            "population_formula": "~ Grade + Group",
            "person_data": person_data,
        },
        {
            "name": "mml_gpcm_task_steps",
            "method": "MML",
            "model": "GPCM",
            "mml_engine": "EM",
            "step_facet": "Task",
            "slope_facet": "Task",
            "population_formula": None,
            "person_data": None,
        },
    ]
    manifest_rows = []
    for scenario in scenarios:
        res = mfrm_estimate(
            data,
            person_col="Person",
            facet_cols=["Rater", "Task", "Criterion"],
            score_col="Score",
            model=scenario["model"],
            method=scenario["method"],
            step_facet=scenario.get("step_facet"),
            slope_facet=scenario.get("slope_facet"),
            mml_engine=scenario["mml_engine"],
            quad_points=7,
            population_prior_sd=1.0,
            maxit=60,
            reltol=1e-5,
            person_data=scenario["person_data"],
            person_id_col="Person" if scenario["person_data"] is not None else None,
            population_formula=scenario["population_formula"],
            population_standardize_numeric=True if scenario["population_formula"] else False,
            compute_plausible_values=scenario["method"] == "MML",
            n_plausible_values=3,
            plausible_seed=20260411,
        )
        diagnostics = mfrm_diagnostics(res, compute_pca=True, compute_marginal=scenario["method"] == "MML")
        prefix = scenario["name"]
        frames = {
            "summary": res.get("summary", pd.DataFrame()),
            "convergence": res.get("convergence", pd.DataFrame()),
            "person_measures": res.get("facets", {}).get("person", pd.DataFrame()),
            "facet_measures": res.get("facets", {}).get("others", pd.DataFrame()),
            "steps": res.get("steps", pd.DataFrame()),
            "gpcm_slopes": res.get("slopes", pd.DataFrame()),
            "population_coefficients": res.get("population", {}).get("coefficients", pd.DataFrame()),
            "population_person_data": res.get("population", {}).get("person_data", pd.DataFrame()),
            "posterior_scores": res.get("posterior", {}).get("scores", pd.DataFrame()),
            "fit_statistics": diagnostics.get("fit", pd.DataFrame()),
            "reliability": diagnostics.get("reliability", pd.DataFrame()),
            "score_map": res.get("prep", {}).get("score_map", pd.DataFrame()),
        }
        written = []
        for key, frame in frames.items():
            if isinstance(frame, pd.DataFrame) and not frame.empty:
                file_name = f"{prefix}_{key}.csv"
                frame.to_csv(out_dir / file_name, index=False)
                written.append(file_name)
        summary = res.get("summary", pd.DataFrame())
        manifest_rows.append({
            "Scenario": prefix,
            "Method": scenario["method"],
            "Model": scenario["model"],
            "StepFacet": scenario.get("step_facet"),
            "SlopeFacet": scenario.get("slope_facet"),
            "MmlEngine": res.get("config", {}).get("mml_engine"),
            "PopulationFormula": scenario["population_formula"] or "",
            "LogLik": float(summary["LogLik"].iloc[0]) if isinstance(summary, pd.DataFrame) and not summary.empty else np.nan,
            "Converged": bool(summary["Converged"].iloc[0]) if isinstance(summary, pd.DataFrame) and not summary.empty else False,
            "Files": ";".join(written),
        })
    pd.DataFrame(manifest_rows).to_csv(out_dir / "python_parity_manifest.csv", index=False)
    cross_package_validation_plan().to_csv(out_dir / "cross_package_validation_plan.csv", index=False)
    cross_package_parameterization_notes().to_csv(out_dir / "cross_package_parameterization_notes.csv", index=False)
    cross_package_tolerance_policy().to_csv(out_dir / "cross_package_tolerance_policy.csv", index=False)
    external_reference_documentation_table().to_csv(out_dir / "external_reference_documentation.csv", index=False)
    external_simulation_reference_inventory().to_csv(out_dir / "external_simulation_reference_inventory.csv", index=False)
    external_simulation_template_inventory().to_csv(out_dir / "external_simulation_template_inventory.csv", index=False)
    external_validation_artifact_checklist().to_csv(out_dir / "external_validation_artifact_checklist.csv", index=False)
    external_validation_report_template().to_csv(out_dir / "external_validation_report_template.csv", index=False)
    mfrmr_015_migration_coverage_table().to_csv(out_dir / "mfrmr_015_migration_coverage.csv", index=False)
    mfrmr_016_migration_coverage_table().to_csv(out_dir / "mfrmr_016_migration_coverage.csv", index=False)
    for name, script_text in external_simulation_template_scripts().items():
        (out_dir / name).write_text(script_text, encoding="utf-8")

    readme = """# MFRM Python Parity Fixture

This folder contains deterministic Python outputs for external comparison with
TAM, sirt, mirt, FACETS, or ConQuest. The goal is not to claim exact parameter
identity across all packages. Use it to separate expected parameterisation
differences from implementation regressions.

Files:
- `mfrm_parity_data_long.csv`: long-format data fitted by the Python app.
- `mfrm_parity_person_data.csv`: person-level covariates for latent regression.
- `sirt_rater_facets_response.csv` and `sirt_rater_facets_items.csv`: wide
  person-rater response matrix plus item metadata for a direct `sirt::rm.facets`
  rater-facet smoke check.
- `python_parity_manifest.csv`: scenario index and Python log-likelihoods.
- `cross_package_validation_plan.csv`: what to compare with TAM, sirt, mirt,
  FACETS-like, and ConQuest-style reference workflows.
- `cross_package_parameterization_notes.csv`: conventions to align before
  numerical comparisons.
- `cross_package_tolerance_policy.csv`: default review thresholds.
- `external_reference_documentation.csv`: official documentation touchpoints
  used to scope optional validation.
- `external_simulation_reference_inventory.csv`: archived validation artifacts
  that can support numerical validation without becoming runtime dependencies
  or bundled private data.
- `external_simulation_template_inventory.csv`: index of sanitized Python/R/Julia
  handoff templates for optional external validation.
- `README_external_simulation_templates.md`,
  `simulation_validation_python_template.py`,
  `simulation_validation_r_template.R`, and
  `simulation_validation_julia_template.jl`: optional sanitized handoff scripts.
- `external_validation_artifact_checklist.csv`: artifacts to archive before
  making public comparison claims.
- `external_validation_report_template.csv`: blank reviewer table for the
  final external validation summary.
- `mfrmr_015_migration_coverage.csv` and `mfrmr_016_migration_coverage.csv`:
  migration coverage maps for the mfrmr package feature surface through 0.1.6.
- `*_summary.csv`, `*_person_measures.csv`, `*_facet_measures.csv`, `*_steps.csv`:
  Python reference outputs for each scenario.
- `r_crosscheck_scaffold.R`: optional R script. It is not used by the
  Streamlit app at runtime.

Comparison rules:
- JMLE RSM/PCM is closest to FACETS-style fixed-effect estimation, but optimizer
  and constraints can still differ.
- MML RSM is closest to TAM/ConQuest-style MML, except this app fixes the prior
  SD through `population_prior_sd` rather than estimating the latent variance.
- sirt `rm.facets()` is closest for rater-facet MML with optional slopes.
- mirt is useful for broad IRT checks such as GPCM, EAP/factor scores, and
  plausible values, but it does not natively decompose arbitrary MFRM facets in
  the same long-format layout.
- Individual plausible-value draws are not expected to match; compare
  distributions and downstream regression trends.
- Strict marginal diagnostics and package residual diagnostics are screening
  evidence, not proof of model truth.
- The Python app should be described as covering the listed mfrmr 0.1.6
  migration areas with documented boundaries, not as a runtime wrapper around
  mfrmr.

Suggested tolerance policy:
- Exact row counts, category support, and missingness flags should match.
- Log-likelihood and parameter differences should be reviewed with package-
  specific constraints documented; start with absolute differences <= 0.05 logits
  for comparable centered fixed-effect measures and relax only with justification.
- Do not compare unconstrained slopes, latent variances, or anchoring constants
  as if they were the same parameter without a parameterization map.

Optional R handoff:
1. Run `Rscript r_crosscheck_scaffold.R` from this folder.
2. Review `r_crosscheck_status.csv`, `r_crosscheck_package_versions.csv`, and
   `r_crosscheck_report.md`.
3. Copy supported findings into `external_validation_report_template.csv`.
4. Keep rows marked `missing` or `error` out of public validation claims.
"""
    (out_dir / "README.md").write_text(readme, encoding="utf-8")

    r_script = """# External R cross-check scaffold for the MFRM Python parity fixture.
# Run from this folder after installing any packages you want to compare:
# install.packages(c("TAM", "sirt", "mirt", "tidyr", "dplyr"))

status <- data.frame(
  Package = character(),
  Check = character(),
  Status = character(),
  Detail = character(),
  LogLik = numeric(),
  stringsAsFactors = FALSE
)

record_status <- function(package, check, status_value, detail, logLik = NA_real_) {
  status <<- rbind(
    status,
    data.frame(
      Package = package,
      Check = check,
      Status = status_value,
      Detail = detail,
      LogLik = as.numeric(logLik),
      stringsAsFactors = FALSE
    )
  )
}

package_version_text <- function(package) {
  if (!requireNamespace(package, quietly = TRUE)) {
    return(NA_character_)
  }
  as.character(utils::packageVersion(package))
}

package_versions <- data.frame(
  Package = c("R", "TAM", "sirt", "mirt", "tidyr", "dplyr"),
  Version = c(
    paste(R.version$major, R.version$minor, sep = "."),
    package_version_text("TAM"),
    package_version_text("sirt"),
    package_version_text("mirt"),
    package_version_text("tidyr"),
    package_version_text("dplyr")
  ),
  Installed = c(
    TRUE,
    requireNamespace("TAM", quietly = TRUE),
    requireNamespace("sirt", quietly = TRUE),
    requireNamespace("mirt", quietly = TRUE),
    requireNamespace("tidyr", quietly = TRUE),
    requireNamespace("dplyr", quietly = TRUE)
  ),
  stringsAsFactors = FALSE
)
write.csv(package_versions, "r_crosscheck_package_versions.csv", row.names = FALSE)

dat <- read.csv("mfrm_parity_data_long.csv")
person_data <- read.csv("mfrm_parity_person_data.csv")
manifest <- read.csv("python_parity_manifest.csv")

if (requireNamespace("tidyr", quietly = TRUE) && requireNamespace("dplyr", quietly = TRUE)) {
  suppressPackageStartupMessages(library(dplyr))
  suppressPackageStartupMessages(library(tidyr))
  wide <- dat |>
    mutate(item_id = paste(Rater, Task, Criterion, sep = "_")) |>
    select(Person, item_id, Score) |>
    pivot_wider(id_cols = Person, names_from = item_id, values_from = Score)
  resp <- as.matrix(wide[, -1])
  rownames(resp) <- wide$Person
  facets <- dat |>
    distinct(Rater, Task, Criterion) |>
    mutate(item_id = paste(Rater, Task, Criterion, sep = "_"))

  if (requireNamespace("TAM", quietly = TRUE)) {
    message("TAM cross-check: MML/facet design reference, not exact Python parity.")
    tam_result <- tryCatch({
      tam_mod <- TAM::tam.mml.mfr(
        resp = resp,
        facets = facets[, c("Rater", "Task", "Criterion")],
        formulaA = ~ item + Rater + Task + Criterion + step,
        pid = wide$Person,
        control = list(maxiter = 120, progress = FALSE)
      )
      write.csv(tam_mod$xsi.facets, "tam_xsi_facets.csv", row.names = FALSE)
      write.csv(tam_mod$person, "tam_person.csv", row.names = FALSE)
      tam_loglik <- if (!is.null(tam_mod$deviance)) -0.5 * tam_mod$deviance else NA_real_
      record_status("TAM", "tam.mml.mfr", "ok", "Wrote tam_xsi_facets.csv and tam_person.csv", tam_loglik)
      TRUE
    }, error = function(e) {
      record_status("TAM", "tam.mml.mfr", "error", conditionMessage(e), NA_real_)
      FALSE
    })
  } else {
    record_status("TAM", "tam.mml.mfr", "missing", "Package TAM is not installed", NA_real_)
  }

  if (requireNamespace("mirt", quietly = TRUE)) {
    message("mirt cross-check: item-level GPCM check, not arbitrary-facet decomposition.")
    mirt_result <- tryCatch({
      resp0 <- resp - min(dat$Score, na.rm = TRUE)
      mirt_mod <- mirt::mirt(resp0, 1, itemtype = "gpcm", verbose = FALSE, technical = list(NCYCLES = 100))
      write.csv(as.data.frame(mirt::fscores(mirt_mod, method = "EAP")), "mirt_gpcm_eap_scores.csv")
      write.csv(as.data.frame(mirt::coef(mirt_mod, simplify = TRUE)$items), "mirt_gpcm_item_parameters.csv")
      mirt_loglik <- tryCatch(as.numeric(mirt_mod@Fit$logLik), error = function(e) NA_real_)
      record_status("mirt", "gpcm item-level", "ok", "Wrote mirt_gpcm_eap_scores.csv and mirt_gpcm_item_parameters.csv", mirt_loglik)
      TRUE
    }, error = function(e) {
      record_status("mirt", "gpcm item-level", "error", conditionMessage(e), NA_real_)
      FALSE
    })
  } else {
    record_status("mirt", "gpcm item-level", "missing", "Package mirt is not installed", NA_real_)
  }
} else {
  record_status("tidyr/dplyr", "wide data build", "missing", "Install tidyr and dplyr to run R cross-checks", NA_real_)
}

if (requireNamespace("sirt", quietly = TRUE)) {
  message("sirt cross-check: direct rater-facet smoke check with person-rater rows.")
  sirt_result <- tryCatch({
    sirt_resp <- read.csv("sirt_rater_facets_response.csv", check.names = FALSE)
    sirt_items <- read.csv("sirt_rater_facets_items.csv", check.names = FALSE)
    sirt_pid <- sirt_resp$Person
    sirt_rater <- as.character(sirt_resp$Rater)
    sirt_dat <- as.matrix(sirt_resp[, setdiff(names(sirt_resp), c("Person", "Rater")), drop = FALSE])
    storage.mode(sirt_dat) <- "numeric"
    sirt_dat <- sirt_dat - min(sirt_dat, na.rm = TRUE)
    if (!all(colnames(sirt_dat) %in% sirt_items$SirtItem)) {
      stop("sirt item metadata does not cover all response columns")
    }
    sirt_fit_log <- capture.output({
      sirt_mod <- sirt::rm.facets(
        dat = sirt_dat,
        pid = sirt_pid,
        rater = sirt_rater,
        est.b.rater = TRUE,
        est.a.item = FALSE,
        est.a.rater = FALSE,
        rater_item_int = FALSE,
        maxiter = 60
      )
    })
    saveRDS(sirt_mod, "sirt_rater_facets_model.rds")
    writeLines(sirt_fit_log, "sirt_rater_facets_fit_log.txt")
    writeLines(capture.output(print(summary(sirt_mod))), "sirt_rater_facets_summary.txt")
    sirt_loglik <- tryCatch({
      raw_loglik <- as.numeric(sirt_mod$ic$loglike)
      if (length(raw_loglik) == 0) NA_real_ else raw_loglik[1]
    }, error = function(e) NA_real_)
    record_status("sirt", "rm.facets rater fixture", "ok", "Wrote sirt_rater_facets_model.rds, fit log, and summary text", sirt_loglik)
    TRUE
  }, error = function(e) {
    record_status("sirt", "rm.facets rater fixture", "error", conditionMessage(e), NA_real_)
    FALSE
  })
} else {
  record_status("sirt", "rm.facets rater fixture", "missing", "Package sirt is not installed", NA_real_)
}

write.csv(status, "r_crosscheck_status.csv", row.names = FALSE)

report <- c(
  "# R Cross-Check Status",
  "",
  "This report records whether the generated parity fixture can be fitted by selected R packages.",
  "Use the outputs for directional checks only; exact equality is not expected because parameterisation, constraints, and latent variance handling differ.",
  "",
  "Package versions:",
  paste(capture.output(print(package_versions)), collapse = "\n"),
  "",
  paste(capture.output(print(status)), collapse = "\n"),
  "",
  "Python manifest:",
  paste(capture.output(print(manifest[, c('Scenario', 'Method', 'Model', 'LogLik', 'Converged')])), collapse = "\n")
)
writeLines(report, "r_crosscheck_report.md")

created_files <- list.files(pattern = "^(tam_|mirt_|sirt_|r_crosscheck_|external_|cross_package_|mfrmr_|python_|mfrm_|README)")
file_manifest <- data.frame(
  File = created_files,
  Bytes = file.info(created_files)$size,
  stringsAsFactors = FALSE
)
write.csv(file_manifest, "r_crosscheck_file_manifest.csv", row.names = FALSE)
message("Wrote r_crosscheck_status.csv, r_crosscheck_package_versions.csv, and r_crosscheck_report.md")
"""
    (out_dir / "r_crosscheck_scaffold.R").write_text(r_script, encoding="utf-8")
    print(f"Wrote parity fixture to: {out_dir}")
    print("Key files: mfrm_parity_data_long.csv, python_parity_manifest.csv, external_validation_report_template.csv, r_crosscheck_scaffold.R")
    return 0


def build_demo_report_frames(
    result: dict,
    diagnostics: dict,
    data: pd.DataFrame,
    all_bias_results: dict | None = None,
) -> OrderedDict[str, pd.DataFrame]:
    """Assemble beginner-facing demo report tables for CLI export."""
    frames: OrderedDict[str, pd.DataFrame] = OrderedDict()
    frames["demo_manifest"] = pd.DataFrame([
        {
            "AppVersion": APP_VERSION,
            "ReleaseLabel": APP_RELEASE_LABEL,
            "Dataset": "built-in synthetic sample",
            "Model": result.get("config", {}).get("model"),
            "Method": result.get("config", {}).get("method"),
            "RuntimeBoundary": "standalone Python; no mfrmr/rpy2/Rscript/FACETS/TAM/sirt/mirt runtime call",
            "PrivacyNote": "The demo uses synthetic built-in data only.",
            "ReadFirst": "Open publication_gate_summary, then submission_action_plan, then beginner_case_guidance, then final_report_readiness, then manuscript_claim_guide, then manuscript_template.md, then visual_interpretation_checklist, then measures and category_probability_curves.",
        }
    ])
    frames["sample_data"] = data.copy()
    summary = result.get("summary", pd.DataFrame())
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        frames["summary"] = summary
    convergence = result.get("convergence", pd.DataFrame())
    if isinstance(convergence, pd.DataFrame) and not convergence.empty:
        frames["convergence"] = convergence
    prep = result.get("prep", {})
    score_map = prep.get("score_map", pd.DataFrame())
    if isinstance(score_map, pd.DataFrame) and not score_map.empty:
        frames["score_map"] = score_map
    publication_gate = build_publication_gate_summary(result, diagnostics, all_bias_results or {})
    if isinstance(publication_gate, pd.DataFrame) and not publication_gate.empty:
        frames["publication_gate_summary"] = publication_gate
    action_plan = build_submission_action_plan(result, diagnostics, all_bias_results or {})
    if isinstance(action_plan, pd.DataFrame) and not action_plan.empty:
        frames["submission_action_plan"] = action_plan
    beginner_cases = build_beginner_case_guidance(result, diagnostics, all_bias_results or {})
    if isinstance(beginner_cases, pd.DataFrame) and not beginner_cases.empty:
        frames["beginner_case_guidance"] = beginner_cases
    readiness = build_final_report_readiness(result, diagnostics, all_bias_results or {})
    if isinstance(readiness, pd.DataFrame) and not readiness.empty:
        frames["final_report_readiness"] = readiness
    claim_guide = build_manuscript_claim_guide(result, diagnostics, all_bias_results or {})
    if isinstance(claim_guide, pd.DataFrame) and not claim_guide.empty:
        frames["manuscript_claim_guide"] = claim_guide
    frames["visual_interpretation_checklist"] = visual_interpretation_checklist()
    frames["visual_method_evidence"] = visual_method_evidence_table()
    frames["public_beta_limitations"] = public_beta_limitations_table()
    frames["external_simulation_reference_inventory"] = external_simulation_reference_inventory()
    frames["external_simulation_template_inventory"] = external_simulation_template_inventory()
    frames["mfrmr_015_migration_coverage"] = mfrmr_015_migration_coverage_table()
    frames["mfrmr_016_migration_coverage"] = mfrmr_016_migration_coverage_table()
    frames["public_release_readiness"] = public_release_readiness_table()
    person = result.get("facets", {}).get("person", pd.DataFrame())
    if isinstance(person, pd.DataFrame) and not person.empty:
        frames["person_measures"] = person
    others = result.get("facets", {}).get("others", pd.DataFrame())
    if isinstance(others, pd.DataFrame) and not others.empty:
        frames["facet_measures"] = others
    steps = result.get("steps", pd.DataFrame())
    if isinstance(steps, pd.DataFrame) and not steps.empty:
        frames["steps"] = steps
    slopes = result.get("slopes", pd.DataFrame())
    if isinstance(slopes, pd.DataFrame) and not slopes.empty:
        frames["gpcm_slopes"] = slopes
    reliability = diagnostics.get("reliability", pd.DataFrame())
    if isinstance(reliability, pd.DataFrame) and not reliability.empty:
        frames["reliability"] = reliability
    fit = diagnostics.get("fit", pd.DataFrame())
    if isinstance(fit, pd.DataFrame) and not fit.empty:
        frames["fit_statistics"] = fit
    obs = diagnostics.get("obs", pd.DataFrame())
    if isinstance(obs, pd.DataFrame) and not obs.empty:
        frames["residuals"] = obs
        try:
            cat_stats = calc_category_stats(obs, result)
            if isinstance(cat_stats, pd.DataFrame) and not cat_stats.empty:
                frames["category_diagnostics"] = cat_stats
        except Exception:
            pass
    try:
        step_order = calc_step_order(result.get("steps", pd.DataFrame()))
        if isinstance(step_order, pd.DataFrame) and not step_order.empty:
            frames["step_order"] = step_order
    except Exception:
        pass
    curve_export = category_probability_curve_export_table(result)
    if isinstance(curve_export, pd.DataFrame) and not curve_export.empty:
        frames["category_probability_curves"] = curve_export
    try:
        predictions = compute_fitted_prediction_table(result)
        if isinstance(predictions, pd.DataFrame) and not predictions.empty:
            frames["fitted_predictions"] = predictions
    except Exception:
        pass
    for pair_key, bundle in (all_bias_results or {}).items():
        table = bundle.get("table") if isinstance(bundle, dict) else None
        summary_tbl = bundle.get("summary") if isinstance(bundle, dict) else None
        safe_pair = re.sub(r"[^A-Za-z0-9]+", "_", str(pair_key)).strip("_")[:40]
        if isinstance(table, pd.DataFrame) and not table.empty:
            frames[f"bias_{safe_pair}"] = table
            dff_tbl = build_dff_bias_screening_table(bundle)
            if isinstance(dff_tbl, pd.DataFrame) and not dff_tbl.empty:
                frames[f"dff_bias_{safe_pair}"] = dff_tbl
        if isinstance(summary_tbl, pd.DataFrame) and not summary_tbl.empty:
            frames[f"bias_{safe_pair}_summary"] = summary_tbl
    return frames


def export_demo_report(output_dir: str) -> int:
    """Export a deterministic beginner-facing demo report from built-in sample data."""
    out_dir = Path(output_dir).expanduser().resolve()
    out_dir.mkdir(parents=True, exist_ok=True)
    data = sample_mfrm_data(seed=20260411)
    keep_persons = data["Person"].drop_duplicates().head(12)
    data = data[data["Person"].isin(keep_persons)].copy()
    data.to_csv(out_dir / "demo_sample_data.csv", index=False)

    result = mfrm_estimate(
        data,
        person_col="Person",
        facet_cols=["Rater", "Task", "Criterion"],
        score_col="Score",
        model="PCM",
        method="JMLE",
        step_facet="Task",
        maxit=80,
        reltol=1e-5,
    )
    diagnostics = mfrm_diagnostics(result, compute_pca=True, compute_marginal=False)
    all_bias_results: dict[str, dict] = {}
    try:
        all_bias_results["Rater x Task"] = estimate_bias_interaction(
            result,
            diagnostics,
            "Rater",
            "Task",
            max_abs=10.0,
            omit_extreme=True,
        )
    except Exception:
        all_bias_results = {}

    frames = build_demo_report_frames(result, diagnostics, data, all_bias_results=all_bias_results)
    method_appendix = generate_method_appendix_text(result, diagnostics, all_bias_results=all_bias_results)
    manuscript_template = generate_manuscript_reporting_template(result, diagnostics, all_bias_results=all_bias_results)
    for name, frame in frames.items():
        frame.to_csv(out_dir / f"{name}.csv", index=False)
    (out_dir / "MFRM_Demo_Report.xlsx").write_bytes(to_excel_bytes(frames))
    (out_dir / "MFRM_Demo_Report.html").write_bytes(to_html_report(frames, title="MFRM Demo Report"))
    (out_dir / "MFRM_Demo_Report.zip").write_bytes(build_osf_zip(
        frames,
        title="MFRM_Demo_Report",
        text_assets={
            "method_appendix.md": method_appendix,
            "manuscript_template.md": manuscript_template,
            **external_simulation_template_scripts(),
        },
    ))
    (out_dir / "method_appendix.md").write_text(method_appendix, encoding="utf-8")
    (out_dir / "manuscript_template.md").write_text(manuscript_template, encoding="utf-8")
    for name, script_text in external_simulation_template_scripts().items():
        (out_dir / name).write_text(script_text, encoding="utf-8")

    figure_html: dict[str, str] = {}
    figure_png: dict[str, bytes] = {}
    figure_measures = diagnostics.get("measures", pd.DataFrame())
    facets_data = result.get("facets", {})
    _add_figure_export(
        _make_wright_map_export_figure(
            facets_data.get("person", pd.DataFrame()),
            facets_data.get("others", pd.DataFrame()),
            result.get("steps", pd.DataFrame()),
        ),
        "wright_map",
        figure_png,
        figure_html,
    )
    _add_figure_export(
        _make_fit_scatter_export_figure(figure_measures),
        "fit_scatter",
        figure_png,
        figure_html,
    )
    _add_figure_export(
        _make_facet_distribution_export_figure(figure_measures),
        "facet_distribution",
        figure_png,
        figure_html,
    )
    curve_options = category_probability_curve_options(result)
    for row in curve_options.itertuples(index=False):
        is_average = bool(getattr(row, "IsAverage"))
        level_idx = None if is_average else int(getattr(row, "LevelIndex"))
        curve = build_category_probability_curve_data(result, step_level_index=level_idx)
        fig_curve, fig_expected = _make_category_probability_curve_figures(curve)
        safe_label = re.sub(r"[^A-Za-z0-9]+", "_", str(getattr(row, "Label"))).strip("_")[:80] or "curve"
        if fig_curve is not None:
            _add_figure_export(
                fig_curve,
                f"category_probability_curve_{safe_label}",
                figure_png,
                figure_html,
            )
        if fig_expected is not None:
            _add_figure_export(
                fig_expected,
                f"expected_score_curve_{safe_label}",
                figure_png,
                figure_html,
            )
    figure_manifest = _figure_export_manifest(figure_html, figure_png)
    if not figure_manifest.empty:
        figure_manifest.to_csv(out_dir / "figure_manifest.csv", index=False)
        figure_assets = _figure_bundle_assets(figure_html, figure_png, figure_manifest)
        (out_dir / "MFRM_Demo_Publication_Figures.zip").write_bytes(
            cached_mixed_asset_zip(figure_assets, bytes_mapping_fingerprint(figure_assets))
        )
    if figure_html:
        fig_dir = out_dir / "figures_html"
        fig_dir.mkdir(exist_ok=True)
        for name, html in figure_html.items():
            (fig_dir / f"{name}.html").write_text(html, encoding="utf-8")
        (out_dir / "MFRM_Demo_Figures_HTML.zip").write_bytes(cached_named_asset_zip(figure_html, bytes_mapping_fingerprint(figure_html), "html"))
    if figure_png:
        png_dir = out_dir / "figures_png"
        png_dir.mkdir(exist_ok=True)
        for name, png in figure_png.items():
            (png_dir / f"{name}.png").write_bytes(png)
        (out_dir / "MFRM_Demo_Figures_PNG.zip").write_bytes(cached_named_asset_zip(figure_png, bytes_mapping_fingerprint(figure_png), "png"))

    readme = f"""# MFRM Demo Report

This folder was generated from the app's built-in synthetic sample data.
It demonstrates the standalone Python workflow without calling `mfrmr`,
`rpy2`, `Rscript`, FACETS, TAM, sirt, or mirt at runtime.

## Files to open first

1. `MFRM_Demo_Report.html`: browser-readable table report.
2. `publication_gate_summary.csv`: whether APA-style conclusions are ready, caveated, or blocked.
3. `submission_action_plan.csv`: prioritized blockers, caveats, boundaries, and wording repairs before manuscript use.
4. `beginner_case_guidance.csv`: case-specific cautions for common beginner interpretation traps.
5. `final_report_readiness.csv`: what to resolve before final reporting.
6. `manuscript_claim_guide.csv`: what is safe to claim in a manuscript.
7. `manuscript_template.md`: Methods, Results, limitations, and reviewer preflight scaffold.
8. `visual_interpretation_checklist.csv`: how to read each plot.
9. `visual_method_evidence.csv`: methodological basis and readability rules for plots.
10. `public_beta_limitations.csv`: what this beta release supports and does not claim.
11. `external_simulation_reference_inventory.csv`: archived validation artifacts
   to consult without bundling private data.
12. `external_simulation_template_inventory.csv`: index of sanitized Python/R/Julia
   external validation templates.
13. `README_external_simulation_templates.md` and `simulation_validation_*`:
   sanitized handoff scripts for optional external validation.
14. `mfrmr_015_migration_coverage.csv` and `mfrmr_016_migration_coverage.csv`: how the mfrmr package feature surface through 0.1.6 maps to this Python app.
15. `public_release_readiness.csv`: repository-level public release checklist.
16. `category_probability_curves.csv`: long-form PCM curve data for the
   averaged view and each Task level.
17. `figure_manifest.csv`: manuscript-use notes and available formats for exported figures.
18. `MFRM_Demo_Publication_Figures.zip`: publication-styled PNG/HTML figure bundle.
19. `figures_html/`: interactive publication-styled diagnostic figures.
20. `method_appendix.md`: reproducible method notes for this demo run.

## Demo model

- Model: PCM
- Estimation: JMLE
- Step facet: Task
- Observations: {len(data):,}
- App version: {APP_VERSION}

The data are synthetic, but the report structure is the same one to use with
real rating data. For confidential real data, run locally and remove direct
identifiers before upload or paste.
"""
    (out_dir / "README.md").write_text(readme, encoding="utf-8")
    print(f"Wrote demo report to: {out_dir}")
    print("Key files: MFRM_Demo_Report.html, MFRM_Demo_Report.xlsx, publication_gate_summary.csv, submission_action_plan.csv, beginner_case_guidance.csv, final_report_readiness.csv, manuscript_claim_guide.csv, manuscript_template.md, figure_manifest.csv, MFRM_Demo_Publication_Figures.zip, figures_html/")
    return 0


def _benchmark_data_subset(base: pd.DataFrame, n_persons: int) -> pd.DataFrame:
    keep_persons = base["Person"].drop_duplicates().head(int(n_persons))
    return base[base["Person"].isin(keep_persons)].copy()


def _benchmark_bias_scan(result: dict, diagnostics: dict, facet_cols: list[str], bias_mode: str) -> tuple[float, int]:
    if bias_mode == "Skip":
        return 0.0, 0
    pairs_available = list(combinations(["Person"] + list(facet_cols), 2))
    if bias_mode == "All facet pairs":
        pairs = pairs_available
    elif bias_mode == "Selected pair" and pairs_available:
        pairs = [pairs_available[0]]
    else:
        pairs = []
    start_time = time.perf_counter()
    n_tables = 0
    for facet_a, facet_b in pairs:
        try:
            bundle = estimate_bias_interaction(
                result,
                diagnostics,
                facet_a,
                facet_b,
                max_abs=10.0,
                omit_extreme=True,
            )
            table = bundle.get("table") if isinstance(bundle, dict) else None
            if isinstance(table, pd.DataFrame) and not table.empty:
                n_tables += 1
        except Exception:
            continue
    return float(time.perf_counter() - start_time), n_tables


def _version_tuple(version_text: str) -> tuple[int, ...]:
    parts = re.findall(r"\d+", str(version_text))
    return tuple(int(part) for part in parts[:3]) if parts else (0,)


def _version_meets_floor(version_text: str, floor_text: str) -> bool:
    observed = _version_tuple(version_text)
    floor = _version_tuple(floor_text)
    max_len = max(len(observed), len(floor))
    observed = observed + (0,) * (max_len - len(observed))
    floor = floor + (0,) * (max_len - len(floor))
    return observed >= floor


def run_doctor(json_output: bool = False) -> int:
    """Run lightweight environment checks for local support and CI."""
    rows = []

    def record(check: str, status: str, detail: str) -> None:
        rows.append({"Check": check, "Status": status, "Detail": detail})

    record(
        "app_version",
        "ok",
        f"{APP_RELEASE_LABEL} {APP_VERSION}; standalone Python; no external MFRM engine is called",
    )
    record(
        "python",
        "ok" if sys.version_info >= (3, 11) else "warn",
        sys.version.split()[0],
    )

    for package_name, floor in RUNTIME_PACKAGE_FLOORS.items():
        try:
            version_text = importlib_metadata.version(package_name)
            status = "ok" if _version_meets_floor(version_text, floor) else "warn"
            record(f"package:{package_name}", status, f"{version_text} (required >= {floor})")
        except importlib_metadata.PackageNotFoundError:
            record(f"package:{package_name}", "error", f"missing (required >= {floor})")

    for asset_name in BUNDLED_ANCHOR_ASSETS:
        try:
            path = _bundled_asset_path(asset_name)
            payload = get_bundled_asset_bytes(asset_name)
            status = "ok" if payload else "error"
            record(f"asset:{asset_name}", status, f"{len(payload)} bytes at {path.name}")
        except Exception as exc:
            record(f"asset:{asset_name}", "error", str(exc))

    try:
        sample = cached_sample_mfrm_data(seed=20240101)
        record("sample_data", "ok" if isinstance(sample, pd.DataFrame) and not sample.empty else "error", f"{getattr(sample, 'shape', None)}")
    except Exception as exc:
        record("sample_data", "error", str(exc))

    try:
        ns = load_core_namespace()
        required_names = ["mfrm_estimate", "mfrm_diagnostics", "read_flexible_table"]
        missing = [name for name in required_names if name not in ns]
        record("core_namespace", "ok" if not missing else "error", "missing: " + ", ".join(missing) if missing else f"{len(ns)} functions")
    except Exception as exc:
        record("core_namespace", "error", str(exc))

    record(
        "privacy_boundary",
        "ok",
        "uploaded/pasted rating data are not cached as resources; export-byte caches are bounded and short-lived",
    )
    record(
        "runtime_boundary",
        "ok",
        "mfrmr, rpy2, Rscript, FACETS, TAM, sirt, and mirt are not runtime dependencies",
    )

    if json_output:
        print(json.dumps(rows, indent=2, ensure_ascii=False))
    else:
        width = max(len(row["Check"]) for row in rows) if rows else 5
        for row in rows:
            print(f"[{row['Status'].upper():5}] {row['Check']:<{width}}  {row['Detail']}")

    return 1 if any(row["Status"] == "error" for row in rows) else 0


def run_release_check(json_output: bool = False) -> int:
    """Run static public-beta release readiness checks."""
    readiness = public_release_readiness_table()
    limitations = public_beta_limitations_table()
    migration = mfrmr_015_migration_coverage_table()
    migration_016 = mfrmr_016_migration_coverage_table()
    simulation_inventory = external_simulation_reference_inventory()
    simulation_templates = external_simulation_template_inventory()
    payload = {
        "release_status": "public beta / research preview",
        "app_version": APP_VERSION,
        "release_label": APP_RELEASE_LABEL,
        "readiness": readiness.to_dict(orient="records"),
        "limitations": limitations.to_dict(orient="records"),
        "external_simulation_reference_inventory": simulation_inventory.to_dict(orient="records"),
        "external_simulation_template_inventory": simulation_templates.to_dict(orient="records"),
        "mfrmr_015_migration_coverage": migration.to_dict(orient="records"),
        "mfrmr_016_migration_coverage": migration_016.to_dict(orient="records"),
    }
    if json_output:
        print(json.dumps(payload, indent=2, ensure_ascii=False))
    else:
        print(f"Release status: public beta / research preview ({APP_RELEASE_LABEL} {APP_VERSION})")
        print("\nReadiness checks:")
        width = max(len(str(v)) for v in readiness["Check"].tolist()) if not readiness.empty else 5
        for _, row in readiness.iterrows():
            print(f"[{str(row['Status']).upper():10}] {str(row['Check']):<{width}}  {row['Evidence']}")
            print(f"{'':13} {row['Action']}")
        print("\nPublic beta limitations:")
        for _, row in limitations.iterrows():
            print(f"- {row['Area']}: {row['PublicBetaStatus']} - {row['Boundary']}")
        print(f"\nArchived validation artifact inventory rows: {len(simulation_inventory)}")
        print(f"\nExternal validation template rows: {len(simulation_templates)}")
        print(f"\nmfrmr 0.1.5 migration coverage rows: {len(migration)}")
        print(f"mfrmr 0.1.6 migration coverage rows: {len(migration_016)}")
    blocker_count = int((readiness["Status"].astype(str) == "Blocker").sum()) if "Status" in readiness.columns else 1
    return 1 if blocker_count else 0


def run_benchmarks(csv_path: str | None = None, quick: bool = False) -> int:
    """Run small benchmark snapshots without opening Streamlit."""
    base = sample_mfrm_data(seed=20260411)
    facet_cols = ["Rater", "Task", "Criterion"]
    scenarios = [
        {
            "Scenario": "small_fast_preview_jmle_rsm",
            "Persons": 6,
            "Model": "RSM",
            "Method": "JMLE",
            "AnalysisDepth": "Fast preview",
            "Maxit": 40,
            "Reltol": 1e-3,
            "QuadPoints": None,
        },
        {
            "Scenario": "medium_standard_jmle_rsm",
            "Persons": 15,
            "Model": "RSM",
            "Method": "JMLE",
            "AnalysisDepth": "Standard (recommended)",
            "Maxit": 40,
            "Reltol": 1e-3,
            "QuadPoints": None,
        },
        {
            "Scenario": "large_standard_jmle_rsm",
            "Persons": 30,
            "Model": "RSM",
            "Method": "JMLE",
            "AnalysisDepth": "Standard (recommended)",
            "Maxit": 40,
            "Reltol": 1e-3,
            "QuadPoints": None,
        },
        {
            "Scenario": "small_full_publication_mml_rsm",
            "Persons": 6,
            "Model": "RSM",
            "Method": "MML",
            "AnalysisDepth": "Full publication",
            "Maxit": 8,
            "Reltol": 1e-3,
            "QuadPoints": 5,
        },
        {
            "Scenario": "small_full_publication_mml_pcm",
            "Persons": 6,
            "Model": "PCM",
            "Method": "MML",
            "AnalysisDepth": "Full publication",
            "Maxit": 8,
            "Reltol": 1e-3,
            "QuadPoints": 5,
        },
        {
            "Scenario": "small_full_publication_mml_gpcm",
            "Persons": 6,
            "Model": "GPCM",
            "Method": "MML",
            "AnalysisDepth": "Full publication",
            "Maxit": 8,
            "Reltol": 1e-3,
            "QuadPoints": 5,
        },
        {
            "Scenario": "small_full_publication_mml_latent_regression",
            "Persons": 6,
            "Model": "RSM",
            "Method": "MML",
            "AnalysisDepth": "Full publication",
            "Maxit": 8,
            "Reltol": 1e-3,
            "QuadPoints": 5,
            "PopulationFormula": "~ Grade + Group",
        },
    ]
    if quick:
        keep_scenarios = {
            "small_fast_preview_jmle_rsm",
            "small_full_publication_mml_rsm",
        }
        scenarios = [scenario for scenario in scenarios if scenario["Scenario"] in keep_scenarios]
    rows = []
    for scenario in scenarios:
        data = _benchmark_data_subset(base, scenario["Persons"])
        person_data = None
        if scenario.get("PopulationFormula"):
            persons = data["Person"].drop_duplicates().astype(str).tolist()
            person_data = pd.DataFrame({
                "Person": persons,
                "Grade": [1 + (i // 2) for i in range(len(persons))],
                "Group": ["A" if i % 2 == 0 else "B" for i in range(len(persons))],
            })
        settings = resolve_analysis_depth_settings(
            scenario["AnalysisDepth"],
            scenario["Method"],
        )
        fit_start = time.perf_counter()
        result = mfrm_estimate(
            data,
            person_col="Person",
            facet_cols=facet_cols,
            score_col="Score",
            model=scenario["Model"],
            method=scenario["Method"],
            mml_engine="Auto (recommended)",
            quad_points=int(scenario["QuadPoints"] or 5),
            maxit=int(scenario["Maxit"]),
            reltol=float(scenario["Reltol"]),
            person_data=person_data,
            person_id_col="Person" if person_data is not None else None,
            population_formula=scenario.get("PopulationFormula"),
            compute_plausible_values=bool(settings["compute_plausible_values"]),
            n_plausible_values=int(settings["n_plausible_values"]),
            plausible_seed=int(settings["plausible_seed"]),
        )
        estimate_seconds = float(time.perf_counter() - fit_start)

        diag_start = time.perf_counter()
        diagnostics = mfrm_diagnostics(
            result,
            compute_pca=bool(settings["compute_residual_pca"]),
            compute_marginal=bool(settings["compute_strict_marginal"]),
            marginal_pairwise=bool(settings["strict_marginal_pairwise"]),
            marginal_max_pair_cells=int(settings["strict_marginal_max_pair_cells"]),
            compute_eb_shrinkage=bool(settings["compute_eb_shrinkage"]),
        )
        diagnostics_seconds = float(time.perf_counter() - diag_start)
        bias_seconds, bias_tables = _benchmark_bias_scan(
            result,
            diagnostics,
            facet_cols,
            settings["bias_mode"],
        )

        summary = result["summary"].iloc[0]
        rows.append({
            "Scenario": scenario["Scenario"],
            "AnalysisDepth": scenario["AnalysisDepth"],
            "Method": scenario["Method"],
            "Model": scenario["Model"],
            "Rows": int(len(data)),
            "Persons": int(data["Person"].nunique()),
            "FacetCount": int(len(facet_cols)),
            "Categories": int(result["config"]["n_cat"]),
            "Maxit": int(scenario["Maxit"]),
            "Reltol": float(scenario["Reltol"]),
            "QuadPoints": scenario["QuadPoints"],
            "PopulationFormula": scenario.get("PopulationFormula", ""),
            "MmlEngine": result["config"].get("mml_engine"),
            "ComputePCA": bool(settings["compute_residual_pca"]),
            "ComputeStrictMarginal": bool(settings["compute_strict_marginal"]),
            "StrictMarginalPairwise": bool(settings["strict_marginal_pairwise"]),
            "ComputePlausibleValues": bool(settings["compute_plausible_values"]),
            "PlausibleValues": int(settings["n_plausible_values"]),
            "BiasMode": settings["bias_mode"],
            "BiasTables": int(bias_tables),
            "EstimateSeconds": estimate_seconds,
            "DiagnosticsSeconds": diagnostics_seconds,
            "BiasSeconds": float(bias_seconds),
            "TotalSeconds": estimate_seconds + diagnostics_seconds + float(bias_seconds),
            "Converged": bool(summary.get("Converged", False)),
            "Iterations": int(summary.get("Iterations", 0) or 0),
            "GradientNorm": float(summary.get("GradientNorm", np.nan)),
            "LogLik": float(summary.get("LogLik", np.nan)),
        })

    out = pd.DataFrame(rows)
    display_cols = [
        "Scenario",
        "Rows",
        "Method",
        "Model",
        "AnalysisDepth",
        "MmlEngine",
        "EstimateSeconds",
        "DiagnosticsSeconds",
        "BiasSeconds",
        "TotalSeconds",
        "Converged",
        "Iterations",
        "GradientNorm",
    ]
    print(out[display_cols].to_string(index=False))
    if csv_path:
        csv_out_path = Path(csv_path).expanduser()
        csv_out_path.parent.mkdir(parents=True, exist_ok=True)
        out.to_csv(csv_out_path, index=False)
        print(f"\nWrote benchmark snapshot: {csv_out_path}")
    return 0


def _self_test_csv_newline_normalization() -> None:
    """Pasted and uploaded CSV/TSV data should parse after newline normalization."""
    csv_text = "Person,Rater,Score\rP1,R1,1\rP2,R2,2\r"
    df = read_flexible_table(csv_text, None, header=True)
    _self_test_assert(df.shape == (2, 3), f"CR-only pasted CSV parsed to {df.shape}")
    _self_test_assert(df.iloc[1]["Person"] == "P2", "CR-only pasted CSV row order changed")

    class _Upload:
        name = "ratings.csv"

        def getvalue(self):
            return b"Person,Rater,Score\r\nP1,R1,1\r\nP2,R2,2\r\n"

    uploaded = read_flexible_table("", _Upload(), header=True)
    _self_test_assert(uploaded.shape == (2, 3), f"CRLF uploaded CSV parsed to {uploaded.shape}")
    _self_test_assert(normalize_csv_newlines("a\rb\r\nc") == "a\nb\nc", "text newline normalization failed")
    _self_test_assert(normalize_csv_newlines(b"a\rb\r\nc") == b"a\nb\nc", "byte newline normalization failed")


def _self_test_table_delimiter_and_stale_fingerprints() -> None:
    """Table parsing and stale-input fingerprints should catch common UX traps."""
    semi_text = "Person;Rater;Score\rP1;R1;1\rP2;R2;2\r"
    parsed = read_flexible_table(semi_text, None, header=True, delimiter="Auto")
    _self_test_assert(parsed.shape == (2, 3), f"semicolon pasted table parsed to {parsed.shape}")
    forced_comma = read_flexible_table(semi_text, None, header=True, delimiter="Comma (,)")
    _self_test_assert(forced_comma.shape[1] == 1, "forced comma delimiter should expose one-column parse")

    class _SemiUpload:
        name = "ratings.csv"
        size = len(b"Person;Rater;Score\nP1;R1;1\n")

        def getvalue(self):
            return b"Person;Rater;Score\nP1;R1;1\nP2;R2;2\n"

    uploaded = read_flexible_table("", _SemiUpload(), header=True, delimiter="Auto")
    _self_test_assert(uploaded.shape == (2, 3), f"semicolon uploaded CSV parsed to {uploaded.shape}")
    _self_test_assert(infer_table_delimiter(semi_text) == ";", "semicolon delimiter inference failed")

    class _ExcelUpload:
        name = "ratings.xlsx"

        def getvalue(self):
            buf = io.BytesIO()
            pd.DataFrame({"Person": ["P1", "P2"], "Rater": ["R1", "R2"], "Score": [1, 2]}).to_excel(
                buf, index=False, engine="openpyxl"
            )
            return buf.getvalue()

    xlsx = read_flexible_table("", _ExcelUpload(), header=True)
    _self_test_assert(xlsx.shape == (2, 3), f"Excel uploaded table parsed to {xlsx.shape}")

    class _JsonUpload:
        name = "ratings.json"

        def getvalue(self):
            return b'[{"Person":"P1","Rater":"R1","Score":1},{"Person":"P2","Rater":"R2","Score":2}]'

    parsed_json = read_flexible_table("", _JsonUpload(), header=True)
    _self_test_assert(parsed_json.shape == (2, 3), f"JSON uploaded table parsed to {parsed_json.shape}")

    class _ParquetUpload:
        name = "ratings.parquet"

        def getvalue(self):
            buf = io.BytesIO()
            pd.DataFrame({"Person": ["P1", "P2"], "Rater": ["R1", "R2"], "Score": [1, 2]}).to_parquet(
                buf, index=False
            )
            return buf.getvalue()

    parsed_parquet = read_flexible_table("", _ParquetUpload(), header=True)
    _self_test_assert(parsed_parquet.shape == (2, 3), f"Parquet uploaded table parsed to {parsed_parquet.shape}")

    data_a = pd.DataFrame({"Person": ["P1"], "Rater": ["R1"], "Score": [1]})
    data_b = pd.DataFrame({"Person": ["P1"], "Rater": ["R1"], "Score": [2]})
    fp_a = dataframe_fingerprint(data_a)
    fp_b = dataframe_fingerprint(data_b)
    anchor_a = table_source_fingerprint(text_value="Facet,Level,Anchor\nRater,R1,0\n")
    anchor_b = table_source_fingerprint(text_value="Facet,Level,Anchor\nRater,R1,1\n")
    output = {
        "_input_data_fingerprint": fp_a,
        "_anchor_source_fingerprint": anchor_a,
        "_group_anchor_source_fingerprint": None,
        "_population_source_fingerprint": None,
        "result": {"config": {}},
    }
    reasons = build_input_stale_reasons(
        output,
        current_input_data_fingerprint=fp_b,
        current_anchor_source_fingerprint=anchor_b,
        current_group_anchor_source_fingerprint=None,
        current_population_source_fingerprint=None,
    )
    _self_test_assert("rating data" in reasons, "changed rating data fingerprint was not stale")
    _self_test_assert("anchor input" in reasons, "changed anchor source fingerprint was not stale")


def _self_test_likelihood_information_criteria() -> None:
    summary = pd.DataFrame([{
        "Model": "RSM",
        "Method": "JMLE",
        "N": 100,
        "KParams": 8,
        "LogLik": -50.0,
        "AIC": 116.0,
        "BIC": 136.841361,
    }])
    result = {"summary": summary, "config": {"parameter_count": 8}}
    info = build_likelihood_information_criteria(result)
    _self_test_assert(not info.empty, "likelihood information table is empty")
    values = dict(zip(info["Metric"], info["Value"]))
    _self_test_assert(abs(float(values["Deviance"]) - 100.0) < 1e-8, "deviance should equal -2LL")
    _self_test_assert("AICPerObs" in values and abs(float(values["AICPerObs"]) - 1.16) < 1e-8, "AIC per observation missing")

    history = [
        {"timestamp": "A", "output_snapshot": {"result": result}},
        {"timestamp": "B", "output_snapshot": {"result": {
            "summary": pd.DataFrame([{
                "Model": "PCM",
                "Method": "JMLE",
                "N": 100,
                "KParams": 12,
                "LogLik": -46.0,
                "AIC": 116.0,
                "BIC": 147.262042,
            }]),
            "config": {"parameter_count": 12},
        }}},
    ]
    rows = build_run_history_likelihood_table(history)
    _self_test_assert(len(rows) == 2, "run-history likelihood table row count changed")
    _self_test_assert("DeltaAIC" in rows.columns and rows["DeltaAIC"].min() == 0, "DeltaAIC not computed")
    _self_test_assert(
        "ComparableIC" in rows.columns and not bool(rows["ComparableIC"].all()),
        "run-history ComparableIC should be false when model/method/data comparability differs",
    )
    desc = build_likelihood_descriptives(rows)
    _self_test_assert("AIC" in desc["Metric"].tolist(), "likelihood descriptives missing AIC")


def _self_test_dff_bias_screening() -> None:
    bias_tbl = pd.DataFrame({
        "FacetA": ["Rater", "Rater", "Rater"],
        "FacetA_Level": ["R1", "R2", "R3"],
        "FacetB": ["Task", "Task", "Task"],
        "FacetB_Level": ["T1", "T1", "T2"],
        "ObsN": [30, 4, 30],
        "Bias Size": [0.80, 0.10, 0.60],
        "S.E.": [0.10, 0.50, 0.30],
        "t": [8.0, 0.2, 2.0],
        "Prob.": [0.001, 0.84, 0.046],
    })
    dff = build_dff_bias_screening_table({"table": bias_tbl}, alpha=0.05, min_n=5, practical_logit=0.5)
    _self_test_assert(not dff.empty and "p_holm" in dff.columns and "p_bh" in dff.columns, "DFF table missing adjusted p-values")
    _self_test_assert("Strong review" in dff["EvidenceLevel"].astype(str).tolist(), "strong DFF review flag missing")
    _self_test_assert("Sparse cell" in dff["EvidenceLevel"].astype(str).tolist(), "sparse DFF cell flag missing")
    summary = summarize_dff_bias_screening(dff)
    _self_test_assert(not summary.empty, "DFF screening summary is empty")
    values = dict(zip(summary["Metric"], summary["Value"]))
    _self_test_assert(int(values.get("Flagged cells", 0)) >= 2, "DFF summary undercounts flagged cells")


def _self_test_facet_regularization() -> None:
    """Facet regularization should be explicit, audited, and gradient-safe."""
    data = _make_self_test_gradient_data()
    spec = [{
        "Facet": "Rater",
        "Level": "*",
        "ParameterClass": "facet",
        "Mean": 0.0,
        "SD": 3.0,
        "Enabled": True,
        "Source": "self_test",
    }]
    res = mfrm_estimate(
        data,
        person_col="Person",
        facet_cols=["Rater", "Task"],
        score_col="Score",
        model="RSM",
        method="JMLE",
        facet_regularization={"enabled": True, "specs": spec},
        maxit=20,
        reltol=1e-4,
    )
    summary = res["summary"].iloc[0]
    _self_test_assert(summary.get("FacetRegularization") == "On", "regularized run was not labelled On")
    _self_test_assert(str(summary.get("EstimatorLabel")) == "Penalized JMLE", "regularized estimator label changed")
    _self_test_assert(np.isfinite(float(summary.get("RegularizationPenalty"))), "regularization penalty is not finite")
    _self_test_assert(np.isfinite(float(summary.get("PenalizedObjective"))), "penalized objective is not finite")
    _self_test_assert(
        str(summary.get("LogLikBasis")) == "unpenalized likelihood evaluated at fitted estimates",
        "log-likelihood basis note changed",
    )
    info = build_likelihood_information_criteria(res)
    _self_test_assert(
        "RegularizationPenalty" in info["Metric"].tolist(),
        "likelihood information table omits regularization penalty",
    )
    reg = res.get("regularization", {})
    audit = reg.get("audit", pd.DataFrame()) if isinstance(reg, dict) else pd.DataFrame()
    penalty_summary = reg.get("penalty_summary", pd.DataFrame()) if isinstance(reg, dict) else pd.DataFrame()
    _self_test_assert(not audit.empty, "regularization audit table is empty")
    _self_test_assert(
        bool(audit["Status"].astype(str).str.startswith("applied").any()),
        "regularization audit has no applied row",
    )
    _self_test_assert(
        not penalty_summary.empty and "TOTAL" in penalty_summary["Facet"].astype(str).tolist(),
        "regularization penalty summary missing TOTAL row",
    )
    appendix = generate_method_appendix_text(res, {"marginal_fit_enabled": False}, all_bias_results={})
    _self_test_assert("## Facet Regularization" in appendix, "method appendix missing facet regularization section")
    _self_test_assert("not a random-effects model" in appendix, "method appendix missing regularization caveat")

    par = np.asarray(res["opt"].x, dtype=float)
    if par.size:
        par = par + np.random.default_rng(20260501).normal(0.0, 0.03, par.size)
    config = res["config"]
    sizes = build_param_sizes(config)
    idx = build_indices(res["prep"], step_facet=config["step_facet"], slope_facet=config.get("slope_facet"))
    rel_err, abs_err = _central_difference_gradient_check(
        lambda x: mfrm_loglik_jmle_value_grad(x, idx, config, sizes),
        par,
    )
    _self_test_assert(
        rel_err < 1e-5,
        f"regularized JMLE gradient check failed: rel_err={rel_err:.3e}, abs_err={abs_err:.3e}",
    )

    for bad_spec, expected_text in (
        ([{"Facet": "Rater", "Level": "*", "SD": 0.0}], "SD must be positive"),
        ([{"Facet": "NotAFacet", "Level": "*", "SD": 1.0}], "unknown facet"),
        ([{"Facet": "Rater", "Level": "NotALevel", "SD": 1.0}], "unknown level"),
    ):
        try:
            mfrm_estimate(
                data,
                person_col="Person",
                facet_cols=["Rater", "Task"],
                score_col="Score",
                model="RSM",
                method="JMLE",
                facet_regularization=bad_spec,
                maxit=2,
                reltol=1e-3,
            )
        except ValueError as exc:
            _self_test_assert(expected_text in str(exc), f"unexpected regularization error: {exc}")
        else:
            raise AssertionError(f"invalid regularization spec was accepted: {bad_spec}")


def _self_test_mfrmr_016_audits_and_shrinkage() -> None:
    data = pd.DataFrame({
        "Person": ["P1", "P1", "P2", "P2", "P3", "P3", "P4", "P4"],
        "Rater": ["R1", "R1", "R2", "R2", "R3", "R3", "R4", "R4"],
        "Task": ["T1", "T1", "T1", "T1", "T2", "T2", "T2", "T2"],
        "Score": [1, 2, 2, 3, 3, 4, 4, 5],
        "Weight": [1, 1, 1, 1, 2, 2, 2, 2],
    })
    audit = build_facet_sample_size_audit(data, ["Person", "Rater", "Task"], dummy_facets=["Task"])
    _self_test_assert(not audit.empty, "facet sample-size audit is empty")
    _self_test_assert("structural" in audit["SampleCategory"].astype(str).tolist(), "dummy facet was not marked structural")
    summary = summarize_facet_sample_size_audit(audit)
    _self_test_assert("SparseLevels" in summary.columns, "sample-size summary missing sparse count")

    nesting = build_facet_nesting_audit(data, ["Rater", "Task"])
    _self_test_assert(not nesting.empty, "nesting audit is empty")
    rater_to_task = nesting[(nesting["FacetA"] == "Rater") & (nesting["FacetB"] == "Task")]
    _self_test_assert(
        not rater_to_task.empty and float(rater_to_task["NestingIndex"].iloc[0]) > 0.9,
        "nested Rater -> Task relation was not detected",
    )

    design_effect = compute_intraclass_design_effect(data, ["Rater", "Task"], score_col="Score")
    _self_test_assert("IntraclassCorrelationClusterICC" in design_effect.columns, "cluster ICC column missing")
    _self_test_assert("DesignEffect" in design_effect.columns, "design effect column missing")

    measures = pd.DataFrame({
        "Facet": ["Rater", "Rater", "Rater", "Rater", "Task", "Task"],
        "Level": ["R1", "R2", "R3", "R4", "T1", "T2"],
        "Estimate": [-0.8, -0.2, 0.3, 0.7, -0.1, 0.1],
        "SE": [0.20, 0.30, 0.25, 0.35, 0.2, 0.2],
    })
    shrinkage = compute_empirical_bayes_shrinkage(measures)
    shr = shrinkage.get("measures", pd.DataFrame())
    _self_test_assert(shrinkage.get("available"), "EB shrinkage should be available")
    _self_test_assert({"ShrunkEstimate", "ShrunkSE", "ShrinkageFactor"}.issubset(shr.columns), "EB shrinkage columns missing")
    factors = pd.to_numeric(shr["ShrinkageFactor"], errors="coerce").dropna()
    _self_test_assert(bool(((factors >= 0) & (factors <= 1)).all()), "shrinkage factors outside [0, 1]")
    task_rows = shr[shr["Facet"].astype(str) == "Task"]
    _self_test_assert(
        bool(np.allclose(task_rows["Estimate"], task_rows["ShrunkEstimate"], equal_nan=True)),
        "K<3 facet should pass through without shrinkage",
    )


def _self_test_information_curve_contract() -> None:
    res = mfrm_estimate(
        _make_self_test_rating_data([1, 2, 3, 4] * 6),
        person_col="Person",
        facet_cols=["Rater", "Task"],
        score_col="Score",
        model="RSM",
        method="JMLE",
        maxit=20,
        reltol=1e-3,
    )
    bundle = build_information_curve_data(res)
    _self_test_assert(bundle.get("available"), "information curve unavailable")
    curve = bundle.get("curve", pd.DataFrame())
    _self_test_assert(not curve.empty, "information curve table is empty")
    _self_test_assert(bool((pd.to_numeric(curve["Information"], errors="coerce") >= 0).all()), "information must be nonnegative")
    export = information_curve_export_table(res)
    _self_test_assert(not export.empty and "ConditionalSE" in export.columns, "information curve export missing ConditionalSE")


def run_self_tests() -> int:
    tests = [
        ("zero-count intermediate category support", _self_test_zero_count_category_support),
        ("non-consecutive score recode", _self_test_nonconsecutive_recode),
        ("explicit boundary gap support", _self_test_boundary_gap_support),
        ("fractional score rejection", _self_test_fractional_score_rejection),
        ("JMLE RSM, PCM, and GPCM smoke", _self_test_jmle_rsm_pcm_smoke),
        ("analytical gradient checks", _self_test_gradient_checks),
        ("analysis-depth preset smoke", _self_test_analysis_depth_presets),
        ("MML Auto posterior, PCM/GPCM, and strict marginal", _self_test_mml_auto_posterior_and_marginal),
        ("MML engine branches and negative inputs", _self_test_mml_engine_branches_and_negative_inputs),
        ("latent regression population_formula", _self_test_latent_regression_population_formula),
        ("prediction simulation and design evaluation", _self_test_prediction_simulation_design),
        ("report readiness and method appendix", _self_test_report_readiness_and_method_appendix),
        ("visual interpretation checklist", _self_test_visual_interpretation_checklist),
        ("category probability curve data", _self_test_category_probability_curve_data),
        ("export bundle contents", _self_test_export_bundle_contents),
        ("anchor audit", _self_test_anchor_audit),
        ("script support boundaries", _self_test_script_support_boundaries),
        ("reproducibility fingerprints", _self_test_reproducibility_fingerprints),
        ("cached static assets and exports", _self_test_cached_static_assets_and_exports),
        ("cross-package validation plan", _self_test_cross_package_validation_plan),
        ("public beta release contract", _self_test_public_beta_release_contract),
        ("APA 7 reference list generator", _self_test_apa_reference_list),
        ("Word publication document builder", _self_test_publication_document_word),
        ("PDF publication document builder", _self_test_publication_document_pdf),
        ("Posterior Viewer loaders / plots", _self_test_posterior_viewer_loaders),
        ("Unified chart guide library", _self_test_chart_guide_library),
        ("Advanced-model Stan generators", _self_test_advanced_model_generators),
        ("Measure table rounding helper", _self_test_format_measure_table),
        ("Fit-column conditional styling", _self_test_style_fit_columns),
        ("MFRM quick-reference glossary", _self_test_mfrm_glossary),
        ("Measure column reordering", _self_test_reorder_measure_columns),
        ("HTML publication document builder", _self_test_publication_document_html),
        ("Estimation-error pattern matcher", _self_test_diagnose_estimation_error_patterns),
        ("Help popover library", _self_test_help_popover_library),
        ("Essential-mode tab filters", _self_test_essential_mode_tab_filters),
        ("Sample-data scenarios", _self_test_sample_data_scenarios),
        ("CSV newline normalization", _self_test_csv_newline_normalization),
        ("Table delimiter and stale-input fingerprints", _self_test_table_delimiter_and_stale_fingerprints),
        ("Likelihood information criteria", _self_test_likelihood_information_criteria),
        ("DFF bias screening", _self_test_dff_bias_screening),
        ("Facet regularization", _self_test_facet_regularization),
        ("mfrmr 0.1.6 audits and EB shrinkage", _self_test_mfrmr_016_audits_and_shrinkage),
        ("information curve contract", _self_test_information_curve_contract),
        ("Data-outlier detection", _self_test_data_outlier_detection),
        ("Posterior NetCDF round-trip", _self_test_posterior_load_netcdf),
        ("Posterior CmdStan CSV loader", _self_test_posterior_load_cmdstan_csvs),
        ("Config-JSON import whitelist", _self_test_config_json_import_whitelist),
        ("Run-history clear confirmation", _self_test_run_history_clear_confirmation),
    ]
    failures = []
    for name, test_func in tests:
        try:
            test_func()
            print(f"[PASS] {name}")
        except Exception as exc:
            failures.append((name, exc))
            print(f"[FAIL] {name}: {exc}")
    if failures:
        print(f"\n{len(failures)} self-test(s) failed.")
        return 1
    print(f"\nAll {len(tests)} self-tests passed.")
    return 0


# ---------------------------------------------------------------------------
# Unified chart interpretation guide (D3)
# ---------------------------------------------------------------------------
# Every diagnostic plot across the Visuals / Dimensionality / Wright Map
# sections ends up under a familiar ❓ "How to read this" expander rendered
# by render_chart_guide. Keeping the library in one place prevents the
# explanatory text from drifting between tabs.

_CHART_GUIDE_LIBRARY: dict[str, dict[str, str]] = {
    "wright_map": {
        "headline": "Wright Map — persons (left) vs item/facet elements (right) on a common logit scale.",
        "body": (
            "**How to read:** higher = more able persons / harder items. "
            "A healthy map has items spread across the person range (good "
            "targeting); items clustered above the person mean imply a test "
            "too hard, below imply too easy. Wright & Stone (1999) and "
            "Linacre (2024) call this the primary visual check."
        ),
    },
    "pathway_map": {
        "headline": "Pathway Map — measure on x-axis, Infit MnSq on y-axis, with element labels.",
        "body": (
            "**How to read:** points near y = 1.0 fit the Rasch expectation. "
            "Values > 1.4 indicate noisy (distorting) responses for that "
            "element; values < 0.6 indicate over-fit (Wright & Linacre, 1994)."
        ),
    },
    "category_probability": {
        "headline": "Category Probability Curves — probability of each response category vs latent trait.",
        "body": (
            "**How to read:** each curve should peak exclusively at some "
            "trait range, and all categories should be the most probable "
            "choice over some interval. Overlapping / dominated curves "
            "suggest an unused or redundant category (Linacre, 2004; "
            "Andrich, 1978)."
        ),
    },
    "threshold_map": {
        "headline": "Threshold Map — ordered step thresholds across elements.",
        "body": (
            "**How to read:** adjacent thresholds should increase "
            "monotonically. Disordered thresholds (a later step with a "
            "lower threshold) flag category misuse (Linacre, 2002)."
        ),
    },
    "icc": {
        "headline": "ICC — Item Characteristic Curve overlaying observed vs expected scores.",
        "body": (
            "**How to read:** the empirical (dots) should track the "
            "model-implied S-curve. Systematic departures indicate model "
            "misfit or multidimensionality."
        ),
    },
    "scree": {
        "headline": "Scree Plot — eigenvalues of the residual correlation matrix.",
        "body": (
            "**How to read:** the first eigenvalue < 2.0 supports "
            "unidimensionality; 2.0–3.0 is a grey zone; > 3.0 flags a "
            "strong secondary dimension. Eigenvalues of the residuals "
            "should then hover near 1.0 (Smith, 2002; Linacre, 2024)."
        ),
    },
    "facet_distribution": {
        "headline": "Facet Distribution — boxplots / strip plots of element measures by facet.",
        "body": (
            "**How to read:** compare the spread of each facet's measures. "
            "A facet with very tight measures contributes less to person "
            "ordering; very wide spread may warrant splitting."
        ),
    },
    "reliability": {
        "headline": "Reliability / Separation — separation index and Rasch reliability per facet.",
        "body": (
            "**How to read:** person separation ≥ 2 (reliability ≥ 0.80) "
            "is usually the floor for scoring decisions; ≥ 3 for higher "
            "stakes (Linacre, 2024). Non-person facets report the same "
            "quantities but interpret them as precision of the facet's "
            "element measures."
        ),
    },
    "rater_agreement": {
        "headline": "Rater Agreement — exact / adjacent percent agreement and κ.",
        "body": (
            "**How to read:** MFRM does not require high agreement; the "
            "model itself absorbs rater severity. Still, very low agreement "
            "(< 40% exact) combined with poor fit suggests rater-specific "
            "confusion (Myford & Wolfe, 2003)."
        ),
    },
    "posterior_trace": {
        "headline": "Trace Plot — chain-by-chain draws across iterations.",
        "body": (
            "**How to read:** chains should overlap and wander without "
            "trends (the hairy caterpillar). Separated or drifting chains "
            "imply non-mixing; Rhat ≥ 1.01 confirms it (Gelman & Rubin, 1992)."
        ),
    },
    "posterior_ridge": {
        "headline": "Ridge Plot — posterior densities stacked across parameters.",
        "body": (
            "**How to read:** compare shape and location at a glance. "
            "Bimodal / skewed densities often point to identifiability or "
            "prior-sensitivity issues (Kruschke, 2018)."
        ),
    },
}


